window.HB_TR["1-chronicles"]["ks"]=["1. آدم، شیٹھ، انوش،\n2. کینن، محلالیل، جیرڈ،\n3. ہینوک، میتھوسیلہ، لامیک،\n4. نوح، شیم، حام تہٕ یافتھ۔\n5. یافتھ سٕندِ نیٚچوۍ۔ گومر، تہٕ ماگوگ، تہٕ مدای، تہٕ جاوان، تہٕ توبل، تہٕ میشچ، تہٕ تیراس۔\n6. تہٕ گومر سٕندِ نیچو۔ اشچیناز، تہٕ ریفتھ، تہٕ ٹوگرمہ۔ {ریپھتھ: یا، دیفتھ یتھہ پاٹھۍ کینژن کاپٮن منز چھہ}\n7. تہٕ جاوان سٕندِ نیٚچوۍ۔ الیشاہ، تہٕ ترشیش، کِٹِم تہٕ ڈوڈنیم۔ {Dodanim: یا، Rodanim، کنہہ کاپیہٕ مطٲبق}\n8. ہیم سٕندۍ نیٚچو؛ کُش، تہٕ مزرایم، پُٹ تہٕ کنعان۔\n9. تہٕ کُش سٕندِ نیٚچوۍ۔ سیبا، تہٕ حویلہ، تہٕ سبتہ، تہٕ رامہ تہٕ سبتیچا۔ تہٕ رامہ سٕندِ نیٚچوۍ۔ شیبا، تہٕ ڈیڈن۔\n10.\\tتہٕ کُش زاو نمرود: سُہ ہیوٚتُن زمینس پیٹھ طاقتور بنُن۔\n11.\\tتہٕ مزریمن پیدہ لودیم، انامیم، تہٕ لہابیم تہٕ نفتوہیم،\n12.\\tپتھرُسم تہٕ کاسلوہِم، (یِمو منزٕ فلسطینی آیہِ) تہٕ کیفتھورِم۔\n13.\\tتہٕ کنعانن زاو زِدُن پنُن گۄڈنیُک زامُت، تہٕ ہیتھ،\n14. یبوسی تہِ، تہٕ اموری تہٕ گرگاشی،\n15. تہٕ حِویت، تہٕ آرکیت، تہٕ سِنائٹ،\n16.\\tتہٕ عرودیت، تہٕ زیماری تہٕ ہماتی۔\n17. شیم سٕندِ نیٚچوۍ۔ ایلام، تہٕ آشور، تہٕ ارفکساد، تہٕ لُد، تہٕ آرام، تہٕ عُز، تہٕ ہُل، تہٕ گیتھر، تہٕ میشچ۔ {میشچ: یا، ماش}\n18.\\tتہٕ ارفقسعد دیت شیلہ تہٕ شیلاہن زاے ایبر۔\n19.\\tتہٕ ایبرس زاے زٕ نیچوۍ: أکِس سُند ناو {اوس} پیلیگ۔ تکیازِ تٔمۍ سٕندِس دۅہس منز ٲس زمین تقسیم کرنہٕ آمٕژ: تہٕ تٔمۍ سٕندِس بٲے سُند ناو اوس جوکٹان۔ {پیلیگ: یعنی تقسیم}\n20.\\tتہٕ جوکتن زاے الموداد، تہٕ شیلف، تہٕ ہزارمویت تہٕ یراہ۔\n21.\\tہدورم تہِ، تہٕ اُزال، تہٕ دِکلاہ،\n22.\\tتہٕ ایبال، تہٕ ابیمیل تہٕ شیبا،\n23. تہٕ اوفیر، تہٕ حویلہ تہٕ جوباب۔ یم سٲری ٲسۍ جوکٹن سٕندۍ نیچوۍ۔\n24. شیم، ارپکساد، شیلہ،\n25. ایبر، پیلیگ، ریو،\n26. سیروگ، ناہور، تیرہ،\n27. ابرام۔ یۅہے {چھُ} ابراہیم۔\n28.\\tابراہیم سٕندِ نیٚچوۍ۔ اسحاق تہٕ اسماعیل۔\n29.\\tیِم چھِ تِہٕنزِ نسلہٕ: اسماعیل سُند گۄڈنیُک زامُت، نبایوت۔ پتہٕ کیدار، تہٕ عدبیل، تہٕ مِبسام،\n30. مشما، تہٕ دومہ، ماسا، حداد تہٕ تیما، {حداد: تہٕ وَننہٕ یوان، حضر}\n31. جیتور، نپھش تہٕ کیدیمہ۔ یِم چھِ اسماعیل سٕندِ نیٚچِوۍ۔\n32.\\tوۅنۍ کتورہ سٕندِس نیچوۍ، یُس ابراہیم سٕنزِ لونڈی: أمِس زیٚو زِمران، تہٕ جوکشَن، تہٕ مدان، تہٕ مدیان، تہٕ اِشباق تہٕ شواہ۔ تہٕ جوکشن سٕندۍ نیچو۔ شیبا، تہٕ ڈیڈن۔\n33.\\tتہٕ مدیانٕکۍ نیٚچوۍ۔ ایفاہ، تہٕ ایفر، تہٕ ہینوک، تہٕ عابدہ، تہٕ ایلداہ۔ یم سٲری {چِھ} کتورا سٕندِ نیچوۍ۔\n34. تہٕ ابراہیم زاے اسحاق ۔ اسحاق سٕندۍ نیٚچوۍ؛ عیسو تہٕ اسرائیل۔\n35. عیسو سٕندۍ نیٚچوۍ۔ الیفاز، ریوئل، تہٕ عیسیٰ تہٕ جلم، تہٕ کورہ۔\n36.\\tالیفاز سٕندِ نیچو۔ تیمان، تہٕ عمر، زیفی، تہٕ گتام، کیناز تہٕ تیمنا، تہٕ امالیک۔ {زیفی: یا، زیفو}\n37. ریویل سٕندۍ نیٚچوۍ۔ نہات، زراہ، شمہ تہٕ مِزہ۔\n38.\\tتہٕ سیر سٕندِ نیٚچوۍ۔ لوتان، تہٕ شوبل، تہٕ زیبیون، تہٕ عناہ، تہٕ دیشون، تہٕ ایزر، تہٕ دیشان۔\n39.\\tتہٕ لوٹن سٕندِ نیچو۔ ہوری، تہٕ ہومم: تہٕ تیمنا ٲس لوٹن سنز بینہٕ۔ {ہوم: یا، ہیمام}\n40.\\tشوبل سٕندۍ نیٚچوۍ۔ الیان، تہٕ مناہتھ، تہٕ ایبل، شیفی تہٕ اونم۔ تہٕ زِبیونٕکۍ نیٚچوۍ۔ آیاہ، تہٕ آناہ۔ {الیان: تہِ ونان چھِ، الوان} {شیفی: شیفو تہِ ونان چھِ}\n41.\\tآنا سٕندِ نیٚچوۍ۔ ڈشون۔ تہٕ ڈِشَن سٕندِ نیچِو؛ امرام، تہٕ اشبان، تہٕ اِتھران تہٕ چیران۔ {امرام: یا، ہیمدان}\n42. ایزر سٕندۍ نیٚچوۍ۔ بلہان تہٕ زاوان، {تہٕ} جاکان۔ دیشان سٕنٛدۍ نیٚچوۍ؛ اُز تہٕ آران۔ {جاکان: یا، اکان}\n43.\\tوۅنۍ چھہِ یم بادشاہ یِم حضرت عیدوم کِس سرزمینس مَنٛز بادشاہت کٔرِتھ ٲسۍ۔ بیور سُند نیچو بیلا: تہٕ تٔمۍ سٕندِ شہرُک ناو اوس دینہابا۔\n44.\\tتہٕ ییلہ بیلہ مٔرۍ، بوزرہ کِس زرہ سُند نیچو جوباب کٔر أمِس بدلہٕ حکومت۔\n45.\\tتہٕ ییلہ جوباب مٔرۍ، تِمن ہٕندِس زمینہٕ ہُند حشام کٔر أمِس بدلہٕ حکوٗمت۔\n46.\\tتہٕ ییلہ حشام مٔرۍ، بیداد سُند نیچو حداد، یُس موآب کِس میدانس مَنٛز مدیانس ماران اوس، تٔمۍ سٕندِ بدلہٕ کٔر حُکوٗمت: تہٕ تٔمۍ سٕندِس شہرُک ناو اوس اویتھ۔\n47.\\tتہ ییلہ حداد فوت سپد تہ مصیرہ سند سملہ کٔر تمۍ سندِ جایہ حکومت۔\n48.\\tییلہ سملہ مرُن، دریاوس نکھہ رہوبوتُک شاؤل اوس تٔمۍ سٕنزِ جایہ حکومت۔\n49.\\tتہٕ ییلہ شاؤل مٔرۍ، اَچبور سُند نیچو بعلحنن کٔر أمِس بدلہٕ حُکوٗمت۔\n50.\\tتہٕ ییلہ بعلحنان مٔرۍ، حدادن کٔر أمِس بدلہٕ حُکوٗمت: تہٕ تٔمۍ سٕندِس شہرُک ناو اوس پای۔ تہٕ تٔمۍ سٕنزِ زنانہِ ہُند ناو اوس محتابل، یۄس میزاہاب سٕنز کورِ ماترید سٕنز کوٗر ٲس۔ {حداد: یا، حدار} {پائی: یا، پاو}\n51.\\tحداد تہِ گٔیہ۔ تہٕ ایڈومٕکۍ ڈیوک ٲسۍ۔ ڈیوک ٹمناہ، ڈیوک عالیہ، ڈیوک جیتھیتھ،\n52. ڈیوک اہولیبامہ، ڈیوک ایلاہ، ڈیوک پینن،\n53. ڈیوک کیناز، ڈیوک ٹیمان، ڈیوک مِبزار،\n54. ڈیوک میگدیل، ڈیوک ارام۔ یم {چِھ} ایڈومٕکۍ ڈیوک۔","1. یِم چھِ اسرٲیلٕکۍ نیٚچوۍ۔ روبن، شمعان، لیوی تہٕ یہوداہ، عیساکر، تہٕ زبولون، {اسرائیل: یا، یعقوب}\n2. ڈین، جوزف، تہٕ بینجمن، نفتالی، گاڈ تہٕ آشر۔\n3. یہوداہ سٕندِ نیٚچوۍ؛ اِر، تہٕ اونان، تہٕ شیلہٕ: {یُس} تٔمِس زاے شوع کنعانی سٕنزِ کورِ ہٕندِس سٍتـ̡ ۔ تہٕ یہوداہ سُند گۄڈنیُک زامُت، اوس خداوند سٕندِ نظرِ منز بُرۍ۔ تہٕ تٔمۍ مور سُہ ۔\n4.\\tتہٕ تمر، تٔمۍ سٕنزِ نوٗر زاے تس فریز تہٕ زِرہ۔ یہوداہ سٕندِ سٲری نیچوۍ ٲسۍ پانژھ۔\n5. فریز سٕنٛدۍ نیٚچوۍ۔ ہیزرون تہٕ ہمول۔\n6. تہٕ زراح سٕندِ نیٚچو۔ زمری، تہٕ ایتھن، تہٕ ہیمن، تہٕ کیلکول، تہٕ دارا: کل پانژھ۔ {زمری: یا، زبدی} {دارا: یا، دردا}\n7. تہٕ کارمی سٕندۍ نیٚچوۍ۔ اچار، اسرٲیلُک پریشان کرُن، یُس لعنتی چیزس مَنٛز خلاف ورزی کٔر۔ {اچار: یا، اچن}\n8. تہٕ ایتھن سٕندِ نیٚچوۍ۔ عزریہ۔\n9.\\tہیزرون سٕندِ نیچوۍ تہِ، یِم أمِس زامٕتۍ ٲسۍ۔ جَرَہمیٖل، تہٕ رام تہٕ چیلوبائی۔ {رام: گر. آرام} {چیلوبائی: یا، کالب}\n10.\\tتہٕ رام زاو امینادب۔ تہٕ امیناڈاب زاو یہوداہ کین بچن ہُند شہزادٕ نہشون۔\n11.\\tتہ ناہشون پیدہ سلمیٰ تہ سلمیٰ پیدہ بوعز، {سلمیٰ: یتھ تہِ وَننہٕ یوان چھُ}\n12.\\tتہٕ بواز پیوو عبید تہٕ عبیدن پیوو یسی،\n13.\\tتہٕ یسیٰ زاو پنُن گۅڈنیُک الیاب، تہٕ ابینادب دوٚیِم تہٕ شِمہ دِژ تریم {شِما: یا شمہ}\n14. نیتھانیل ژورم، ردایی پانژم،\n15.\\tاوزم شیم، ڈیوڈ سٔتِم:\n16.\\tیمۍ سٕنزِ بینہٕ زرویاہ تہٕ ابیگیل۔ تہٕ زرویاہ سٕندِ نیچو۔ ابیشایی تہٕ جوآب تہٕ اساہیل، ترےٚ۔\n17. تہٕ ابیگیل بارے اماسا: تہٕ اماسا سُند مول اوس جیتھر اسماعیلِٹ۔ {یتھر...: یتھ تہِ ونان چھِ، اِتھرا اِسرٲیلِی}\n18.\\tتہٕ حضرون سُند نیچو کالب زاے ازوبہ سٕنزِ زنانہٕ تہٕ یریوتھ سٕندِس نیچوِس {بچہ}۔ جیشر، تہٕ شوباب، تہٕ آرڈن۔\n19.\\tییلہ ازوبہ مٔرۍ، کالبن نِیوو أمِس نِش افرات، ییمہ سٍتـ̡ أمِس ہُر پییہِ۔\n20.\\tتہٕ حُرن زاے اُری تہٕ اُری زاے بیزلیل۔\n21.\\tتہٕ امہ پتہ گۆو حسرون جلعاد سٕندِس مٲلِس ماخر سٕنزِ کورِ نِش، یٔمِس سٍتـ̡ تٔمِس تریہ وُہُر وٲنسہِ سٍتـ̡ خاندر کٔر۔ تہٕ تٔمۍ کٔر أمس سیگب۔ {خانٛدر: ہیب۔ ٹُک}\n22.\\tتہٕ سیگوبَن زاو جیر، یٔمِس گلعاد کِس سرزمینس مَنٛز ترے تہٕ وُہ شہر ٲسۍ۔\n23.\\tتہٕ تٔمۍ نیو گیشور تہٕ آرام، یِمن نِش کِناتھ تہٕ تِمن ہٕندِس قصبس سٍتۍ، تریہ شَہَر شہر۔ یِم سارِنٕے ٲسۍ جلعاد سٕندِس مٲلِس مخیر سٕندِس نیچوِس سٍتـ̡ ۔\n24.\\tتہٕ تمہ پتہ اوس حسرون کالبفراتاہ مَنٛز موٗدمُت، تمہ پتہٕ دیت ابیا حزرون سٕنزِ زنانہِ تِقعہ سُند مول عاشور۔\n25.\\tحضرت یرحمیل سٕندِ نیچوۍ یُس حضرت حسرون سُند گۅڈٕ زامُت اوس، رام تہٕ بونہٕ تہٕ اورن تہٕ عزیم، {تہٕ} احیجاہ۔\n26.\\tیرحمیلس ٲس بیاکھ زنانہ تہِ، یمۍ سُند ناو عطارہ اوس۔ سۅ ٲس اونم سنز موج۔\n27.\\tتہٕ رام سٕندِ نیچوۍ یُس یرحمیل سُند گۄڈنیُک زامُت اوس، معذ تہٕ جامن تہٕ ایکر۔\n28.\\tتہٕ اونم سٕندِ نیچوۍ ٲسۍ شمایی تہٕ جادا۔ تہٕ شامایی سٕندِ نیچوۍ۔ نداب تہٕ ابیشور۔\n29.\\tتہٕ ابیشور سٕنزِ زنانہِ ہُند ناو اوس ابیحیل، تہٕ تٔمِس اوس احبان تہٕ مولِد۔\n30.\\tتہٕ نداب سٕندِس نیٚچوۍ۔ سیلیڈ، تہٕ اپیم: مگر سیلیڈ موٗد بچہٕ ورٲے۔\n31. تہٕ اپییم سٕندِ نیٚچوۍ۔ ایشی۔ تہٕ ایشی سٕندِ نیچو؛ شیشان۔ تہٕ شیشان سٕندِ شُرۍ۔ اہلائی۔\n32.\\tتہٕ شمایی سُند بٲے جادا سٕندِ نیچوۍ۔ جیتھر تہٕ جوناتھن: تہٕ جیتھر موٗد شُرۍ ورٲے۔\n33. تہٕ جوناتھن سٕندِ نیچوۍ۔ پیلتھ تہٕ زازا۔ یِم ٲسۍ یرحمیل سٕندِ نیچِوۍ۔\n34.\\tوۅنۍ ٲسۍ نہ شیشنس نیچوۍ بلکہ کورِ۔ تہٕ شیشان اوس اکھ نوکر، اکھ مصری، ییٚمۍ سُنٛد ناو اوس جارہا۔\n35.\\tتہٕ شیشَن دِژ پنٕنۍ کورِ جارہَس پنٕنۍ خادم۔ تہٕ سۅ کٔر أمِس اتایی نِش۔\n36.\\tتہٕ عتایی زاو ناتھن، تہٕ ناتھن زبد،\n37.\\tتہ زباد پیدہ افلال تہ افلال پیدہ عبید۔\n38.\\tتہٕ عوبَن دِژ یہو، تہٕ یہوَن دِژ عزریہ،\n39.\\tتہٕ عزریاہ دیت ہیلیز تہٕ ہیلیزن پیوو الیاسہ،\n40.\\tتہٕ الیاسہ دیت سیسمایی تہٕ سیسمایی پیدہ شلوم،\n41.\\tتہٕ شلمن زاے یکامیاہ تہٕ یکامیاہ پیوو الیشماہ۔\n42.\\tوۅنۍ اوس کالب سٕندِ نیچوۍ، یُس یرحمیل سُند بوے اوس، میشا اوس تٔمِس گۅڈنیُک زامُت، یُس زِپھ سُند مول اوس۔ تہٕ ہیبرون سُند مول مریشہ سٕندِ نیچوۍ۔\n43. تہٕ ہیبرون سٕندِ نیچو۔ کورہ، تہٕ تپواہ، تہٕ رکیم، تہٕ شیما۔\n44.\\tتہٕ شمعہ زاے زاے یُس جورکوم سُند مول اوس رحم۔\n45.\\tتہٕ شمعی سُند نیچو اوس ماون: تہٕ معون اوس بیت زورُک مول۔\n46.\\tتہٕ ایفاہ، کالب سٕنز لونڈی، ننگی ہاران، تہٕ موزہ، تہٕ گزیز: تہٕ ہارن پیوو گزیز۔\n47.\\tتہٕ جہدایی سٕندِ نیچو۔ ریجم، تہٕ جوتھم، تہٕ گیشان، تہٕ پیلٹ، تہٕ ایفاہ، تہٕ شاف۔\n48.\\tماچہ، کالب سنز لونڈی، ننگی شیبر تہٕ ترہناہ۔\n49.\\tأمِس زاے شاف، مدمناہ سُند مول، شیوا یُس مچبیناہ سُند مول اوس، تہٕ گِبیہ سُند مول تہٕ کالب سٕنز کورِ ٲس۔\n50. یِم ٲسۍ افراتہ سُند گۅڈٕ زامُت حُر سُند نیچو کالب۔ شوبل، کرجاتجیریم سُند مول، {افراتا: یتھ افرتھ تہِ ونان چھِ}\n51. سلمیٰ بیت اللحمُک مول، بیت اللحمُک مول حرف۔\n52.\\tتہٕ شوبل، کِرجاتجیرِم سٕندِس مٲلِس زاے نیٚچِوۍ۔ ہاروہ، {تہٕ} نصف مناہیتھیٹس۔ {ہاروہ: یا، ریایہ} {نصف...: یا، نصف مینوچیٹس، یا، ہٹسیہمینوچوتھ}\n53.\\tتہٕ کِرجاتجیرِم سٕندِ خاندان۔ اتھرائٹس، تہٕ پُہیت، تہٕ شومتھی، تہٕ مشرائیٹس؛ تمن منٛز آیہٕ زراتھیٹس تہٕ ایشٹالائٹس ۔\n54.\\tسلمیٰ سٕندِس نیٚچوۍ۔ بیت لحم، تہٕ نیتوفاتھیس، عطاروتھ، یوآب سُند گرٕ تہٕ نصف منحیتھی، زوریت۔ {Ataroth...: یا، Atarites، یا، Joab سٕندِ گرٕکۍ تاج}\n55.\\tتہٕ یِمن کاتبن ہٕندِ خاندانہٕ یِم جابیزس منز روزان ٲسۍ۔ تیراتھی، شیمتی، {تہٕ} سوچاتھی۔ یم چھہِ تِم کینیٹس یُس ریچاب سٕندِس گرُک مول ہیمتھ سٕندِ سٍتـ̡ آمُت چھُ۔","1. وۅنۍ ٲسۍ یِم داؤد سٕندِ نیچوۍ، یِم أمِس ہیبرونس مَنٛز زامٕتۍ ٲسۍ۔ گۄڈنیُک زامُت امنون، اہنوام دی یزریلیٹس؛ دوٚیِم دانیال، ابیگیل دی کارمیلیٹس: {Daniel: or, Chileab}\n2. تریم ابسالوم یُس گیشور کِس بادشاہ تلمایی سٕنز کورِ چھُ، ژوٗرِم، ادونیاہ سُند نیچو:\n3.\\tپانژم، شیفتیہ ابیتل: شیم، اِتھریم تٔمۍ سٕنزِ زنانہِ ایگلہ۔\n4. {یِم} شیہ زامٕے أمِس ہیبرونس مَنٛز۔ تہٕ تتہِ کٔر تٔمۍ سَتن ؤرین تہٕ شیٚن رٮ۪تن حکومت: تہٕ یروشلمس مَنٛز کٔر تٔمۍ ترٕہ ترہن ؤرین حکومت۔\n5. تہٕ یِم زاے أمِس یروشلمس مَنٛز۔ شیمیع، تہٕ شوباب، تہٕ ناتھن، تہٕ سُلیمان، ژور وُہُر، بَتشوع سٕنز کوٗر یُس امیعیٰ سٕنز کورِ: {شِمیعہ: یا، شموعہ} {بَتشوع: یا، بَتشیبا} {عمیع: یا، الیام}\n6.\\tاِبہار تہِ، تہٕ اِلِشامہ تہٕ اِلِفلیٹ، {اِلِشامہ: یَتھ تہِ وَننہٕ چُھ یِوان، اِلیشوا}\n7. تہٕ نوگاہ، تہٕ نیفیگ، تہٕ یافیہ،\n8.\\tتہٕ الیشامہ، تہٕ الیاڈا، تہٕ ایلیفلیٹ، نو۔ {الیاڈا: یا، بیلیاڈا}\n9. {یِم ٲسۍ داؤد سٕندِ سٲری نیچوۍ، لونڈین ہٕندِس نیچوِس علاوٕ، تہٕ تمر تہٕ تِہٕنزِ بینہِ۔\n10.\\tتہٕ سُلیمان سُند نیچو {اوس} رحبعام، عبیا تٔمۍ سُند نیچو، آسا تٔمۍ سُند نیچو، یہوشفات تٔمۍ سُند نیچو، {ابیا: یا، ابیجام}\n11.\\tیورَم سُند نیٚچُو، اَحزیاہ تٔمِس نیچو، یُس یُس نیچو یُس نیچو اوس، یُس اَحزیاہ اوس، یُس یُس نیچو اوس، یُس یُس اَحزیاہ اوس، یُس اَزَریاہ سُند\n12.\\tاَمزیاہَس سُند نیٚچُو، عزریاہ پُسُند نیچو، یوتھم سُند نیچو {عزریہ: یا عُزِیاہ}\n13.\\tاحض تسند نیچو، حزقیاہ پنن نیچو، مناسیٰ پنن نیچو،\n14. امون تسند نیچو، جوسیا تسند نیچو۔\n15.\\tتہٕ یوسیاہ سٕندِ نیچوۍ، گۅڈنیُک جوحان، دۆیم یہویاکیم، تریم زدقیاہ، ژوٗرِم شلوم۔ {جوہانان: یا، یہوہاز} {یہویاکیم: یا، الیاکیم} {زدیکیاہ: یا، متانیا}\n16.\\tتہٕ یہویاکیٖم سٕندِ نیچو: یکونیاہ تٔمۍ سُند نیٚچُو، زدیقیاہ تٔمۍ سُند نیچو۔ {جیکونیا: یتھ تہِ ونان چھِ، یہویاچین یا کونیاہ}\n17. تہٕ یکونیاہ سٕندِ نیٚچوۍ۔ آسیر، سلتھیل تٔمۍ سُند نیچو، {سلتھیل: ہیب۔ شیلٹیل}\n18.\\tملچیرام تہِ، تہٕ پیدایہ، تہٕ شینزار، یکیمیاہ، ہوشما، تہٕ ندبیاہ۔\n19.\\tتہٕ پیدایاہ سٕندِ نیچوۍ، زروبابل تہٕ شِمیعی، تہٕ زروبابل سٕندِ نیٚچِوۍ۔ مشُلَم، حَنانیاہ تہٕ شیلومِتھ تہٕ تِہٕنٛز بیٚنہِ:\n20.\\tتہٕ ہشوبہ، تہٕ اوہیل، تہٕ بریکیاہ، تہٕ حسادیہ، جوشابھیسید، پانژھ۔\n21. تہٕ حنانیاہ سٕندِ نیچو۔ پیلاتیا تہٕ یسعیاہ: رفعیاہ سٕندۍ نیچوۍ، ارنان سٕندۍ نیچۍ، عوبیاہ سٕندۍ نیچوۍ، شیخانیاہ سٕندۍ نیچو۔\n22.\\tتہٕ شیخانیہ سٕندِ نیٚچوۍ۔ شمعیہ: تہٕ شمعیاہ سٕندِ نیچو۔ ہتوش، تہٕ ایجیل، تہٕ بریہ، تہٕ نیریاہ، تہٕ شافات، شیہ۔\n23. تہٕ نیریاہ سٕندِ نیچو۔ ایلیونایی تہٕ حزقیاہ تہٕ عزریکام، ترۍ۔ {حزقیاہ: حب۔ ہسکیجاہ}\n24.\\tتہٕ الیوئنائی سٕندِ نیچوۍ، ہودیاہ تہٕ الیاشیب، تہٕ پیلاہ، تہٕ عکوب تہٕ جوہانان، تہٕ دالیہ، تہٕ عنانی، ستھ۔","1. یہوداہ سٕندِ نیٚچوۍ؛ فراز، ہیزرون، تہٕ کارمی، تہٕ ہُر، تہٕ شوبل۔ {کارمی: چیلوبائی یا کالب تہِ ونان چھِ}\n2.\\tتہٕ شوبل سُند نیچو ریعیاہ زاو جہات۔ تہٕ جہاتن زاے اہومائی تہٕ لہاد۔ یم {چِھ} زوراتھین ہند خاندان۔ {ریایہ: یا، ہاروہ}\n3.\\tتہٕ یِم ٲسۍ عتامُک مول ۔ یِزریل، تہٕ اِشمہ تہٕ اِدباش: تہٕ تِہٕنزِ بیٚنہِ ہُند ناو اوسُس حزلیلپونی:\n4.\\tتہٕ جدور سُند مول تہٕ عزیر ہوشاہ سُند مول۔ یِم چھِ بیت اللحمُک مول افراتہ سُند گۅڈنیُک نیٚچُو۔\n5.\\tتہٕ تیکوع سٕندِس مٲلِس عاشورَس ٲس زٕ خانٛدارِن، ہیلہ تہٕ نارہ۔\n6.\\tتہٕ نارہ دیت تس احوزم، تہٕ ہیفر، تہٕ تیمنی تہٕ ہاہشتاری۔ یِم ٲسۍ ناراہ سٕندِ نیٚچِوۍ۔\n7. تہٕ ہیلہ سٕندِ نیچوۍ، زرتھ تہٕ یزور، تہٕ ایتھنان۔\n8.\\tتہٕ کُز زاے انوب تہٕ زوبیبہ تہٕ ہارم سٕندِس نیچوِس اہرحیل سٕندِس خاندانس سٍتـ̡ زٲوِتھ۔\n9.\\tتہٕ جابیز اوس پننین باین کھوتہ زیادٕ عزتدار تہ تسٕنزِ ماجہ اوس تٔمِس جابیز ناو ونان زِ بہٕ چُھس تس غمس سٍتـ̡ دِوان۔ {جابیز: یعنی غم}\n10.\\tتہٕ جابیزن کٔر اسرٲیلِکِس خدایس مُتلق وَنُن، اے یێلہِ ژٕ کٔرِکھ میہ برکت تہٕ میٲنۍ بٔٹھِس بٔڑٲوِتھ تہٕ تُہُند اَتھٕ گژھہِ میہ سٍتـ̡ تہٕ یێلہِ ژے رژھ تہٕ خداین دیت تس سُہ یُس تٔمۍ درخواست کٔر۔ {اوہ...: ہیب۔ اگر ژیہ چاہِ، وغیرہ} {رژھرُن...: ہیب۔ مے کرو }\n11.\\tتہٕ شُوح سٕندِس بٲے چِلُب زاے مہیر، یُس اِشتون سُند مول اوس۔\n12.\\tتہٕ ایشٹن زاے بیت رافا تہٕ پاسہ تہٕ تہنہٕ یُس اِرنہاش سُند مول اوس۔ یم {چِھ} رِچاہٕکۍ مرد۔ {ارنہاش: یا، ناہش شہر}\n13. تہٕ کیناز سٕندِ نیچوۍ۔ اوتھنیل، تہٕ سریاہ: تہٕ اوتھنیل سٕندۍ نیٚچوۍ۔ ہتھاتھ۔ {ہتھاتھ...: یا، ہتھاتھ، تہٕ میونوتھائی، یُس پیدٕ کٔر، وغیرہ}\n14.\\tتہٕ میونوتھایی زاے عفرہ: تہٕ سریاہ زاو جوآب، یُس وادی چراشیم ہُند مول اوس۔ تکیازِ تم ٲسۍ کاریگر۔ {وادی: یا، وادی ہٕندِس بسکین} {چراشم: یعنی کاریگر} {ہتھاتھ...: یا، ہتھاتھ، تہٕ میونوتھائی، یُس پیدٕ کٔر، وغیرہ}\n15.\\tتہٕ یپھُنہٕ سُند نیچو کالب سٕندِس نیچو۔ عرو، الہ تہٕ نام: تہٕ ایلاہ سٕندۍ نیٚچوۍ، حتیٰ کہ کناز۔ {حتیٰ کہ کیناز: یا، اکناز}\n16.\\tتہٕ جہالیلیل سٕندِ نیچوۍ۔ زیف، تہٕ زیفاہ، تیریا تہٕ اساریل۔\n17.\\tعزرا سٕندِ نیچوۍ، یتھر تہٕ مرید، تہٕ ایفر تہٕ جالون۔ تہٕ أمِس زاے مریم، تہٕ شمایی تہٕ اشتہ سُند مول۔\n18.\\tتہٕ تٔمۍ سٕنزِ خانٛدارِنہِ یہودیجہ یٔژ گیدورُک مول تہٕ سوکو سُند مول ہیبر تہٕ زانواہ سُند مول جیکوتھیل۔ تہٕ یِم چھِ فرعون سٕنزِ کورِ بِتھیاہ سٕندِ نیچِوۍ، یُس میرڈن نِیومُت۔ {یہودیجاہ: یا، یہودی}\n19.\\tتہٕ یێمہِ سٕنزِ زنانہِ ہٕندِس نیچوِس ہودیاہ سٕنزِ بینہِ، یُس کیلہ گارمیٹ سُند مول اوس، تہٕ اِشتموعہ ماچتھِس سٍتـ̡ باپ ۔ {ہودیہ: یا، یہودیجاہ، یُس گۅڈہ وننہ آمت چھُ}\n20.\\tتہٕ شمعون سٕندِ نیچوۍ، امنون تہٕ رِناہ، بنہان تہٕ تیلون۔ تہٕ ایشی سٕندۍ نیچوۍ، زوہتھ تہٕ بینزوہتھ۔\n21.\\tیہوداہ سُند نیچو شیلہ سٕندِ نیچو، ایر لیکا سُند مول تہٕ لادہ سُند مول تہٕ تِمن ہٕندِس گرٕکۍ یِم اَصٕل کُن کُن بناوان ٲسۍ،\n22.\\tتہٕ جوکیم تہٕ چوزیبا ہٕندِس مرد، تہٕ یوآش تہٕ ساراف، یُس موآب تہٕ یشوبلحمس مَنٛز سلطنت اوس۔ تہٕ {یِم چھِ} قدیم چیز۔\n23.\\tیِم ٲسۍ کمہار تہٕ یِم کُلٮ۪ن تہٕ کُلٮ۪ن مَنٛز روزان ٲسۍ، تتہِ ٲسۍ تِم بادشاہس سٍتـ̡ تٔمۍ سٕنزِ کامہِ خٲطرٕ روزان۔\n24.\\tشمعون سٕندِ نیچوۍ، نیموئیل تہٕ جامین، جریب، زراہ، {تہٕ} شاؤل: {نموئیل: یا، یموئیل} {جریب، زَرہ: یا، یَچن زوہر}\n25.\\tشلم تسند نیچو، مِبسام تسند نیچو، مشما۔\n26. تہٕ مشماع سٕندِ نیٚچوۍ۔ ہیموئیل اوس تٔمۍ سُنٛد نیٚچُو، زَکُر تٔمۍ سُنٛد نیٚچُو، شیمی أمۍ سُنٛد نیٚچُو۔\n27.\\tتہٕ شِمعی یَس زاے شُراہ نیچوۍ تہٕ شےٚ کورِ۔ مگر تٔمۍ سٕندٮ۪ن باین ٲسۍ نہٕ واریاہ شُرۍ، تہٕ نہ اوس تِہُند سارِوٕے عیال یہوداہ کین شُرین ہٕندۍ پٲٹھۍ۔ {یِتھ کٔنۍ...: ہیب۔ unto}\n28.\\tتہٕ تِم ٲسۍ بیرشیبع، مولادہ تہٕ ہزارشوالَس مَنٛز روزان۔\n29.\\tتہٕ بلہاہس منز، تہٕ عزمس منز، تہٕ تولاڈس پیٹھ، {بلحا: یا، بلہ} {تولاد: یا، ایلٹولاد}\n30.\\tتہٕ بیتھوایلس منز، تہٕ ہورمہِ منز، تہٕ زِکلاگس منز،\n31.\\tتہٕ بیت مارکبوت، تہٕ ہزارسوسم، تہٕ بیت بیری تہٕ شارایمس مَنٛز۔ یم ٲسۍ داؤد سٕندِس دورس تام تہندِ شہر۔ {Hazarsusim: یا، Hazarsusah}\n32.\\tتہٕ تِہٕندِس گامَس {ٲس}، ایتام، تہٕ عین، رِمون، تہٕ توچن، تہٕ آشان، پانژھ شہر: {Etam: or, Ether}\n33.\\tتہٕ تِہٕندِ سارِنٕے گام یِم اَمی شہرَن اندۍ پٔکھۍ بعلس تام ٲسۍ۔ یم ٲسۍ تہنز رہائش گاہ، تہٕ تہند شجرہ۔ {بعل: یا، بعلتھ بیر} {تہند شجرہ: یا، یتھ کٔنۍ تمو پنن پان قومن ذریعہٕ تقسیم کٔرتھ}\n34.\\tتہٕ میشوباب تہٕ جملک تہٕ یُس امازیہ سُند نیچو یوشاہ اوس،\n35.\\tتہٕ یوسیاہ سُند نیٚچُو، یُس سریاہ سُند نیٚچُو، یُس اسِیل سُند نیٚچُو،\n36.\\tتہٕ ایلیونی، تہٕ یعقوبہ، تہٕ یشوحیاہ، تہٕ عسیٰ، تہٕ عدیل، تہٕ یسیمیئل، تہٕ بنیاہ،\n37. تہٕ زیزا شیفی سُند نیچو، علون سُند نیچو، یُس شیمیاہ سُند نیچو اوس، شمعیاہ سُند نیچو۔\n38.\\tیِمن ہُند ذِکر {تِہُند} ناوٕ سٍتۍ کرنہٕ آمُت اوس تہٕ تِہندین مٲلن ہٕندِس گرس منز ہُریوو واریاہ زیادٕ۔ {ذکر: ہیب۔ یِوان}\n39. تہٕ تِم گٔیہِ گیدور کِس دروازس پیٹھ، یُس وادی ہٕندِس مشرقس کُن تہِ اوس، پننین چارن خٲطرٕ چراگاہ ژھارنہٕ خٲطرٕ۔\n40.\\tتہٕ تِمو لٔبِتھ موٚٹۍ چراگاہ تہٕ اَصٕل تہٕ زمین ٲس کُنہِ تہٕ سُکوٗن۔ تکیازِ ہامکۍ {تِم} ٲسۍ پرانہِ کالہِ اتہِ روزان۔\n41.\\tتہٕ یِم ناو لیکھنہٕ آمٕتۍ یِم یہوداہ کِس بادشاہ حزقیاہ سٕندِس زمانس مَنٛز آیہ، تہٕ یِمن ہٕندِس خیمہ تہٕ یِم بستی لبنہٕ آمٕژ ٲس، تہٕ یِم کٔرِکھ از تام تِمن ہٕندِس کمرس مَنٛز روزان، تکیازِ تِمن ہٕندِس دامنس خٲطرٕ اوس مرگہٕ۔\n42.\\tتہٕ یِمو منزٕ گٔیہِ شمعون سٕندِس نیچویو سٍتـ̡ پانژھ ہتھ نفر سعیرس کُن کُنہِ کُنہِ سٍتـ̡ تہٕ یِمن ہٕندِس کپتانن ہٕندِ خٲطرٕ ٲسٕکھ پیلاطیہ، تہٕ نیریہ، تہٕ رفعیہ تہٕ عزیێل یِم عیشی سٕندِ نیچوۍ۔\n43.\\tتہٕ تِمو دِژ باقٕے امالیکین یِم ژٔلِتھ ژٔلِتھ تہٕ از تام روٗدۍ اَتہِ روزان۔","1. وۅنۍ چھہ روبن سٕندِ نیچوۍ، یُس اسرٲیلُک گۅڈنیُک زامُت اوس، (تکیازِ سُہ اوس گۅڈنیُک زامُت، مگر یێلہِ تٔمۍ پننِس مٲلہِ سٕندِس بسترس ناپاک کٔر، تٔمۍ سُند پیدائشی حق آو یوسف سٕندِس نیچوِس دِنہٕ، تہٕ شجرہ سٍتـ̡ گژھہِ نہٕ پیدائشہٕ سٍتـ̡ شمار کرنہٕ یُن۔\n2. تکیازِ یہوداہ اوس پننین باین پیٹھ، تہٕ أمس سٍتـ̡ آو سردار حکمران۔ مگر پیدائشی حق {اوس} جوزف سُند:) {سردار...: یا، شہزادہ}\n3.\\tروبن سٕندِ نیچوۍ، {بہٕ چُھس ونان}، یُس اسرٲیلُک گۄڈنیُک زامُت اوس، حنوخ، تہٕ پلو، حزرون تہٕ کارمی۔\n4. جوئل سٕندۍ نیٚچوۍ۔ شمعیاہ تسند نیچو، گوگ پنن نیچو، شمعیہ پنن نیچو،\n5.\\tمیکاہ سُند نیچو، ریعیاہ تسند نیچو، بعل تسند نیچو،\n6. بیرہ تٔمۍ سُند نیچو، یُس اسریاہُک بادشاہ ٹلگاپِلنیسر نِش نِیومُت: سُہ اوس روبینن ہُند شہزادٕ۔ {Tilgathpilneser: تہٕ چُھ ونان، Tiglathpileser}\n7.\\tتہٕ تٔمۍ سٕندِس بٲے یێلہِ تِہٕندِس خاندانس سٍتـ̡ یێلہِ تِمن ہٕندِس نسب سٍتـ̡ شمار کرنہٕ ییہِ، یێلہِ أسـ̡ سردار، یێل تہٕ زکریا\n8.\\tتہٕ بیلا یُس عزاز سُند نیچو اوس، یُس یُس عرورس مَنٛز روزان اوس، حتیٰ کہ نیبو تہٕ بعلمونس تام تہِ: {شیما: یا، شمیعہ}\n9.\\tتہٕ مشرق کُن رود سُہ دریائے فرات کِس بیابانس منز اژنس تام بسان۔\n10.\\tتہٕ ساؤل سٕندِس دۅہس مَنٛز کٔر تِمو ہجرِین سٍتـ̡ جنگ، یِم تِہٕندِس اتھہٕ سٍتـ̡ پۯاونہٕ آمٕتۍ۔ {پورٕ پٲٹھۍ...: ہیب۔ مشرق کِس سارِنٕے بُتھِس پیٹھ}\n11.\\tتہٕ گاد سٕندِ اولادٕ گٔیہِ تِمن خلاف باشان کِس سرزمینس مَنٛز سلچہ تام۔\n12.\\tیوایل سردار تہٕ شافام بیاکھ تہٕ جانائی تہٕ شافعت۔\n13.\\tتہٕ تِہٕندِس مٲلِس سٕندِس گرس ہٕندِس بٲے، میکائیل تہٕ مشُلم، تہٕ شیبا، تہٕ جورائی، تہٕ یچان، تہٕ ضیاء، تہٕ ہیبر، سَتھ۔\n14.\\tیِم چھہِ ابیحیل سٕندِ نیچو، حوری سُند نیچو، جاروہُک نیچو، جلعاد سُند نیچو، میکائیل سُند نیچو، یشیشایی سُند نیچو، جہدو سُند نیچو، بوز سُند نیچو۔\n15.\\tاحی یُس گُنی سُند نیچو اوس، یُس تِمن ہٕندِس مٲلن ہٕندِس گرُک سردار اوس۔\n16.\\tتہٕ تِم ٲسۍ بشانس مَنٛز گلعادس مَنٛز، تہٕ تٔمۍ سٕندِس شہرن مَنٛز، تہٕ شیرون کِس سارنٕے مضافاتس مَنٛز، تِمن ہٕندِس سرحدس پیٹھ روزان۔ {تِہُند...: ہیب۔ تہند برونٹھ کُن}\n17.\\tیِم سارِنٕے ٲسۍ یہوداہ کِس بادشاہ یوتام سٕندِس زمانس مَنٛز تہٕ اسرٲیلِکِس بادشاہ یربعام سٕندِس زمانس مَنٛز شجرہ نسب سٍتـ̡ شمار کرنہٕ آمٕتۍ۔\n18.\\tروبن سٕندِ نیچوۍ، تہٕ گادِس تہٕ مانسیہٕکۍ نصف قبیلہٕ، بہادر نفرن ہٕندِس نیچوۍ، یِم بکلر تہٕ تلوار رٔٹِتھ تہٕ کمانہٕ سٍتـ̡ گولہٕ چلاونس لایق ٲسۍ، تہٕ جنگس مَنٛز ہنرمند ٲسۍ، ژور تہٕ ژتٲجی ساس ستھ ہتھ ترےٚ، یِم جنگس مَنٛز درٛاو۔ {بہادر...: ہیب۔ بہادری ہٕنٛدۍ نیٚچو}\n19.\\tتہٕ تِمو کٔر ہَگارِیَن سٍتـ̡ ، یِتورس سٍتـ̡ نِفِش تہٕ نودابس سٍتـ̡ جنگ۔\n20.\\tتہٕ تِمن ہٕندِس خٕلاف آو تِمن ہٕندِس اتھس مَنٛز دِنہٕ، تہٕ یِمن سٍتـ̡ یِمن سٍتـ̡ سارِوٕے سٍتـ̡ دِنہٕ آمُت، تکیازِ تِمو کٔر جنگس مَنٛز خدایس نِش فریاد تہٕ تِمن سٍتـ̡ آو تِمن سٍتـ̡ دِنہٕ۔ تِکیازِ تِمو اوس أمِس پیٹھ پَنُن بھروسہٕ۔\n21.\\tتہٕ تِمو نِش پنٕنۍ چارواے۔ تِمن ہٕندٮ۪ن اونٹَن منز پنژاہ ساس، تہٕ دانٛدن ہٕندِ زٕ ہتھ ساس تہٕ گَرٕ سٕندِ زٕ ساس تہٕ نفرن ہُند اکھ ہتھ ساس۔ {ٹُک...: ہیب۔ لیڈ کیپٹیو} {مرد: ہیب۔ انسانن ہٕنٛز روح}\n22.\\tتکیازِ واریاہ مارۍ گٔیہِ، تکیازِ جنگ اوس خدایہ سُند۔ تہٕ تم رودۍ قید گژھنس تام پننین جایٔن منٛز۔\n23.\\tتہٕ منسی ہٕندِس نصف قبیلٕکۍ شُرۍ گٔیہِ زمینس مَنٛز روزان: تِمو گٔیہِ بَشَن پٮ۪ٹھٕ بعلہرمون تہٕ سینیر تام تہٕ ہرمون کِس پہاڑس تام۔\n24.\\tتہٕ یِم ٲسۍ پننین مٲلن ہٕندِ گرٕکۍ سربراہ، حتیٰ کہ ایفر، عیشی، تہٕ ایلیئل، تہٕ عزریل، تہٕ یرمیاہ تہٕ ہوداویاہ تہٕ جہدیل، بہادر شخص، مشہور شخص، تہٕ پننین مٲلن ہٕندِس گرٕکۍ سربراہ۔ {مشہور...: ہیب۔ مین آف ناون }\n25.\\tتہٕ تِمو کٔر پننین مٲلن ہٕندِس خدایس خلاف زیادٕ، تہٕ گٔیہِ زمینہٕ کین لوکن ہٕندِس دیوتاہن پَتہٕ یِمن خداین تِمن برونہہ تباہ کٔرۍ۔\n26.\\tتہٕ اسرٲیلٕکۍ خداہَن کٔر اسریاہُک بادشاہ پُل سُند روح تہٕ اسریاہُک بادشاہ تلگتھپِلنیسر سُند روح تہٕ تِم نِش نِتھ تہٕ یِم نِتھ تہٕ یِم ہالہ، حبور، تہٕ ہارا تہٕ از تام دریائے گوزانس کُن۔","1. لیوی سٕندۍ نیٚچوۍ۔ گرشون، کوہاتھ تہٕ میراری۔ {گیرشن: یا، گرشوم}\n2. تہٕ کوہات سٕندِ نیچو۔ امرام، اظہر تہٕ حبرون تہٕ عزیل۔\n3. تہٕ امرام سٕندِ اولاد۔ ہارون، موسیٰ تہٕ مریم۔ ہارون سٕندۍ نیچوۍ تہِ۔ نداب تہٕ ابیہو، الیعازر تہٕ اِتھمار۔\n4. الیعزر پیدہ فینہاس، فینہاسن پیدہ ابیشوا،\n5.\\tتہٕ ابیشوع زاو بُکی تہٕ بُکی زاے عزی،\n6.\\tتہٕ عُزی زَرہیاہ زاے تہٕ زراہیاہ زاے میریوتھ\n7. میریوتھ زاے امریہ، تہٕ اماریہ پیدہ احتوب۔\n8.\\tتہٕ احیتوبن زٲو زادوک تہٕ زادوک زاے احیماز،\n9.\\tتہٕ احیمااز دیت عزریاہ تہٕ عزریاہ پیدہ جوحنان،\n10.\\tتہٕ یوہنانن زاے عزریہ، (سُہ {یہ} یُس سُلیمانن یروشلمس مَنٛز بنوومُت مندرس مَنٛز پادٕرۍ سُند عہدہ پھانسی دِژ:) {مندرس منز: حبری۔ مکانس منز}\n11. تہٕ عزریاہ پیدہ امریہ تہٕ امریہ پیدہ احتوب۔\n12.\\tتہٕ احیتوبس پیدہ زادوک تہٕ زادوک پیدہ شلوم، {شلم: یا، مشُلم}\n13.\\tتہٕ شالوم زاے حلقیاہ تہٕ حلکیہ پیدہ عزریاہ،\n14.\\tتہٕ عزریاہ دیت سرایاہس پیدٕ، تہٕ سریاہ پیوو یہوزادک پٲدٕ۔\n15.\\tتہٕ یہوزادک گۆو {قٲدِس منز}، ییلہِ خداوند یہوداہ تہٕ یروشلم نبوکدنضر سٕندِ اتھہٕ سٍتـ̡ نِیو۔\n16. لیوی سٕندۍ نیٚچوۍ۔ گرشوم، کوہاتھ تہٕ میراری۔ {گیرشوم: یا، گیرشون}\n17. تہٕ یِم {be} گرشوم سٕندٮ۪ن نیچوین ہٕندِ ناو۔ لبنی تہٕ شیمی۔\n18.\\tتہٕ کوہات سٕندِ نیچوۍ، امرم تہٕ ازہر، تہٕ حبرون تہٕ عزیل۔\n19.\\tمیراری سٕندِ نیٚچوۍ۔ مہلی، تہٕ مشی۔ تہٕ یِم چِھہ پننین مٲلن ہٕندِ مطٲبق لاوِین ہٕندِ خاندان۔\n20. گرشومُک ؛ لبنی پنُن نیٚچُو، جہاد پنُن نیچو، زیمہ أمۍ سُنٛد نیٚچُو،\n21.\\tجوح تسند نیچو، اڈو تسند نیچو، زیرہ پنن نیچو، جیتراے پنن نیچو۔ {جوہ: یا، ایتھن} {Iddo: or, Adaiah} {Jeaterai: تہٕ چُھ ونان، نسل}\n22.\\tکوہات سٕندِ نیچوۍ۔ امیناڈاب تسند نیچو، کورہ تسند نیچو، اسیر سندس نیچو {امینادب: یا ازہر}\n23.\\tالکانہ تٔمۍ سُند نیچو تہٕ ابیاسفُک نیچو تہٕ اسیر سُند نیچو۔\n24.\\tتہ نیچو یوریئل، نیچو عزیاہ تہ شاؤل نیچو۔\n25.\\tتہٕ الکانہ سٕندِ نیچو۔ اماسائی، تہٕ اہیموتھ۔\n26.\\tالکانہ: الکانہ سٕندِ نیٚچوۍ۔ زوفایی تسند نیچو تہ ناہتھ تسند نیچو {زوپھائی: یا، زُپھ}\n27.\\tالیاب تسند نیچو، جیروہام تسند نیچو، الکانہ تسند نیچو۔\n28.\\tتہٕ سموئیل سٕندِ نیٚچوۍ۔ گۅڈنچہ لٹہِ وشنی، تہٕ ابیہ۔ {وشنی: یتھ جوئل تہِ ونان چھہِ}\n29.\\tمیراری سٕندِ نیٚچوۍ۔ مہلی، لبنی پنُن نیچو، شیمی پنُن نیچو، عزا پنُن نیٚچُو،\n30.\\tشیمعہ سُند نیچو، حاجیاہ تسند نیچو، عسیاہ تسند نیچو۔\n31. تہٕ یِم چھِ یِم داؤد خداوند سٕندِس گرس مَنٛز گیونٕچ خدمتہٕ خٲطرٕ مقرر کٔرۍمٕتۍ، تمہ پتہٕ کٔر صندوقس آرام کرنہٕ۔\n32.\\tتہٕ تِمو کٔر جماعت کِس خیمہ کِس مکانس برونہہ کُن گیونہٕ سٍتـ̡ خدمت، یوتام سُلیمانن یروشلمس مَنٛز خداوند سُند گرٕ تعمیر کور۔\n33.\\tتہٕ یِم چھِ تِم یِم پننین شُرین سٍتـ̡ پیاران ٲسۍ۔ کوہتھین ہٕندِس نیچوِس منز: ہیمن اکھ گلوکار، یوئیل سُند نیچو، شیموئیل سُند نیچو، {انتظار: حب۔ کھڑا}\n34.\\tالکانہ سُند نیچو، یروحیم سُند نیچو، الیل سُند نیچو، توح سُند نیچو،\n35.\\tزُف سُند نیٚچُو، الکانہ سُند نیچو، مہاتھ سُند نیچو، اماسایی سُند نیچو،\n36.\\tالکنہ سُند نیٚچُو، یُس یوایل سُند نیچو، یُس عزریاہ سُند نیٚچُو، یُس زفانیاہ سُند نیچو اوس،\n37.\\tطحث سُند نیچو، اسیر سُند نیچو، ابیساف سُند نیچو، یُس کورہ سُند نیچو اوس،\n38.\\tحضرت سُند نیچو، کوہات سُند نیچو، لیوی سُند نیچو، یُس اسرٲیلُک نیچو۔\n39.\\tتہٕ تٔمۍ سُند بوے آساف، یُس تٔمۍ سٕندِس دچھنہِ اتھس پیٹھ کھڑا اوس، یُس شیمعہ سُند نیچو برخیاہ سُند نیچو اوس،\n40. مایکائل سُند نیٚچُو، یُس باسیا سُند نیچو، ملکیا سُند نیچو،\n41. ایتھنی سُند نیٚچُو، زراح سُند نیچو، عدیاہ سُند نیچو،\n42.\\tزیمہ سُند نیچو ایتھن سُند نیچو، شمعیہ سُند نیچو،\n43.\\tجہات سُند نیچو، گرشوم سُند نیچو، لیوی سُند نیچو۔\n44.\\tتہٕ تِہٕندِس بٲے ٲسۍ میراری سٕندِ نیچو کھورِ طرفہٕ کھڑا: ایتھن کیشی سُند نیچو، عبدی سُند نیچو، ملُچ سُند نیچو، {کشی: یا، کُشایہ}\n45.\\tحشبیاہ سُند نیٚچُو، یُس حَلکیا سُند نیٚچُو،\n46.\\tامزی سُند نیچو بنی سُند نیچو شمر سُند نیچو۔\n47.\\tمہلی سُند نیچو، موشی سُند نیچو، میراری سُند نیچو، لیوی سُند نیچو۔\n48.\\tتہندِ بٲے تہِ آیہ خدایہ سٕندِ گرٕ کِس خیمہ کِس پرٮ۪تھ قٕسمٕچ خدمتہٕ خٲطرٕ مقرر کرنہٕ۔\n49.\\tمگر ہارون تہٕ تٔمۍ سٕندِس نیچویو کٔر دزنہٕ کِس قربان گاہس پیٹھ تہٕ بخور کِس قربان گاہس پیٹھ، {تہٕ آیہ مقدس ترین مقامہٕ سٕنزِ سارِنٕے کامہِ خٲطرٕ مقرر کرنہٕ، تہٕ اسرٲیلِس خٲطرٕ کفارہ دِنہٕ خٲطرٕ، یُس موسىٰ سٕندِ بندس اوس حکم دِتمُت۔\n50. تہٕ یِم چھِ ہارون سٕندِ نیٚچِوۍ۔ الیعازر تٔمۍ سُند نیچو، فینہاس سُند نیچو، ابیشوا پنُن نیچو،\n51.\\tبُکی تٔمۍ سُند نیچو، عُزی تٔمۍ سُند نیچو، زراحیاہ تٔمۍ سُند نیچو،\n52.\\tمیریوتھ تسند نیچو، امریاہ پنن نیچو، احتوب پنن نیچو،\n53.\\tزادوک تسند نیچو، احیماز تسند نیچو۔\n54.\\tوۅنۍ چھہِ یِمن ہٕندِس قلعس منز تہندِس بٹھس منز، ہارون سٕندٮ۪ن نیچوین ہٕندِ، کوہاتی خاندانن ہٕندِس خاندانس منز، تِمن ہٕندِس سٍتـ̡ روزنٕچ جاے ٲس۔\n55. تہٕ تِمو دِژ یہوداہ کِس سرزمینس مَنٛز تہٕ اَتھ أندۍ پٔکھۍ علاقن ہٕندِس علاقس مَنٛز۔\n56.\\tمگر شہرٕکۍ کھیت تہٕ یِمن ہٕندِس گامَس دِژ یِمو یِمو یپھُنہٕ سٕندِس نیچوِس کالبس دِنہٕ۔\n57. تہٕ ہارون سٕندِس نیچوِس دِژ یہوداہ ہٕندِس شہرس {یعنی} ہیبرون، پناہ گاہُک شہر، تہٕ لبنہٕ ہٕندِس مضافاتس سٍتۍ، تہٕ جاتیر تہٕ اشتیموا تہٕ تِمن ہٕندِس مضافاتس سٍتـ̡\n58. تہٕ ہیلن پننس مضافاتی علاقن سۭتۍ، دیبیر پننس مضافاتی علاقن سۭتۍ، {ہیلن: یا، ہولن}\n59.\\tتہٕ آشان پنہٕ نِس مضافاتس سٍتۍ، تہٕ بیت شیمش پنہٕ نِس مضافاتس سٍتۍ: {آشان: یا، عین}\n60. تہٕ بنیامین سٕندِ قبیلہٕ منز۔ گیبا پننس مضافاتی علاقن سۭتۍ، تہٕ علیمتھ پننس مضافاتی علاقن سۭتۍ، تہٕ اناتھوتھ پننس مضافاتی علاقن سۭتۍ۔ تِہندین خاندانن منز ٲسۍ تِہندۍ تمام شہر ترہ شہر۔ {علیمتھ: یا، المون}\n61.\\tتہٕ کوہات سٕندِس نیچوِس {یِم تمہِ قبیلہٕ کِس خاندانس منزٕ باقٕے ٲسۍ} دِنہٕ آمٕتۍ، {یعنی} منزٕ ٲسۍ منشہ کِس نصف {قبیلہٕ} منزٕ دِنہٕ آمٕتۍ، داہ شہر۔\n62. تہٕ گرشوم سٕندِس نیچوِس سٲرۍسٕے عیالس منز، تہٕ آشیر قبیلہٕ منزٕ تہٕ نفتالی قبیلہٕ منزٕ تہٕ بشانس مَنٛز مانسی قبیلہٕ منزٕ ترُہ شہر۔\n63.\\tمیراری کین نیچوین آیہ قرعہ اندازی کٔرِتھ دِنہٕ، روبن سٕندِ قبیلہٕ منز، گاد قبیلہٕ منزٕ تہٕ زبولون قبیلہٕ منزٕ باہ شہر۔\n64.\\tتہٕ بنی اسرٲیلِو دِژ لاوِین تہٕ یِمن ہٕندِس مضافاتس سٍتـ̡ شہر۔\n65. تہٕ یِمو دِژ یہوداہ کین اولادن ہٕندِس قبیلہٕ منز، تہٕ شمعون سٕندِ اولادٕ سٕندِ قبیلہٕ منزٕ تہٕ بنیامین سٕندِ اولاد سٕندِ قبیلہٕ منزٕ یِم شہر، یِمن ہٕندِس ناوٕ سٍتـ̡ وننہٕ یوان چھِ۔\n66.\\tتہٕ کوہات کین نیچوین ہٕندِس خاندانن ہٕندِس باقیاتس منز ٲسۍ افرائیم قبیلہٕ سٕندِ سٍتـ̡ شہر۔\n67.\\tتہٕ تِمو دِژ تِمن پناہ گاہٕکۍ شہر، کوہ افرائیم کِس مضافاتس سٍتـ̡ شیکیم۔ {تمو دِژ} گیزر تہِ پننین مضافاتی علاقن سٍتۍ،\n68.\\tتہٕ جوکمیام پننِس مضافاتس سٍتۍ، تہٕ بیتھورون پننین مضافاتن سٍتۍ،\n69.\\tتہٕ ایجالون پننین مضافاتن سٍتۍ، تہٕ گتھریمن پننین مضافاتن سۭتۍ:\n70.\\tتہٕ منسی ہٕندِس نصف قبیلس منز۔ انیر پننین مضافاتی علاقن سۭتۍ، تہٕ بلیم پننس مضافاتی علاقن سۭتۍ، کوہاتھ کین نیچوین ہٕنٛدس باقیاتس خاندانس خٲطرٕ۔\n71.\\tگرشوم سٕندِس نیچوِس مَنٛز دِنہٕ آمُت، بشنَس مَنٛز گولان تہٕ اشتاروت تٔمۍ سٕندِس مضافاتس سٍتۍ:\n72.\\tتہٕ اِساکر قبیلہٕ منز۔ کیدیش پننِس مضافاتی علاقَس سۭتۍ، دبیرتھ پننِس مضافاتی علاقَن سۭتۍ،\n73.\\tتہٕ رموتھ پننِس مضافاتس سٍتۍ، تہٕ انیم پننِس مضافاتس سٍتۍ:\n74.\\tتہٕ آشر قبیلہٕ منز؛ مشعل پننین مضافاتن سۭتۍ، تہٕ عبدون پننین مضافاتن سۭتۍ،\n75.\\tتہٕ ہُکوک پننِس مضافاتی علاقن سٍتۍ، تہٕ ریہوب:\n76.\\tتہٕ نفتالی قبیلہٕ منز؛ گلیلس منز کیدیش پننین مضافاتن سٍتۍ، تہٕ ہیمون پننین مضافاتی علاقن سٍتۍ، تہٕ کرجاتھیم پننین مضافاتن سۭتۍ۔\n77.\\tمَراری ہٕندِس باقٕے شُرِس {آیہ دِنہٕ} زبولُن قبیلہٕ منز، رِمن ہٕندِس مضافاتس سٍتۍ، تَبور تٔمۍ سٕندِس مضافاتس سٍتۍ:\n78.\\tتہٕ دوٚیمہِ طرفہٕ یریحا سٕندِ طرفہٕ اردن کِس مشرقس طرف، {آیہ تِم روبن سٕندِ قبیلہٕ منزٕ دِنہٕ}، بیابانن مَنٛز بیزر تہٕ یَہزاہ تٔمۍ سٕندِس مضافاتس سٍتـ̡ دِنہٕ۔\n79.\\tکیدمتھ تہِ پننین مضافاتی علاقن سٍتۍ، تہٕ میفاتھ پننین مضافاتن سٍتۍ:\n80.\\tتہٕ گاڈ قبیلہٕ منز؛ گلعادس مَنٛز رموتھ پننین مضافاتن سٍتۍ، تہٕ مہانیم پننین مضافاتن سٍتۍ،\n81. تہٕ ہیشبن پننس مضافاتی علاقن سۭتۍ، تہٕ جازر پننس مضافاتی علاقن سۭتۍ۔","1.\\tوۅنۍ چھہِ اِساکر سٕندِ نیچوۍ، تولہٕ تہٕ پواہ، یشوب تہٕ شِمرون ژور۔\n2. تہٕ ٹولہٕ سٕندِ نیچوۍ۔ عزی، تہٕ رفعیہ، تہٕ جیریئل، تہٕ جِبسام، تہٕ شیموئیل، تِمن ہٕندِس مٲلہِ سٕندِس گرٕکۍ سربراہ، {وُچھِن}، تولہٕ: {تِم ٲسۍ پننین نسلن منز بہادر انسان۔ یٔمۍ سُند تعداد اوس داؤد سٕندِس دۅہس منز زٕ وُہ ساس تہٕ شیہ ہتھ۔\n3.\\tتہٕ عُزی سٕندِس نیٚچوۍ۔ ازراحیاہ: تہٕ ازرحیاہ سٕندِ نیٚچوۍ۔ میکائیل، تہٕ عوبدیہ، تہٕ جوئل، ایشیاہ، پانژھ: یم سٲری ٲسۍ سردار۔\n4.\\tتہٕ تِمن سٍتـ̡ ٲس پننین مٲلن ہٕندِس گرس پٲٹھۍ، جنگہٕ خٲطرٕ سپاہِ ہٕندِ جمٲژ ہٕنز، شیہ تہٕ ترہ ساس {مرد}، کیازِ تِمن آسہٕ واریاہ زنانہٕ تہٕ نیچوۍ۔\n5.\\tتہٕ تِہٕندِ بٲے ٲسۍ اِساکر سٕندٮ۪ن سارِنٕے خاندانن مَنٛز بہادر نفر، یِمن ہٕندِس شجرہ نسب سٍتـ̡ ژور تہٕ ستھ ساس شمار سپدان ٲسۍ۔\n6. {بنیامین سٕندِ نیٚچو}؛ بیلا، تہٕ بیچر، تہٕ جیڈیئل، ترۍ۔\n7. تہٕ بیلا سٕندۍ نیٚچوۍ۔ ازبون، تہٕ عزی، تہٕ عزیل، تہٕ جیریموتھ، تہٕ ایری، پانژھ۔ {تہندِ} مٲلن ہٕندِ گرٕکۍ سربراہ، بہادر مرد تہٕ تِمن ہٕندِس شجرہ نسب سٍتۍ ٲسۍ وُہُن، زٕ ساس تہٕ ژۅترہ تہٕ ژوٗر شمار کرنہٕ آمٕتۍ۔\n8. تہٕ بیچر سٕندۍ نیچو۔ زیمیرا، تہٕ یواش، تہٕ الیعزر، تہٕ ایلیونی، تہٕ عمری، تہٕ یرموتھ، تہٕ ابیاہ، تہٕ انتھوتھ، تہٕ عالمیت۔ یم سٲری {چِھ} بیچر سٕندۍ نیچوۍ۔\n9.\\tتہٕ تِمن ہُند تعداد اوس تِہندِ نسلہٕ سٍتـ̡ تِمن ہٕندِس نسب سٍتـ̡ ، تِمن ہٕندِس مٲلِس ہٕندِس گرٕکۍ سربراہ، بہادر نفر ، وُہ ساس تہٕ زٕ ہتھ ۔\n10. یدیال سٕندۍ نیچوۍ تہِ۔ بِلہان: تہٕ بِلہان سٕنٛدِ نیٚچِوۍ۔ عیسیٰ مسیح، تہٕ بنیامن، تہٕ ایہود، تہٕ چناناہ، تہٕ زیتھن، تہٕ تھرش، تہٕ اہیشاہر۔\n11.\\tیِم سارِنٕے نیچوۍ، یِمن ہٕندِس مٲلِس سٍتـ̡ سَتھ ساس تہٕ زٕ ہتھ {سپاہی}، یِم جنگہٕ خٲطرٕ نیرنہٕ خٲطرٕ قٲبل۔\n12.\\tشوپِم تہِ، تہٕ ہُپِم، ایر سٕندِ شُرۍ، {تہٕ} حُشیم، احر سٕندِ نیچوۍ۔ {Ir: or, Iri} {احیر: یا، احیرم}\n13.\\tنفتالی سٕندِ نیچوۍ۔ جہزیل، تہٕ گونی، تہٕ جیزر، تہٕ شلوم، بلحاہ سٕندۍ نیچو۔\n14. مناسی سٕندِ نیچوۍ۔ اشریل، یس أمس نِش بٔرِتھ: ({مگر} تٔمۍ سٕنز لونڈی آرامیٹس بٔرِس مچیر، گلعادُک مول:\n15.\\tتہٕ ماکھِر رٔٹِتھ ہُپِم تہٕ شُپِم سٕنزِ بینہِ ہٕنزِ بینہِ، یٔمۍ سٕنزِ بینہِ ہُند ناو اوس ماخہٕ۔ تہٕ دۆیمِس {اوس} زیلوفہد سُند ناو: تہٕ زیلوفہدس ٲس کورِ۔\n16.\\tتہٕ ماچِر سٕنزِ زنانہِ ہُند نیچو زاے تہٕ تٔمۍ ووٚن أمِس پیریش ناو۔ تہٕ تٔمۍ سٕنٛدِس بٲے سُنٛد ناو اوس شریش۔ تہٕ تٔمۍ سٕنٛدۍ نیٚچوۍ ٲسۍ اُلم تہٕ راکم۔\n17.\\tتہٕ اُلام سٕندِس نیٚچوۍ۔ بیدان۔ یِم ٲسۍ مناسہ سُند نیچو گلعاد سٕندِ نیچو۔\n18.\\tتہٕ تٔمۍ سٕنزِ بینہِ ہمولیکتھ ٲس عیشود، تہٕ عبیزر تہٕ مہلہٕ بٔرۍ۔\n19.\\tتہٕ شیمیدہ سٕندِ نیچوۍ ٲسۍ اہیان تہٕ شیکیم، تہٕ لکھی تہٕ انیام۔\n20. تہٕ افرائیم سٕندِ نیٚچوۍ۔ شثلہ، تہٕ پنن نیچو تہٕ طاحث پنن نیچو، تہٕ الادہ پنن نیچو تہٕ طحت پنن نیچو۔\n21.\\tتہٕ زباد تٔمۍ سُند نیچو تہٕ شوتلہ تٔمۍ سُند نیچو تہٕ عزر تہٕ ایلاڈ، یُس گاتھ ہٕندِس مردس {تَمہِ} زمینس مَنٛز زامُت اوس، کیازِ تِم ٲسۍ پنٕنۍ چاروٲے نِنہٕ خٲطرٕ بۄن آمٕتۍ۔\n22.\\tتہٕ تِہٕندِس مٲلہِ افرائیم کٔر واریاہن دۅہن ماتم تہٕ تٔمۍ سٕندِ بٲے آیہِ أمِس تسلی دِنہِ۔\n23.\\tتہٕ ییلہ سُہ پننہِ زنانہِ نِش اژِو، تٔمِس گٔیہِ حاملہٕ تہٕ نیچو زیٚوُن، تہٕ تٔمۍ وَنُن پننِس گرس سٍتـ̡ بدکار گٔیہِ۔\n24.\\t(تہٕ تٔمۍ سٕنز کوٗر ٲس شیرہ، یٔمۍ بیت حورن تہٕ اپر تہٕ عزنشیرہ تعمیر کٔر۔)\n25.\\tتہٕ رِفاح اوس تٔمۍ سُند نیچو، تہٕ تلہٕ اوس تٔمۍ سُند نیٚچُو، تہٕ تہان اوس تٔمۍ سُند نیٚچُو۔\n26.\\tلادان تٔمۍ سُند نیچو، امیہود تٔمۍ سُند نیچو، الیشامہ تٔمۍ سُند نیچو،\n27. تٔمۍ سُند نیچو، یہوشوع تٔمۍ سُند نیچو۔ {non: or, nun} {یہوشوع: یا، یشوع}\n28.\\tتہٕ تِہٕندِس ملکیتس تہٕ بستی ٲس، بیتھل تہٕ اَمہ کِس قصبس سٍتۍ، مشرقس کُن ناران تہٕ مغرب کُن گیزر، یِمن ہٕندِس قصبس سٍتۍ۔ شیکیم تہٕ تِمن ہٕندِس قصبس تام، غزہ تہٕ تِمن ہٕندِس قصبن تام: {قصبہٕ: حب۔ کورِ} {غزہ کُن: یا، عداسا}\n29.\\tتہٕ مناسی، بیت شیان تہٕ تٔمۍ سٕندِس قصبَن ہٕندِس شُرین سٍتـ̡ تہٕ تٔمۍ سٕندِس قصبَن ہٕندِس سرحدس سٍتـ̡ ۔ یِمن مَنٛز ٲسۍ اسرٲیلِس سٕندِس نیٚچوِس یوسف سٕندِ بچہٕ روزان۔ {قصبہٕ: ہیب۔ کورِ}\n30. آشر سٕندۍ نیچو۔ عمانہ، تہٕ عیسوہ، تہٕ عیشوعی، تہٕ بریہ، تہٕ سیرہ تہٕ تہنز بینہِ۔\n31. تہٕ بیریاہ سٕندِ نیچو۔ ہیبر، تہٕ مالچیئل، یُس {چُھ} برزاویت سُند مول۔\n32.\\tتہٕ ہیبر زاے یافلیٹ، شومر، تہٕ ہوتھم، تہٕ شوع تہٕ تِہنز بینہِ۔\n33.\\tتہٕ یافلیٹ سٕندِ نیٚچوۍ۔ پاسچ، تہٕ بِمَل، تہٕ اشوتھ۔ یم {چِھ} جافلیٹ سٕندۍ شُرۍ۔\n34. تہٕ شمر سٕندِ نیٚچوۍ۔ آہی تہٕ روہگا، جہبہ تہٕ آرام۔\n35.\\tتہٕ تٔمۍ سٕندِس بٲے ہیلم سٕندِ نیچوۍ۔ زوفاہ تہٕ امانہ، تہٕ شیلیش تہٕ امل۔\n36.\\tزوفاہ سٕندِ نیٚچوۍ۔ سوح، تہٕ ہارنیفر، تہٕ شوال، تہٕ بیری تہٕ امرہ،\n37.\\tبیزر، ہود، تہٕ شما، تہٕ شِلشاہ، تہٕ اِتھران تہٕ بیرا۔\n38.\\tتہٕ یتھر سٕندِ نیچو۔ جیفونہ، تہٕ پسپا تہٕ آرا۔\n39.\\tتہٕ اولا سٕندِ نیچو۔ آرہ، تہٕ ہینیئل، تہٕ ریزیا۔\n40. یِم سٲری ٲسۍ آشر سٕندِ شُرۍ، مٲلہِ سٕندِ گرٕکۍ سربراہ، ژٲر تہٕ بہادر شخص، شہزادن ہُند سردار۔ تہٕ تِمن ہٕندِس شجرس منز یِم جنگہٕ خٲطرٕ موزوں ٲسۍ، تِمن ہُند تعداد اوس وُہ شیہ ساس نفر۔","1. وۅنۍ زاو بنیامین بیلہ پنُن گۅڈنچہ اولاد، اشبیل دۆیم تہٕ احراہ تریم\n2. نوہا ژوٗرِم تہٕ رافا پٲنژم۔\n3.\\tتہٕ بیلہ سٕندِ نیچوۍ ٲسۍ اَدار تہٕ گیرا تہٕ ابیہود، {اَدر: یا، ارد}\n4. تہٕ ابیشوا، تہٕ نعمان، تہٕ آہواہ،\n5. تہٕ گیرا، تہٕ شیفوفن تہٕ حُرم۔ {شیفوفن: یا، شوپھم}\n6.\\tتہٕ یِم چھِ احود سٕندِ نیچوۍ: یِم چھِ گیبا کین بسکینن ہٕندِس مٲلن ہٕندِ کلہٕ، تہٕ یِمو کٔرِکھ ماناہتس کُن۔\n7.\\tنعمان تہٕ احیٰ تہٕ گیرہ کٔرِن تِم ہٹٲوِتھ عزا تہٕ احیُد پٲدٕ کٔرِتھ۔\n8.\\tتہٕ شحریم زاے موآب کِس ملکس مَنٛز شُرۍ۔ حُشم تہٕ بَرٕ آسہٕ تٔمۍ سٕنٛزٕ زنانہٕ۔\n9.\\tتہٕ أمِس زاے ہودیش سٕنزِ زنانہٕ جوباب تہٕ ضبیعہ، تہٕ میشا تہٕ ملچم۔\n10.\\tتہٕ جیوز، تہٕ شاچیا تہٕ میرما۔ یم ٲسۍ تٔمۍ سٕندۍ نیچوۍ، مٲلن ہٕندۍ سربراہ۔\n11.\\tتہٕ ہُشم سٕندِس سٍتـ̡ زاے ابیطوب، تہٕ الپال۔\n12. ایلپالٕکۍ نیٚچوۍ۔ ایبر، تہٕ مِشام، تہٕ شمد، یِمو اونو تہٕ لوڈ بنٲوۍ، تِمن ہٕندِس قصبس سٍتۍ:\n13.\\tبریاہ تہٕ شیما تہِ، یُس ایجالون کین بسکیٖنن ہٕندِس مٲلِس سٍتـ̡ کٔرِتھ:\n14. تہٕ اہیو، شاشاک تہٕ یرموتھ،\n15.\\tزبادیہ، عراد تہٕ آدر،\n16. تہٕ مائیکل، تہٕ اسپاہ تہٕ جوہا، بیریاہ سٕندۍ نیچو۔\n17.\\tزیبادیہ، تہٕ مشولم، تہٕ حزکی تہٕ حبر،\n18.\\tاِشمیراے تہٕ یِزلیاہ تہٕ جوباب، یِم ایلپالٕکۍ نیٚچِوۍ۔\n19.\\tتہٕ جاکیم، تہٕ زکری، تہٕ زبدی،\n20. تہٕ ایلینی، تہٕ زِلتھائی تہٕ ایلیئل،\n21.\\tتہٕ عدیہ تہٕ بریاہ تہٕ شمرت شماہی سٕندِ نیچو۔ {شِمہی: یا، شیما}\n22.\\tایشپان تہٕ ہیبر تہٕ ایلیل،\n23. تہٕ عبدون تہٕ زکری تہٕ حنان،\n24. تہٕ حنانیاہ تہٕ ایلام تہٕ انتوتھیجاہ،\n25.\\tتہٕ افیدیہ تہٕ پینوئل، ششک سٕندِ نیچوۍ۔\n26. تہٕ شمشیرائی تہٕ شہریہ تہٕ اتھلیاہ،\n27. تہٕ یریشیاہ تہٕ ایلیاہ تہٕ زکری، یِم یروہیم سٕندِ نیچوۍ۔\n28.\\tیِم ٲسۍ مٲلن ہٕندِ سربراہ، تہندِ نسلہٕ سٍتـ̡ بٔڈۍ {انسان}۔ یم ٲسۍ یروشلمس منز روزان۔\n29.\\tتہٕ گِبیونَس مَنٛز اوس گِبیونُک مول روزان۔ یٔمۍ سٕنزِ زنانہِ ہُند ناو {اوس} ماچہ: {مول...: یتھ جہیل تہِ ونان چھِ}\n30.\\tتہٕ تٔمۍ سُند گۄڈنیُک نیچو عبدون، تہٕ زور، تہٕ کِش، تہٕ بعل تہٕ ندب،\n31. تہٕ گیڈور، تہٕ اہیو، تہٕ زاکر۔ {زکر: یا، زکریا}\n32.\\tتہٕ مکلوت دیت شمیع۔ تہٕ یِم تہِ ٲسۍ یروشلمس مَنٛز پننین باین سٍتـ̡ روزان۔ {شمیع: یا، شمیعم}\n33.\\tتہٕ نیرن زاے کِش، تہٕ کِش زٲو ساؤل، تہٕ ساؤلن زٲو یوناتھن تہٕ ملکیشوع تہٕ ابینادب تہٕ اشبال۔ {ابیناداب: یتھ ایشوئی تہِ ونان چھِ} {اشبال: یا، اشبوشیتھ}\n34. تہٕ جوناتھن سُند نیچو اوس مریبعل۔ تہٕ مریبعلن زاو میکاہ۔ {مریبعل: یا، میفیبوشیتھ}\n35.\\tتہٕ میکاہ سٕندِ نیچوۍ، پِتھون تہٕ ملیک، تہٕ تریہ تہٕ آحاز۔ {Tarea: or, Tahrea}\n36.\\tتہٕ احاز پیدہ یہوداہ۔ تہٕ یہوداہ زاے علیمتھ تہٕ عظموتھ تہٕ زیمری۔ تہٕ زیمری پیدہ موزہ، {یہوداہ: یَتھ تہِ وَننہٕ یوان چھُ}\n37.\\tتہٕ موزہ زاو بینا: رافا اوس تٔمۍ سُند نیچو، الیاسہ اوس تٔمۍ سُند نیچو، عزیل اوس تٔمۍ سُند نیچو: {رافا: تہِ ونان رفیعہ}\n38.\\tتہٕ عزیل سٕندِس شے نیچوۍ، یِمن ہُند ناو چھُ، عزریقم، بوچیرو، اسماعیل، تہٕ شیریعہ تہٕ عوبدیہ تہٕ حنان۔ یم سٲری ٲسۍ ازیل سٕندۍ نیچوۍ۔\n39.\\tتہٕ اشک سٕندِ نیچوۍ یُس تٔمۍ سُند بوے اوس، اُلام اوس تٔمِس گۅڈنیُک، یہوش دۆیم تہٕ الیفلیٹ۔\n40.\\tتہٕ اُلام سٕندِ نیچوۍ ٲسۍ بہادر تہٕ تیر انداز تہٕ یِمن ٲسۍ واریاہ نیچوۍ تہٕ نیچوۍ ٲسۍ ہتھ پنژاہ۔ یم سٲری {چِھ} بنیامین سٕندِ نیچوین ہٕندِ۔","1. یێلہِ سارِنٕے اِسرٲیلِس سٍتـ̡ شجرہ نسب سٍتـ̡ شمار کرنہٕ آمُت۔ تہٕ وُچھِو، تِم ٲسِکھ اسرٲیلِس تہٕ یہوداہ کِس بادشاہن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ، {یِمَن} ٲس تِمن ہٕنزِ خلاف ورزی کِنہِ بابل کُن نِنہٕ آمٕتۍ۔\n2. وۅنۍ گۅڈنچہ لٹہِ روزن وٲلۍ، یم پننین شہرن منز روزان ٲسۍ، تم ٲسۍ اسرائیل، پادٕرۍ، لاوی تہٕ نیتھینیم۔\n3. تہٕ یروشلمس منز ٲس یہوداہ کِس بُلِس تہٕ بنیامین سٕندِس شُرین تہٕ افرائیم تہٕ منسی ہٕندِس اولادَس منز روزان۔\n4.\\tاُتھایی امی ہود سُند نیچو، عمری سُند نیچو، بنی سُند نیچو، یہوداہ سُند نیچو فریز سٕندِس نیچو۔\n5. تہٕ شِلونائٹس؛ عیسیاہ گۅڈنچہ اولاد تہٕ تٔمۍ سٕندِ نیچوۍ۔\n6. تہٕ زرہ سٕندِس نیٚچوِس سٍتـ̡ ۔ یُس تہٕ تِہٕندِس بٲے، شیہ ہتھ تہٕ نَمتھ ۔\n7. تہٕ بنیامین سٕندِس نیچوِس سٍتـ̡ ۔ سلوٗ مشُلَم سُنٛد نیٚچُو، حَداویاہ سُنٛد نیٚچُو، یُس حسینواہ سُنٛد نیٚچُو،\n8. تہٕ ابنیاہ، یروہام سُند نیچو، تہٕ ایلہ یُس عُزی سُند نیچو، یُس مِکری سُند نیچو اوس، تہٕ مشُلَم یُس اِبنیجہ سُند نیچو رئیل سُند نیچو۔\n9. تہٕ تِہٕندِ بٲے تہٕ تِہٕندِ نسلہٕ مُطٲبق نو ہتھ پنژاہ تہٕ شیہ۔ یم سٲری نفر ٲسۍ پننین مٲلن ہٕندِس گرس منز مٲلن ہٕندِ سردار۔\n10. تہٕ پادٕرین ہٕندِ؛ جدیاہ، تہٕ یہویاریب، تہٕ جاچین،\n11. تہٕ عزریاہ ہلکیا سُند نیچو، مشُلَم سُند نیچو، زادوک سُند نیچو، میریوتھ سُند نیچو، یُس خدایہ سٕندِس گرُک حکمران اوس۔ {عزریہ: تہِ ونان سریعہ}\n12.\\tتہٕ اَدیاہ یَروہَم سُند نیٚچُو، یُس پاشور سُند نیچو، ملکیجاہ سُند نیچو، تہٕ عدیل سُند نیچو، یُس جازِراہ سُند نیچو، مشُلمُک نیچو، میشِلمُت سُند نیچو، یُس اِمر سُند نیچو اوس۔\n13.\\tتہٕ تِہٕندِس بٲے، پننین مٲلن ہٕندِس گرس ہٕندِس سردار، ساس ستھ ہتھ ترےٚ۔ خدایہ سٕندِ گرٕ سٕنزِ خدمتہٕ خٲطرٕ واریاہ قٲبل نفر۔ {سٮ۪ٹھاہ...: ہیب۔ بہادری ہٕندۍ طاقتور انسان}\n14. تہٕ لاوِین ہٕندِس سٍتـ̡ شمعیاہ اوس حشوب سُند نیچو، یُس حشبہ سُند نیچو اوس، یُس مراری کین نیچوین ہُند نیچو اوس۔\n15. تہٕ بککر، ہیریش تہٕ گلال، تہٕ متانیاہ میکاہ سُند نیچو، یُس زکری سُند نیچو اوس، یُس آصف سُند نیچو۔\n16.\\tتہٕ عبدیاہ سُند نیچو شیمعیاہ سُند نیچو، یُس یدوتون سُند نیچو اوس، تہٕ الکانہ سُند نیچو آسا سُند نیچو بریخیاہ یُس نیتوفاتین ہٕندِس گامن مَنٛز روزان اوس۔\n17.\\tتہٕ قلی {ٲس}، شلم تہٕ عکوب، تہٕ تلمون، تہٕ اہیمان، تہٕ تِہٕندِس بٲے: شَلم {اوس} سردار۔\n18.\\tیُس از تام بادشاہ سٕندِس دروازس منز مشرقس کُن پیارُن: تِم ٲسۍ لاوی سٕندٮ۪ن شُرین ہٕندِس صحبتس منز قُلۍ۔\n19.\\tتہٕ کورہ سُند نیچو شلوم، یُس کورہ سُند نیچو اوس، تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس گرس سٍتـ̡ تہٕ تٔمۍ سٕندِس بٲے سٕندِس مٲلہِ سٕندِس کامہِ پیٹھ، خیمہ کِس دروازن ہٕندِس رٲچھ کَرن وٲلۍ، تہٕ تِہٕندِس مٲلہِ سٕندِس مٲلہِ سٕندِس لشکرس پیٹھ، {أسـ̡ دٲخل گژھنٕکۍ رٲچھ دار۔ {گیٹس: ہیب۔ تھریشولڈز}\n20. تہٕ الیعزر سُند نیچو فینہاس اوس پتھ کالس منز تمن پیٹھ حکمران، {تہٕ}خداوند اوس تس سٍتـ̡۔\n21.\\t{تہٕ} زکریاہ مشلمیاہ سُند نیچو {اوس} جماعت کِس خیمہ کِس دروازُک پورٹر۔\n22.\\tیِم سٲری {یِم} ٲسۍ دروازن منز قلی بناونہٕ خٲطرٕ ژارنہٕ آمٕتۍ {أسۍ} زٕ ہتھ بارہ۔ یِمن ہُند شجرہ نامہٕ اوس تہندٮ۪ن گامن منز شمار کرنہٕ آمُت، یِم ڈیوڈ تہٕ سیموئیل سیرن پننِس مقرر دفترس منز مقرر کٔرۍ۔ {کیا ...: ہیب۔ بُنیاد} {سیٹ...: یا، ٹرسٹ}\n23.\\tتێلہِ ٲس تِمو تہٕ تِہندِ شُرِ خداوند سٕندِس گرٕ کِس دروازس پیٹھ رٲچھ کٔرِتھ، یعنی خیمہ خانہٕ کِس گَرٕچ نگرٲنی ۔\n24.\\tژۅن ژۅن ژۅن حصن منز ٲسۍ پورٹر، مشرق، مغرب، شمال تہٕ جنوبس کُن۔\n25.\\tتہٕ تِہٕندِس بٲے {یِم تہندِس گامن مَنٛز} ٲسۍ، سَتہٕ دۅہہٕ پتہٕ یِمن سٍتـ̡ یِمن سٍتـ̡ یِنہٕ وٲلۍ۔\n26. یِمن لاوِین ہٕندِ خٲطرٕ، ژور اہم قُلی، ٲسۍ تِہندِس مقرر دفترس منز، تہٕ ٲسۍ خدایہ سٕندِس گرٕ کِس خانن تہٕ خزانن پیٹھ۔ {سیٹ...: یا، ٹرسٹ} {چیمبرز: یا، سٹور ہاؤس}\n27.\\tتہٕ تِم گٔیہِ خدایہ سٕندِس گرس اندۍ پکھۍ روزان، تکیازِ تِمن پیٹھ اوس یہ ذمہ دار، تہٕ پرٮ۪تھ صُبحس یُس تِمن سٍتـ̡ کھولُن اوس۔\n28.\\tتہٕ یِمن منز اوس وزیرن ہٕندِس جہازن ہُند ذمہٕ دار، زِ تِم گژھن افسانہٕ سٍتۍ انٛدر تہٕ نٮ۪بر انن۔ {انن...: ہیب۔ افسانہٕ سٍتۍ أنِو تِم تہٕ دٔلیلہٕ سٍتۍ انجام دِنہٕ}\n29.\\tیِمو منزٕ آیہ کینہہ تہِ مُقرر کرنہٕ آمٕتۍ، تہٕ مقدس مقامٕکۍ سارِنٕے آلات، تہٕ عمدہ آٹ، شراب، تہٕ تیل، تہٕ لوبان تہٕ مسالہٕ ہٕنز نگرٲنی خٲطرٕ تہِ مُقرر کرنہٕ۔ {آلات: یا، جہاز}\n30.\\tتہٕ پادٕرین ہٕندیو نیچویو بنوو مصالحن ہُند مرہم ۔\n31.\\tتہٕ متیتھیاہ، یُس شَلوم کورہیت سُند گۄڈنیُک زامُت اوس، تٔمِس اوس تِمن چیزن ہُند عہدٕ مقرر یُس پانس مَنٛز بناونہٕ آمُت اوس۔ {سیٹ...: یا، ٹرسٹ} {منز...: یا، فلیٹ پلیٹن پیٹھ، یا، سلائس}\n32.\\tتہٕ تِمن ہٕندِس بٲے سٍتـ̡ تہٕ کُہہِین ہٕندِس نیچوِس سٍتـ̡ چُھہ پرٮ۪تھ سبت دۅہہٕ تیار کرنہٕ خٲطرٕ۔ {شیوبریڈ: ہیب۔ آرڈرنگ ہُند روٹی }\n33.\\tتہٕ یِم چھِ گیون والۍ، یِم خانن مَنٛز باقٕے روزان ٲسۍ، تِکیازِ تِم ٲسۍ دۅہہٕ راتس کامہِ مَنٛز کٲم کران۔ {تِم...: ہیب۔ تمن پیٹھ}\n34.\\tلاوِین ہٕندِ یِم بٔڈۍ باپ ٲسۍ پنہٕ نِس نسلس منز سردار۔ یم ٲسۍ یروشلمس منز روزان۔\n35.\\tتہٕ گِبیونَس مَنٛز اوس گِبیونُک مول یُس یٔمۍ سٕنزِ خانٛدارِنہِ ہُند ناو اوس ماخہ:\n36. تہٕ تٔمۍ سُند گۄڈنیُک نیچو عبدون، پتہٕ زور، تہٕ کِش، تہٕ بعل، تہٕ نیر تہٕ ندب،\n37. تہٕ گیدور، تہٕ آہیو، تہٕ زکریا تہٕ مکلوت۔\n38.\\tتہٕ مِکلوت زاے شمعیم۔ تہٕ تِم ٲسۍ پننین باین سٍتـ̡ یروشلمس مَنٛز روزان۔\n39.\\tتہٕ نیرن زاے کِش۔ تہٕ کِش زاے ساؤل۔ تہٕ ساؤلن زٲو جوناتھن تہٕ ملچیشوا تہٕ ابینادب تہٕ اشبال۔\n40.\\tتہٕ یوناتھن سُند نیچو اوس مریبعل: تہٕ مریبعل زاو میکاہ۔\n41.\\tتہٕ میکاہ سٕندِ نیچوۍ، پِتھون تہٕ میلیک، تہٕ طہریع، {تہٕ آہز}۔\n42.\\tتہٕ احاز بنیوو جاراہ۔ تہٕ جاراہن زاے علیمتھ تہٕ عظمویت تہٕ زمری۔ تہٕ زیمری پیدٕ موزا۔\n43.\\tتہٕ موزا پیدہ بینا۔ تہٕ رفیعیاہ تٔمۍ سُند نیچو، الیاسہ سُند نیچو، ازیل سُند نیچو۔\n44.\\tتہٕ عزیل سٕندِس شے نیچوۍ، یِمن ہُند ناو چھُ، عزریکام، بوچیرو، تہٕ اسماعیل، تہٕ شیریعہ، تہٕ عوبدیہ تہٕ حنان: یِم ٲسۍ عزیل سٕندِ نیچوۍ۔","1. وۅنۍ لوٚگ فلسطینیو اسرائیلس خلاف۔ تہٕ اسرٲیلٕکۍ مرد ژٔل فلسطینن برونہہ کُن، تہٕ گٔیہٕ گلبوا پہاڑس مَنٛز مارنہٕ۔ {قتل: یا، زخمی}\n2. تہٕ فلسطینی لٔگۍ ساؤلس پَتہٕ تہٕ تٔمۍ سٕندِس نیچوِس پَتہٕ۔ تہٕ فلسطینیو مارۍ جوناتھن تہٕ ابینادب تہٕ ملچیشوا ساؤل سٕندِ نیچوۍ۔ {ابیناداب: یتھ ایشوئی تہِ ونان چھِ}\n3.\\tتہٕ جنگ گۆو ساؤلس سٍتـ̡ تہٕ تیر اندازو لوٚگ أمِس تہٕ سُہ گۆو تیر اندازن ہٕندِس نِش زخمی۔ {تہٕ تیر انداز: ہیب۔ تہٕ کمانن وٲل شوٹر} {ہٹ: ہیب۔ لٔب}\n4.\\tپتہٕ ووٚن ساؤلن پننِس ہتھیار بردارس زِ پنٕنۍ تلوار کٔڈِتھ تہٕ دِیُن میہ اَتھ سٍتـ̡ دِنہٕ۔ یِم نہٕ یِم ختنہٕ یِن تہٕ مےٚ بدسلوکی کٔرِتھ۔ مگر تٔمۍ سُنٛد ہتھیار بردار اوس نہٕ۔ تکیازِ تس اوس کھوژان۔ تہٕ ساؤلن تُل تلوار تہٕ پیوٚو اتھ پیٹھ۔ {بدسلوکی کٔرِو: یا، مَضموٗن کٔرِو}\n5. تہٕ ییلہ تٔمۍ سٕندِس ہتھیار بردارس وُچھ زِ ساؤل چُھ موٗدمُت، سُہ پیوٚو تلوارِ پیٹھ، تہٕ موٗد۔\n6.\\tیێلہِ گۆو ساؤل تہٕ تٔمۍ سٕندِ تریہ نیچوۍ تہٕ تٔمۍ سُند سارِوٕے گرٕ موٗد اِکہٕ وٹہٕ۔\n7. تہٕ ییلہ وادی منز موجود سارِنٕے اسرائیلٕکۍ لُکو وُچھ زِ تِم ژٔلِتھ ژٔلِتھ تہٕ ساؤل تہٕ تٔمۍ سٕندِس نیچوۍ گٔیہِ مٔرۍمٕتۍ، تِمو ژٔلِتھ تہٕ فلسطینی آیہِ تِمن منز بسنہٕ۔\n8.\\tتہٕ پوٚت دۅہہ ییلہ فلسطینی مقتولن کُن کڈنہِ آیہ، تِمو وُچھ ساؤل تہٕ تٔمۍ سٕندِس نیچوۍ گِلبوع کِس پہاڑس مَنٛز پیوٚو۔\n9. تہٕ ییلہ تِمو أمِس کلہٕ تہٕ تٔمۍ سُند ہتھیار رٔٹِتھ تہٕ سوزُکھ فلسطینن ہٕندِس ملکس منز، یُس پننین بتن تہٕ لوکن تام خبر واتناونہٕ خٲطرٕ۔\n10. تہٕ تِمو تھوو تٔمۍ سُند ہتھیار پننین دیوتاہن ہٕندِس گرس منز، تہٕ کوٚرُن تٔمۍ سُند کلہٕ ڈاگون کِس مندرس مَنٛز۔\n11. تہٕ یێلہِ سارِوٕے جبیشگیلد سُہ سورُے بوز یُس فلسطینیو ساؤلس سٍتـ̡ کورمُت اوس،\n12.\\tتِمو ؤتھۍ، سارِوٕے بہادر نفر، تہٕ نِیُکھ ساؤل سٕنز لاش تہٕ تٔمۍ سٕندٮ۪ن نیچوین ہٕنزِ لاشہٕ تہٕ أنِکھ جابیش نِش تہٕ کٔرٕکھ یِمن ہٕنزِ أڈجہِ جابش کِس بلوطس تَل دفن، تہٕ کٔرٕکھ ستن دۅہن روزہٕ۔\n13.\\tیێلہِ ساؤل موٗد پننہِ گناہ کِنۍ یُس تٔمۍ خداوند سٕندِس کلامَس خٕلاف کٔر، یُس نہٕ تٔمِس رٲچھ کٔرِتھ، تہٕ یُس نہٕ تٔمِس سٍتـ̡ پرژھہٕ گٲر کرنہٕ خٲطرٕ {مشورہ} منگنہٕ خٲطرٕ۔ {کمیٹڈ: ہیب۔ خلاف ورزی کرنہٕ}\n14.\\tتہٕ کٔرٕن نہٕ خداوند سٕندِس سٍتـ̡ پرژھہٕ، تێمہِ مٲرِتھ تہٕ دیتُن بادشاہت یسی سٕندِس نیچوِس داؤدس کُن۔ {جیسی: ہیب۔ ایسائی}","1. اَمہِ پَتہٕ گٔیہِ سارِوٕے اِسرٲیلِس سٍتـ̡ داؤدس سٍتـ̡ حبرونس کُن جمع تہٕ وونُن، وُچھِو أسـ̡ تُہٕندِس أڈجہِ تہٕ تُہُند ماز ۔\n2. تہٕ پٔتِمہِ زمانس مَنٛز، ییلہِ ساؤل بادشاہ اوس، تہٕ یُس اسرٲیلَس مَنٛز دِنہٕ آمُت اوس، تہٕ خداوند تُہٕندِس خداہَن ووٚن تۅہہِ زِ تُہۍ کٔرِو میانین لوکَن اسرٲیلس کھٮ۪وان تہٕ میانہِ قوم اسرٲیلَس پؠٹھ کٔرٕکھ حُکوٗمَت۔ {وقتس منز...: ہیب۔ راتھ تہٕ تریم دۅہ} {فیڈ: یا، قاعدہ}\n3. تێمہِ کِنۍ آیہِ اسرٲیلٕکۍ سٲری زِٹھۍ بادشاہس نِش ہیبرون کُن۔ تہٕ داؤدن کوٚر خداوند سٕندِ برونہہ کُن ہیبرونس مَنٛز تِمن سٍتـ̡ عہد ۔ تہٕ تِمو بنوو داؤد سموئیل سٕندِ کلام مُطٲبق اسرٲیلِس پیٹھ بادشاہ۔ {by: Heb. اتھہٕ سٍتۍ }\n4.\\tتہٕ داؤد تہٕ سارِوٕے اسرٲیل گٔے یروشلمس کُن، یُس {چُھ} یبوس۔ ییتہِ یبوسی ٲسۍ، زمینکۍ بسکین۔\n5.\\tتہٕ یبوسٕکۍ بسکینو ووٚن داؤدس زِ ژٕ گژھ نہٕ یور یِنہٕ۔ بہر حال، ڈیوڈن نیو صہیونک قلعہ، یُس {چُھ} ڈیوڈ سُند شہر چُھ۔\n6. تہٕ داؤد ووٚن زِ یُس یبوسیَن گۅڈٕ مارِ سُہ آسہِ سردار تہٕ کپتان۔ چنانچہ زریاہ سُند نیچو یوآب ووت گۅڈنچہ لٹہِ، تہٕ اوس سردار۔ {چیف: ہیب۔ ہیڈ}\n7. تہٕ داؤد اوس قلعس مَنٛز روزان۔ لہذا وون تمو اتھ شہر ڈیوڈ۔ {یہ: یعنی صیون}\n8. تہٕ تٔمۍ بنوو شہر اندۍ پکھۍ، یێلہِ تہِ میلو پیٹھٕ تہِ، تہٕ یوآبن کٔر باقی شہرٕچ مرمت۔ {مرمت: ہیب۔ بحال کرنہٕ}\n9.\\tیێلہِ گۆو داؤد سٍتـ̡ بٔڈ تہٕ بٔڈ تہٕ بٔڈ تہٕ لشکرن ہُند رب اوس أمِس سٍتـ̡ ۔ {ویکسڈ...: ہیب۔ گٔیہِ گَژھان تہٕ ہُریر}\n10.\\tیِم تہِ چِھہ طاقتور نفرن ہُند سردار یُس داؤد سٕندِس بادشاہتس مَنٛز پانس سٍتـ̡ مضبوط، {تہٕ} سارِنٕے اسرٲیلِس سٍتـ̡ بادشاہ بناونہٕ مۅکھہٕ، یُس اسرٲیلِس مُتلق خداوند سٕندِ کلامَس مُطٲبق بادشاہ بنوو۔ {مضبوط...: یا، تس سٍتۍ مضبوطی سان رٔٹتھ}\n11. تہٕ یہِ چُھ تِمن طاقتور نفرن ہُند تعداد یُس داؤد سٕندِس سٍتـ̡ اوس۔ یشوبیم، یُس کپتانن ہُند سردار: تٔمۍ تُل پنُن نیزٕ اکی ساتہٕ تریہ ہتھ مارنہٕ آمتس خلاف ۔ {an Hachmonite: یا، Hachmoni سُند نیچو}\n12.\\tتہٕ أمِس پَتہٕ اوس الیعزر یُس ڈوڈو سُند نیچو اوس، یُس ترٮ۪ن طاقتورن مَنٛز اکھ اوس۔\n13.\\tسُہ اوس داؤدس سٍتـ̡ پسدمیمس مَنٛز، تہٕ تتہِ گٔیہِ فلسطینی جنگہٕ خٲطرٕ جمع کرنہٕ، یتہِ اوس جوہٕ سٍتـ̡ بٔرِتھ زمینہٕ ہُند اکھ ٹُکر۔ تہٕ لُکھ ژٔل فلسطینن برونہہ کُن۔ {پَسدَمِمِم: یَتھ تہِ وَننہٕ یِوان، اَفسدَمِمِم}\n14.\\tتہٕ تِمو کٔرِکھ پان اتھ پارسلس منز، تہٕ دِژُکھ فلسطینی مار۔ تہٕ خداوند بچٲو تِمن ہٕندِس بٔڈِس نجات سٍتـ̡ ۔ {سیٹ...: یا، کھڑا} {نجات: یا، نجات}\n15.\\tوۅنۍ گٔیہِ ترہو کپتان داؤد کِس کنہِ کُ تہٕ فلسطینن ہٕندِس لشکرس کٔر رفیم کِس وادی مَنٛز ڈیرٕ۔ {ترے...: یا، تریہ کپتان ترہن پیٹھ}\n16.\\tتہٕ داؤد اوس تمہِ ساتہٕ بیت اللحمس مَنٛز، تہٕ فلسطینن ہٕنز چھاونی ٲس تمہ وقتہٕ بیت اللحمس مَنٛز۔\n17.\\tتہٕ داؤد گوو حسرت تہٕ وونُن، اے کاش میہ دِیہِ بیت اللحم کِس کیورُک آب، یعنی دروازس پیٹھ!\n18.\\tتہٕ تریہ ژٔٹِتھ ژٔلِتھ تہٕ کٔرٕن بیت اللحم کِس کۅرٕ منزٕ آب یُس دروازس نِش اوس، تہٕ نِتھ داودُس نِش تہٕ دٲیود نِش دِژُن مگر داودُن نہٕ یہِ چیوٚو، مگر داودُن چُھہ نہٕ یہِ چیوٚن، مگر دٲیود دِژُن نہٕ یہِ چیوٚن، مگر دٲیود دِژُن نہٕ یہِ چُھہ خداہس سٍتـ̡ ترووُن،\n19.\\tتہٕ وونُن، میانہِ خدایہ کرِ میہ یہ کتھ کرُن: کیا بہٕ چُھس یمن نفرن ہُند خون چیوان یمو پنٕنۍ جان خطرس منز ترٛٲومٕژ چھےٚ؟ تکیازِ تِمن ہٕنزِ زندگی ہٕندِس خطرس سٍتۍ اوٚن تمو یہِ۔ لہذا اوس نہ سہ یہ چیوان۔ یمو چیزو کٔر یم تریہ طاقتور۔ {یُس چُھ...: ہیب۔ تہنزِ زندگیہِ سٍتۍ؟}\n20.\\tتہٕ اَبِشایی یُس یوآب سُند بوے اوس، سُہ اوس ترٮ۪ن ہَتن ہُند سردار: ترٚین ہتن خلاف نیزٕ تُلنہٕ مۅکھہٕ مٲرِتھ مارُن تِمن تہٕ تِمن منز اوس اکھ ناو۔\n21. ترشویو منز اوس سُہ دۄن کھوتہٕ زیادٕ عزت۔ تکیازِ سُہ اوس تِہند کپتان: تاہم اوس نہٕ تٔمۍ {گۄڈنِکِس ترے} تام وٲتِتھ۔\n22.\\tیہویادہ سُند نیچو، یُس کبزیل کِس أکِس بہادر سُند نیچو اوس، یٔمۍ واریاہ کٲم کٔرمٕژ۔ تٔمۍ مٲرِتھ موآبٕکۍ زٕ شیر ہِش نفر: تہٕ سُہ ووت بۄن تہٕ مٲرِن شینہٕ وٲلِس دۅہس منز أکِس کھۄڈس منز اکھ شیر۔ {کُس اوس ...: ہیب۔ عظیم اعمال}\n23.\\tتہٕ تٔمۍ مٲرِتھ اکھ مصری، یُس پانژھ کیوبیٹ تھوٚد اوس۔ تہٕ مصری سٕندِس اتھس منز اوس اکھ نیزٕ ہیوٗ وُننہٕ والہٕ سٕندِس بیمِس ہیوٗ نیزٕ۔ تہٕ سُہ گوٚو أمِس نِش لٔرِتھ تہٕ لٔگِن مصری سٕندِ اتھہٕ منزٕ نیزٕ تہٕ مارُن سُہ پننہِ نیزٕ سٍتۍ۔ {عظیم...: ہیب۔ پیمائش}\n24.\\tیِمو {چیز} کٔر یہویادہ سُند نیچو بنیاہ تہٕ تِمن ہُند ناو اوس ترٮ۪ن طاقتورن مَنٛز آسان۔\n25.\\tوُچھ سُہ اوس ترہن منز عزت، مگر ہیوٚت نہٕ گۅڈنِچہِ تریہ تام وٲتِتھ تہٕ داؤدن تھووُن سُہ پنہٕ نِس رٲچھ کُن۔\n26.\\tلشکر ہٕندِس بہادر سٍتـ̡ تہِ ٲس، یُس یوآب سُند بوے اوس، بیت لحم کِس ڈوڈو سُند نیچو الہانان،\n27. شیموتھ دی ہارورائٹ، ہیلیز دی پیلونائٹ، {شمموتھ: یا، شممہ} {ہارورائٹ: یا، ہاروڈائٹ} {پیلونائٹ: یا، پالٹائٹ}\n28.\\tاِکیش سُند نیچو اِکیش سُند نیچو، ابیزر اینٹوتھیٹ،\n29.\\tسِبیکائی ہُشاطیت، اِلائی آہوہیت، {سِبیکائی: یا، میبونای} {اِلائی: یا، زالمون}\n30.\\tمہرایہ نیٹوپھتھی، بانہ نیٹوفیتھیس نیچو ہیلد، {ہیلد: یا، ہیلب}\n31.\\tاِتھایی یُس گِبیاہ کِس رِبایی سُند نیچو اوس، یُس بنیامین سٕندِس شُرین سٍتـ̡ مُتلِق چُھ،\n32.\\tگاش کِس نالہِ ہُراے ، ابییل اربتھی، {ہُرای: یا، ہِدائی} {ابیئل: یا، ابیالبون}\n33.\\tاعظمویت بہرومی، الیابہ شالبونیٹ،\n34.\\tہاشم گِزونائٹ سٕندِ نیچو، جوناتھن شیج ہراریٹؠ سُند نیچو، {ہاشم: یا، ییشن}\n35.\\tاحیام سَکار سُند نیٚچُو، اِلیفال یُس یُور سُند نیٚچُو، {ساکر: یا، شارار} {ایلیفال: یا، اِلیفلیٹ} {یُور: یا، اہاسبائی}\n36. ہیفر دی میکیراتھیٹ، احیاہ پیلونائٹ،\n37.\\tہیزرو کارمیلیٹ، نارائی ایزبائی سُند نیچو، {حزرو: یا ہیزرائی} {نارائی: یا پارائی دی اربِٹ}\n38.\\tجوئل، ناتھن سُند بوے میبھر، ہگری سُند نیچو میبھر، {نیچو...: یا، ہاگریٹ}\n39.\\tزیلیک عمونیت، نہارائی بیروتھی، زرویاہ سُند نیچو یوآب سُند ہتھیار بردار،\n40. ایرا دی ایتھرائٹ، گریب دی ایتھرائٹ،\n41.\\tاوریاہ حتی، زباد، اہلایی سُند نیچو،\n42.\\tشیزہ روبینیٹ سُند نیچو عدینہ تہٕ تٔمِس سٍتـ̡ ترہ\n43.\\tحنان ماخہ سُند نیچو تہٕ یوشافات مِثنی،\n44.\\tعزیہ آشترتھی، شماع تہٕ جہیل، ہوتھن ارورائٹ سٕندۍ نیچوۍ،\n45.\\tشیمری سُند نیچو جدیئل، تہٕ جوہا تٔمۍ سُند بوے تیزیت، {نیچو...: یا، شمریت}\n46.\\tالعیل مہاوی تہٕ یِریبائی تہٕ یُشوِیاہ یُس النعم سٕندِ نیچوِ، تہٕ اِتھمہ موآبِی،\n47. ایلیل، تہٕ اوبید، تہٕ جیسیل دی میسوبیٹ۔","1.\\tوۅنۍ چھہِ یِم داؤدس نِش زِکلاگ کِس نِش آمٕتۍ، ییلہ زن سُہ کیش سُند نیچو ساؤل سٕندِ مۅکھہٕ پانس نزدیک، تہٕ تِم ٲسۍ جنگہٕ کین مددگارن مَنٛز آسان۔ {ییلہ زن ...: ہیب۔ وُنہِ تہِ چھُ بنٛد کَرنہٕ آمُت}\n2. {تِم ٲسۍ کمانو سٍتـ̡ مسلح تہٕ دٔچھُن تہٕ کھوورِ اتھہٕ کمان سٍتـ̡ استعمال کٔرِتھ، حتیٰ کہ ساؤل سٕندِس بٲے سٍتـ̡ {یێلہِ} کمانہٕ سٍتـ̡ کٔرِتھ ہیکان۔\n3.\\tسردار اوس احیزر، پتہٕ یواش، شیمعہ سٕندِ نیچوۍ۔ تہٕ جیزیل، تہٕ پیلٹ، ازماوتھ سٕندۍ نیچو۔ تہٕ بیراچا، تہٕ یہو انتوتھی، {شیماہ: یا، ہسماہ}\n4.\\tتہٕ اسماعیاہ گبیون، یُس ترہن منز تہٕ ترہن کھوتہ زیادٕ طاقتور شخص۔ تہٕ یرمیاہ تہٕ جہازیل، تہٕ جوحان، تہٕ جوساباد گیدرتھائی،\n5. ایلوزائی، تہٕ یرموت، تہٕ بیلیا، تہٕ شیماریہ، تہٕ شیفطیہ ہاروفی،\n6. الکناہ تہٕ یسیاہ تہٕ عزریل، تہٕ جوزر تہٕ یشوبیم، کورہِی،\n7.\\tتہٕ یُلہ تہٕ زبادیہ، یِم گیدور کِس یروہام سٕندِ نیچوۍ۔\n8.\\tتہٕ گادِیو کٔر پان داؤدس نِش بیابانن ہٕندِس قبضس مَنٛز، {تہٕ} جنگہٕ خٲطرٕ موزوں جنگہٕ خٲطرٕ، یِم ڈھال تہٕ بکلرس سمبھالِتھ ہیکن، یِمن ہٕندِس بُتھِس سٍتـ̡ شیرن ہٕندِس بُتھِس ہِش ٲسۍ، تہٕ {ٲس} تِتھۍ تیز رفتار۔ {جنگ: ہیب۔ ہوسٹ سُند} {یُس تیز رفتار...: ہیب۔ یتھے پاٹھۍ پہاڑن پیٹھ کۅکرِ جلدی کرنہ خاطرہ}\n9.\\tایزر گۅڈنچہ، عوبیہ دۆیم، الیاب تریم\n10. مشمنہ ژوٗرم، یرمیاہ پٲنژم،\n11. عطائی شیم، ایلیل سٔتِم،\n12. جوحنان ٲٹھم، العباد نٔوِم،\n13. یرمیاہ دٔہِم، مچبانائی کٔہِم۔\n14.\\tیِم ٲسۍ گاد سٕندِس نیچوِس منز، لشکرٕکۍ کپتان: اکھ کم از کم {اوس} ہتھ کھۅتہٕ زیادٕ، تہٕ سارِوٕے کھۄتہٕ بٔڈ ساس کھۅتہٕ۔ {اکھ...: یا، اکھ یُس کم از کم ہتھ ہتھ مقابلہ ہیکہِ کٔرتھ، تہٕ سارِوٕے کھۄتہٕ بٔڈ ساس}\n15. یِم {چھِ} تِم یِم گۅڈنِکِس رٮ۪تس مَنٛز اردنس مَنٛز گٔیہِ، ییٚلہِ سُہ تٔمۍ سٕندِس سارِنٕے بٔٹھِس مَنٛز ژٔلِتھ اوس۔ تہٕ تِمو کٔر سارِنٕے وادی ژلنہٕ، {دۄشوے} مشرقس کُن تہٕ مغربس کُن۔ {اوور فلو: ہیب۔ بٔرِتھ کٔرِتھ}\n16. تہٕ بنیامین تہٕ یہوداہ سٕندِ اولادٕ سٕندِس تھپھس مَنٛز ووت داؤد۔\n17. تہٕ داؤد دراو تِمن سمکھنہٕ خٲطرٕ، تہٕ دیتُن جواب تہٕ وونُن، یێلہِ تہٕ یێلہِ یێلہِ تہٕ میانین دُشمن سٍتـ̡ چُھہ نہٕ کانہہ غلطی وُچھِتھ، سانین مٲلن ہُند خدا چُھہ اَتھ کُن وُچھان۔  تہٕ ملامت کٔرِو {یہ}۔ {مِلنہٕ خٲطرٕ...: ہیب۔ تِمن برٛونٛہہ} {بٔنِتھ: ہیب۔ اکھ گژھُن} {غلط: یا، تشدد}\n18.\\tاَمہِ پَتہٕ آو اَماسایی یُس کپتانن ہُند سردار اوس، {تہٕ تٔمۍ ووٚن}، تُہُند {چھُ} داؤد، تہٕ تُہٕندِس طرفہٕ، یسیٰ سُند نیچو: امن، امن تہٕ تسٕندٮ۪ن مددگارن ہُند امن {آسُن}۔ تکیازِ تُہند خدا چُھ تۅہہِ مدد کران۔ پتہٕ کٔر ڈیوڈس تِم رٔٹِتھ تہٕ بنووُن تِم بینڈُک کپتان۔ {آو...: ہیب۔ پلو لٲگِتھ}\n19.\\tتہٕ داؤدس سٍتـ̡ آو منسیٰ سٕندِس سٍتـ̡ ییلہ سُہ فلسطینن سٍتـ̡ ساؤلس خلاف جنگہٕ خٲطرٕ آو، مگر تِمو کٔر نہٕ تِمن مدد، تکیازِ فلسطینن ہٕندِس مٲلکَن ہٕندِس مشورس پیٹھ سوٗزُن سُہ یہِ ونِتھ زِ سُہ گژھہِ پننِس آقا ساؤلس سٍتـ̡ سٍتـ̡ {کُن...: ہیب۔ سانین کلن پیٹھ}\n20.\\tییلہ سُہ زِکلاگ گٔیہ، تتہِ آو أمِس نِش مناسیح، عدنہ تہٕ جوزآباد، تہٕ یِمن ہٕندِس مَنسِس سٍتـ̡ دِنہٕ آمُت۔\n21.\\tتہٕ تِمو کٔر ڈیوڈس سٍتـ̡ روورَن ہٕندِس جمٲژ خٕلاف مدد: تِکیازِ تِم ٲسۍ سارِنٕے بہادر نفر تہٕ لشکرس مَنٛز کپتان۔ {خلاف...: یا، بینڈس سۭتۍ}\n22.\\tتکیازِ دۅہہ دۅہہ اوس داؤدس نِش تٔمِس مدتھ کرنہٕ خٲطرٕ یوان، یوتام سُہ خدایہ سٕندِ میزبان سٕندۍ پٲٹھۍاکھ بۆڈ میزبان اوس۔\n23. تہٕ یِم {چِھ} تِمن جمٲژن ہُند تعداد {یُس} جنگہٕ خٲطرٕ تیار ٲس، {تہٕ} آیہ داؤدس نِش حبرون، یُس خداوند سٕندِ کلامٕ مُطٲبق ساؤل سٕنز بادشٲہی پانس کُن پھیرنہٕ مۅکھہٕ۔ {بینڈ: یا، کپتان، یا، مرد: ہیب۔ ہیڈز}\n24.\\tیہوداہٕکۍ بچہٕ یِم ڈھال تہٕ نیزٕ نِش ٲسۍ، ٲسۍ شیہ ساس ٲٹھ ہتھ جنگہٕ خٲطرٕ تیار۔ {ہتھیار بند: یا، تیار}\n25.\\tشمعون سٕندِ شُرین منز، جنگہٕ خٲطرٕ بہادر نفر، ستھ ساس تہٕ ہتھ۔\n26.\\tلیوی سٕندِس شُرین منزٕ ژور ساس شیہ ہتھ۔\n27.\\tتہٕ یہویادا اوس ہارونٮ۪ن ہُند سردار، تہٕ أمِس سٍتـ̡ ٲسۍ ترے ساس ستھ ہتھ۔\n28.\\tتہٕ زادوک، اکھ بہادر نوجوان، تہٕ پننِس مٲلہِ سٕندِس گرس سٍتۍ وُہن تہٕ زٕ کپتان۔\n29.\\tتہٕ بنیامین سٕندِس شُرِس منز، یُس ساؤل سٕندِس رشتہٕ سٍتـ̡ اوس، ترے ساس، تکیازِ یِمو منزٕ اوس وُنیُک بٔڈ حصہ شاؤل سٕندِس گرس ہُند رٲچھ تھاوان۔ {رشتہ دار: ہیب۔ برادران} {عظیم ترین...: ہیب۔ تمن منز اکھ تعداد}\n30. تہٕ افرائیم سٕندِ شُرین منزٕ وُہ ساس ٲٹھ ہتھ بہادر نفر، یُس پننین مٲلن ہٕندِس گرس منز مشہوٗر۔ {مشہور: ہیب۔ مین آف ناون }\n31.\\tتہٕ مناسی ہٕندِس نصف قبیلس منزٕ ارداہ ساس، یُس ناوٕ سٍتـ̡ ظٲہر اوس کرنہٕ آمُت، یُس داؤد بادشاہ بنوو۔\n32.\\tتہٕ اِساکر سٕندِس اولادَس منز، یِمن زمانُک سمجُن اوس تہٕ یہِ زاننہٕ خٲطرٕ زِ اسرٲیلِس کیا پزِ کرُن۔ تِمن ہٕندۍ کلہٕ ٲسۍ زٕ ہتھ؛ تہٕ تِہندِ سٲری بٲے ٲسۍ تہندِس حکمس پیٹھ۔\n33.\\tزبولُن سٍتـ̡ یُس جنگہٕ خٲطرٕ نیران اوس، جنگُک مٲہر، جنگٕکۍ تمام آلات، پنژاہ ساس، یُس درجہٕ برقرار تھٲوِتھ ہیوٚک: {تِم ٲسۍ نہٕ دوٚگنہٕ دِلٕک﴾۔ {ماہر...: یا، رینجرس آف بیٹل، یا، جنگس منز رینج} {رَکُن...: یا، سیٹ کٔرِو جنگ صفس منز} {نہ...: ہیب۔ دِل تہٕ دِل ورٲے }\n34. تہٕ نفتالی سٕندِ ساس کپتان، تہٕ تِمن سٍتـ̡ ڈھال تہٕ نیزٕ ہیتھ ترہ ستھ ساس۔\n35.\\tتہٕ ڈینِین ہٕندِس جنگس مَنٛز مٲہر، وُہُہ ٲٹھ ساس تہٕ شیہ ہتھ۔\n36.\\tتہٕ آشرس سٍتـ̡ یُس جنگس منز نیرِ، جنگُک ماہر، ژتٲجی ساس۔ {ماہر: یا، پنُن درجہٕ برقرار تھاوُن}\n37.\\tتہٕ اردن کِس دوٚیمہِ طرفہٕ روبینن تہٕ گادِس تہٕ مناسی ہٕندِس نصف قبیلس سٍتـ̡ جنگہٕ خٲطرٕ پرٮ۪تھ قٕسمٕکۍ آلہٕ ہیتھ اکھ ہتھ تہٕ وُہ ساس۔\n38.\\tیِم سارِنٕے جنگی نفر یِم درجہٕ برقرار تھٲوِتھ، آیہِ حبرونس کُن کامل دِل ہیتھ داؤد سٲرۍسٕے اسرٲیلِس پیٹھ بادشاہ بناونہٕ خٲطرٕ۔\n39. تہٕ تِم ٲسۍ داؤدس سٍتـ̡ تریہ دۅہہ، کھٮ۪وان چیوان تہٕ تِمن ہٕندِ خٲطرٕ اوس تِمن ہٕندِ خٲطرٕ تیار کورمُت۔\n40.\\tیِم یِمن نزدیکی ٲسۍ، یِمو تہٕ یِمن نزدیک، اِساکر، زبولُن تہٕ نفتالی ہٕندِس تام، گَرَن تہٕ اونٹَن تہٕ خچرن پیٹھ، تہٕ بیلن پیٹھ، ماز تہٕ کھٮ۪ن، انجیر تہٕ کشمش ہٕندِس گٔنڈِس تہٕ شراب، تہٕ تیٖل، تہٕ بیلن تہٕ کۅکرَن ہٕندِس سٍتـ̡ اَننہٕ آمُت۔ {ماز...: یا، کھٮ۪نُک وکٹوال}","1.\\tتہٕ داؤد کٔر ساسہٕ بٔدۍ تہٕ ہتہٕ کپتانن سٍتۍ مشورٕ۔\n2. تہٕ داؤدن ووٚن اسرٲیلٕچ سارنٕے جمٲژ سٍتـ̡، یێلہِ تہٕ یێلہِ یہِ چُھہ تۅہہِ سٍتـ̡ رٔسـ̡ سٍتـ̡ پى۪ٹھـ̡ پى۪۪ٹھـ̡ پى  تاکہ تِم گژھن اسہِ نِش جمع گژھن: {سوز...: حب۔ پھٔٹِتھ تہٕ سوزُن} {تِمن منز...: ہیب۔ تہندِس مضافاتی شہرن منز}\n3. تہٕ أسۍ اَنِو پنُن خدایہ سُند صندوق پانس نِش دُبارٕ، تکیازِ أسۍ اوس نہٕ ساؤل سٕندِس دۅہَس مَنٛز اتھ سٍتـ̡ پرژھان۔ {انن...: ہیب۔ انُن}\n4.\\tتہٕ سارِنٕے جمٲژ ووٚن زِ تِم کرِ یہِ یِتھ، تِکیازِ سارِنٕے لُکن ہٕندِس نظرِ منز اوس یہِ صحیح۔\n5.\\tتہ کٔر داوُد سارِنٕے اسرٲیلِس سٍتـ̡ سٍتـ̡ کِرجاتجیرِم پى۪ٹھہٕ خدایہِ سُند صندوق اننہٕ خٲطرٕ۔\n6. تہٕ داؤد ووت تہٕ سارِوٕے اسرٲیل، بعلہ کُن، یُس یہوداہ سٍتـ̡ اوس، تتہِ خدایہِ سُند صندوق تُلنہٕ خٲطرٕ، یُس کرُبِمن درمِیان روزان چُھ، یُس {اَتھ پیٹھ} ناو چُھہ وننہٕ آمُت۔\n7.\\tتہٕ تِمو تُل خدایہ سُند صندوق أکِس نٔوِس گاڑِس منز ابیناداب سٕندِ گرٕ منزٕ نِش نیبر۔ {کیریڈ...: ہیب۔ سوارِ خٲطرٕ بنوو صندوق}\n8. تہٕ داؤد تہٕ سارِوٕے اِسرٲیلَن گِندُکھ خدایہِ سٍتـ̡ سارِوٕے طاقتہٕ سٍتـ̡ تہٕ گیونہٕ سٍتـ̡ تہٕ ہارپَن سٍتـ̡ تہٕ زبورو سٍتـ̡ تہٕ زنگوو سٍتـ̡ ۔ {گیون: ہیب۔ گیون}\n9. تہٕ ییلہ تِم چِڈون کِس تھریشنگس پیٹھ وٲتۍ، عُزاہن تروو صندوقس رٹنہٕ خٲطرٕ اتھہٕ۔ تکیازِ بیلن لوٚگ ٹھوکر۔ {چیڈن: یتھ ناچون تہِ ونان چھِ} {ٹھوکر: یا، ہلٲوِو}\n10.\\tتہٕ خداوند سُند غصہٕ آو عزا سٍتـ̡ دِنہٕ، تہٕ تٔمۍ دِژ أمِس مُتٲثِر، تِکیازِ تٔمۍ تھووُن صندوقس پیٹھ اتھہٕ، تہٕ تتہِ موٗد سُہ خدایہ سٕندِس برونہہ کُن۔\n11.\\tتہٕ داؤد گوٚو ناراض، تکیازِ خداوند اوس عزاہس خلاف ورزی کٔرمٕژ، لہذا چھہ از تام اتھ جایہ پیریزہ ونان۔ {پیریززا: یعنی عزا سٕنز خلاف ورزی}\n12. تہٕ داؤد اوس تمہِ دۅہہ خدایہِ سٕندِ سٍتـ̡ کھوژان تہٕ وونُن، بہٕ کِتھ کٔنۍ اَنہٕ خدایہِ سُند صندوق پانس نِش۔\n13.\\tتێلہِ اوٚن نہٕ داوُد سٕندِس شہرس منز صندوق پانس نِش بلکہ نِیوُن اوبیدیڈوم گِتیت سٕندِس گَرَس مَنٛز۔ {اننہٕ: ہیب۔ ہٹاونہٕ آمُت}\n14.\\tتہٕ خدایہ سُند صندوق روٗد اوبیڈوم سٕندِس عیالس سٍتـ̡ تریہ ریتس منز۔ تہٕ خداوند کٔر اوبیڈوم سٕندِس گرس تہٕ تٔمِس سارِنٕے سٍتـ̡ برکت۔","1. وۅنۍ سوُزۍ صور کِس بادشاہ حیرامس داؤدس نِش قاصد تہٕ دیودارن ہٕنز لٔکٕر، تہٕ تٔمِس مکانہٕ بناونہٕ خٲطرٕ۔\n2. تہٕ داؤد وُچھ زِ خداوند چُھ تٔمِس اسرٲیلِس پیٹھ بادشاہ بنوومُت، تکیازِ تٔمۍ سٕنز بادشاہت ٲس تٔمۍ سٕندِس لُکہٕ اسرٲیلس سٍتـ̡ تھزراونہٕ آمٕژ۔\n3. تہٕ داؤد کٔر یروشلمس مَنٛز بییہ زنانہٕ، تہٕ داؤدس زاے بییہ نیچوۍ تہٕ کورِ۔ {مٔزیٖد : ہیب۔ توتہِ}\n4. وۅنۍ چھہِ یِم {تٔمِس̡ شُرین ہٕندِ ناو یِم تٔمِس یروشلمس مَنٛز ٲسۍ۔ شموع تہٕ شوباب، ناتھن تہٕ سلیمان،\n5. تہٕ اِبہار، تہٕ الیشوا، تہٕ ایلپالیٹ،\n6. تہٕ نوگاہ، تہٕ نیفیگ تہٕ یافیہ،\n7. تہٕ الیشما، تہٕ بیلیادا، تہٕ ایلیفلیٹ۔ {بیلیاڈا: یتھ الیاڈا تہِ ونان چھہِ}\n8. تہٕ ییلہِ فلسطینیو یہِ بوٗز زِ داؤد چُھ سارِنٕے اسرٲیلِس پیٹھ بادشاہ مقرر کرنہٕ آمُت، سٲری فلسطینی گٔیہِ داؤد سٕندِس سٍتـ̡ ژھانڈنہٕ خٲطرٕ۔ تہٕ داؤد بوز تہٕ دراو تمن خلاف نیبر۔\n9.\\tتہٕ فلسطینی آیہِ تہٕ پھٔہلٲوِتھ وادی رفایمس مَنٛز۔\n10.\\tتہٕ داؤدَن پرژھ خدایہِ سٍتـ̡ وونُن، کیا بہٕ گژھہٕ فلسطینن سٍتـ̡ مقابلہٕ؟ تہٕ کیا ژٕ کٔرِکھ تِم میٲنِس اتھس منٛز؟ تہٕ خداوندَن ووٚن أمِس ہیوٚر ہیوٚر۔ تکیازِ بہٕ دِیہ تم چانہِ اتھس منز۔\n11. تہٕ تِم وٲتۍ بعلپرزیم نِش۔ تہٕ ڈیوڈن دِژ تِمن تتہِ مار۔ اَمہِ پَتہٕ ووٚن داؤد، خداین چُھ میانین دُشمنن پیٹھ میانہِ اتھہٕ سٍتـ̡ ژٔٹِتھ ژٔٹِتھ آبہٕ پھُٹنہٕ سٍتـ̡ ژٔٹِتھ ژٔلِتھ ژٔٹِمٕژ: اَمہِ مۄکھٕ وَنُن تِمو تَمہِ جایہِ ہُند ناو بَلپیرازِم۔ {بعلپیرازم: یعنی، خلاف ورزی ہنز جاے}\n12. تہٕ ییلہ تِمو پَنٕنـ̡ دیوتا اَتہِ ترٲوِتھ، داؤدَن دِیُت حُکُم، تہٕ تِم دِیُت نارٕ سٍتـ̡ زالنہٕ۔\n13. تہٕ فلسطینی پھٔہلِو بییہِ اکہِ لٹہِ وادی مَنٛز۔\n14. تَمہِ کِنۍ پرژھ داؤد دُبارٕ خدایہِ سٕندِس نِش ۔ تہٕ خداین ووٚن أمِس زِ تِمن پَتہٕ گژھ نہٕ تِمن ہٕندِس پَتہٕ کھسنہٕ۔ تِمن نِش پھیُرِو تہٕ تِمن نِش آو شہتوت کُلٮ۪ن پیٹھ۔\n15. تہٕ یێلہِ تہٕ یێلہِ ژے شہتوت کُلٮ۪ن ہٕندِس تینتٲلِس مَنٛز گَژھنٕچ آواز بوزِو، تہٕ تیلہِ گژھہِ ژے جنگہٕ خٲطرٕ نیرُن، تکیازِ خدا چُھ ژے برونہہ کُن دِنہٕ آمُت فلسطینن ہٕندِس لشکرس مارنہٕ خٲطرٕ۔\n16.\\tتێلہِ کٔر داؤد خداین ہُند حُکُم، تہٕ یِمو دِژ فلسطینن ہٕندِس لشکرس گِبعون پیٹھٕ گیزرس تام تہِ۔ {گِبیون: یتھ گیبا تہِ ونان چھِ}\n17.\\tتہٕ داؤد سٕنز شہرت گٔیہِ سارنٕے زمینن مَنٛز۔ تہٕ خداوند دیت سارنٕے قومن پیٹھ أمِس سُند خوف۔","1. تہٕ {داؤد} بنوو تٔمِس داؤد شہرس مَنٛز مکانہٕ، تہٕ خدایہ سٕندِ صندوقہٕ خٲطرٕ جاۓ تیار، تہٕ اَتھ خٲطرٕ کوٚرُن اکھ خیمہٕ۔\n2. اَمہِ پَتہٕ ووٚن داؤد، خدایہِ سُند صندوق پَزِ لاوِیو سٍتـ̡ تُلُن، تِمن خٲطرٕ چُھ خداوند خدایہِ سُند صندوق تُلُن تہٕ ہمیشہٕ خٲطرٕ أمِس خدمت کرنُک انتخاب کوٚرمُت۔ {کانہہ تہِ...: ہیب۔ یہٕ چُھ نہٕ خدایہِ سُند صندوق تُلنہٕ خٲطرٕ، بلکہِ لاوِین ہٕندِ خٲطرٕ}\n3. تہٕ داؤد کٔر سارِنٕے اسرٲیلِس یروشلمس مَنٛز جمع تہٕ خداوند سُند صندوق تُلنہٕ خٲطرٕ، یُس تٔمۍ امہِ خٲطرٕ تیار کورمُت اوس۔\n4. تہٕ داؤد کٔر ہارون سٕندِ بچہٕ تہٕ لاوی سٍتـ̡ جمع ۔\n5.\\tکوہات سٕندٮ۪ن نیچوٮ۪ن ہٕندِ؛ یوریل سردار، تہٕ تٔمۍ سٕندۍ بٲے اکھ ہتھ تہٕ وُہ: {بٲے: یا، رشتہٕ دار}\n6.\\tمیراری سٕندِس نیچوِس منز؛ عسیاہ سردار تہٕ تٔمۍ سٕندِ بٲے زٕ ہتھ وُہ:\n7. گرشوم سٕندِس نیچوِس منز؛ جوئل سردار، تہٕ تٔمۍ سٕندِ بٲے ہتھ تہٕ ترٕہ:\n8. الیزافان سٕندِس نیچوِس منز؛ شمعیہ سردار تہٕ تٔمۍ سٕندِ بٲے زٕ ہتھ:\n9. ہیبرون کین نیچوین منز؛ ایلیل سردار، تہٕ تٔمۍ سٕندِ بٲے ژور سکور:\n10. عزیل سٕندِس نیچوِس منز؛ امیناڈاب سردار تہٕ تٔمۍ سٕنٛدِ بٲے اکھ ہتھ تہٕ باہ۔\n11. تہٕ داؤدن بُلووُن زادوک تہٕ ابیاتھر پادٕرۍ، تہٕ لاوِین ہٕندِس خٲطرٕ، یوریل، عسیاہ تہٕ یوایل، شمعیاہ تہٕ ایلیل تہٕ امِناداب خٲطرٕ۔\n12.\\tتہٕ وونُن تِمَن، یێلہِ چُھہ لاوِین ہٕندِس باپَن ہٕندِس سردارس سٍتـ̡ پان پاک کٔرِو، یێلہِ تُلِو اسرٲیلِکِس خدایہِ سُند صندوق تُلِتھ یُس مے اَمہِ خٲطرٕ تیار کورمُت چھُ۔\n13.\\tکیازِ تۅہہ کٔر نہٕ گۅڈنچہ لٹہِ، خداوند سانہِ خداین کٔر اسہِ خلاف ورزی تہ امہ مۅکھہ زِ أسۍ کٔر نہٕ أمِس مُقرر حُکمہٕ پتہٕ۔\n14. یێمہِ کِنۍ کٔر پادٕرۍ تہٕ لاویو پانس پاکیزٕ کرنہٕ مۅکھہٕ اِسرٲیلِکِس خداوند سُند صندوق تُلنہٕ مۅکھہٕ۔\n15. تہٕ لاوِین ہٕندِ بچہٕ چِھ خدایہِ سٕنز صندوق پننِس پھیکس پیٹھ تُلِتھ، یِتھ کٔنۍ موسیٰ سٕندِ کلامَس مُطٲبق حُکُم دِیُت۔\n16. تہٕ داؤد کٔر لاوِین ہٕندِس سردارس سٍتـ̡ کتھ زِ سُہ کٔرِن پننین باین ہٕندِس بٲے سٍتـ̡ موسیقی، زبور تہٕ ہارپ تہٕ تھپھ ہٕندِس سازس سٍتـ̡ گیون وٲلِس سٍتـ̡ مُقرر کرنہٕ۔\n17. یێمہِ کِنۍ کٔر لیویو ہیمانس یوئیل سُند نیچو مقرر۔ تہٕ تٔمۍ سٕندِس بٲے سُند نیچو آساف۔ تہٕ میراری سٕندِس نیچوِس سٍتـ̡ تِہٕندِس بٲے ایتھن کُشایہ سُند نیچو۔\n18.\\tتہٕ تِمن سٍتـ̡ دۆیمِس بٲے زکرِیاہ، بن تہٕ جازیل، تہٕ شیمیرموتھ، تہٕ یحیێل، تہٕ عُنی، الیاب، تہٕ بنایا، تہٕ ماسیہ، تہٕ متیتیا، تہٕ الیفلہ، تہٕ مکنیہ، تہٕ عوبدیدوم، تہٕ یائیل، قُلۍ۔\n19.\\tتہ گیون والۍ، ہیمان، آصف تہٕ ایتھن، {آیہ مُقرر کرنہٕ}۔\n20.\\tتہٕ زکریا تہٕ عزیل، تہٕ شیمیرموت، تہٕ یہیِیل، تہٕ عُنی، تہٕ الیاب، تہٕ مسییہ، تہٕ بنایہ، الموتھس پیٹھ زبور ہیتھ ۔\n21.\\tتہٕ متیتیا، تہٕ الیفیلیہ، تہٕ مکنیہ، تہٕ اوبیدیدوم، تہٕ جیئل، تہٕ عززیاہ، سٍتـ̡ س� {پیٹھ...: یا، ٲٹھمہِ دۅہہٕ نگرٲنی کرنہٕ خٲطرٕ}\n22.\\tتہٕ چنانیاہ یُس لاوِین ہُند سردار اوس، {اوس} گیونہٕ خٲطرٕ: تٔمۍ کٔر اتھ بٲتس مُتلق ہدایت دِنہٕ، تکیازِ سُہ اوس ہنرمند ۔ {اوس خٲطرٕ...: یا، اوس گاڈِ خٲطرٕ: تٔمۍ دِژ گاڑِ ہٕنز ہدایت} {گیون: ہیب۔ تُلُن}\n23.\\tتہٕ بریخیاہ تہٕ الکانہ ٲسۍ صندوقہٕ خٲطرٕ درِ دار۔\n24.\\tتہٕ شیبانیا، تہٕ یہوشافاط، تہٕ نیتھانیل، تہٕ اماسای، تہٕ زکریا تہٕ بنیاہ تہٕ الیعازر، پادٕرۍ کٔر خدایہ سٕندِس صندوقس برونہہ کُن بُنگے سٍتـ̡ وُنـ̡ تہٕ اوبدیدوم تہٕ یہیاہ {أسـ̡ صندوقہٕ خٲطرٕ دربان۔\n25.\\tیێلہِ گٔیہِ داؤد تہٕ اسرٲیلٕکۍ زِٹھہٕ تہٕ ساسہٕ بٔدۍ سردار گٔیہِ خوشی سان خداوند سٕندِ عہدُک صندوق تُلنہِ۔\n26.\\tتہٕ سپُد یہِ سپدُن، یێلہِ خدایہِ سٕندِ عہدُک صندوق نِش لاوی ہُند مدتھ کٔر، تِمو کٔر سَتھ بیل تہٕ ستھ مینڈٕ۔\n27.\\tتہٕ داؤد اوس نفیس کُنُک پوشاک لٲگِتھ، تہٕ سارِنٕے لاوی یِم صندوقہٕ نِش نِش ٲسۍ، تہٕ گیون والیو تہٕ چنانیاہ اوس گیون والٮ۪ن سٍتـ̡ گیونُک مٲلک۔ {گیون: یا، کیریج}\n28. یِتھٕ پٲٹھۍ تُل سارِنٕے اِسرٲیلَن خداوند سٕندِ عہدُک صندوق کرٛٮ۪کہٕ دِتھ تہٕ کرٛٮ۪کہٕ دِنہٕ سٍتـ̡ تہٕ بُنجہِ ہٕندِ آوازٕ سٍتـ̡ تہٕ زبور تہٕ ہارپَو سٍتـ̡ شور کٔرِتھ۔\n29.\\tتہٕ سپُد یہِ سپُد، یێلہِ خداوند سٕندِ عہدُک صندوق آو داؤد کِس شہرس مَنٛز، زِ شاؤل سٕنزِ کورِ میخال وُچھ دارِ کُن وُچھِتھ بادشاہ داوُد نژان تہٕ گِندان وُچھان، تہٕ تٔمِس کٔر أمِس دِلس منز حقارت ۔","1. یێمہِ سٍتـ̡ اوٚن تِمو خدایہِ سُند صندوق، تہٕ تھووُکھ تتھ خیمس مَنٛز یُس داؤد سٕندِ خٲطرٕ بنوومُت اوس، تہٕ تِمو کٔرٕکھ خدایہِ سٕندِ برونہہ کُن دزنہٕ آمٕژ قربانی تہٕ امن نذرانہ پیش کرنہٕ۔\n2. تہٕ یێلہِ داؤد سٕندِ دَزنہٕ آمٕژ نذرانہ تہٕ امن ہٕنز قربانی دِنہٕ ختم کٔر، تٔمۍ کٔر خداوند سٕندِ ناوٕ سٍتـ̡ لُکن برکت۔\n3. تہٕ تٔمۍ دِژ پرٮ۪تھ أکِس اِسرٲیلِس سٍتـ̡ مرد تہٕ زنانہٕ، پرٮ۪تھ أکِس سٍتـ̡ اکھ روٹی تہٕ اکھ اصل ماز تہٕ شرابُک اکھ جھنڈٕ۔\n4. تہٕ تٔمۍ مقرر کٔر لاوی سٕندِس صندوقس برونہہ کُن خدمت کرنہٕ خٲطرٕ، تہٕ حضرت اسرائیل کِس خداوند سُند شُکر ادا کرنہٕ خٲطرٕ تہٕ تعریف کرنہٕ خٲطرٕ۔\n5.\\tاساف سردار، تہٕ أمِس پَتہٕ زکرِیاہ، جیئیل، تہٕ شیمیرموتھ، تہٕ یہیِیل، تہٕ متیتیاہ، تہٕ الیاب، تہٕ بنایہ، تہٕ عوبیدوم: تہٕ جیئیل زبور تہٕ ہارپ۔ مگر آسافن کٔر کۅکرِ سٍتـ̡ آواز۔ {psalteries سۭتۍ...: Heb. زبور تہٕ ہارپس ہٕندۍ آلات}\n6.\\tبنیاہ تہٕ جاہزیئل تہِ پادٕرۍ یِم خدایہِ سٕندِ عہد کِس صندوقس برونہہ کُن لگاتار بُرق ہیتھ ٲسۍ۔\n7. اَمہِ دۅہہٕ دِژ داوُد اَمہِ دۅہہٕ خداوند سُند شُکر ادا کرنہٕ مۅکھہٕ آصاف تہٕ تٔمۍ سٕندِس بٲے سٕندِس اتھس مَنٛز۔\n8. خداوند سُند شُکر ادا کرُن، تٔمۍ سُند ناو پکار کرُن، تٔمۍ سٕندِ اعمال کٔرِو لوکن مَنٛز ظٲہر۔\n9.\\tأمِس گٮ۪وُن، أمِس گٮ۪وُن زبور، تٔمِس سارِنٕے حیرت انگیز کامہِ ہٕنز کتھ کٔرِو۔\n10. تٔمۍ سٕندِس مقدس ناوس مَنٛز گٔژھِو تِمن ہُند دِل خۅش گژھُن یُس خداوند سٕندِ سٍتـ̡ ژھاران چُھ۔\n11. خداوند تہٕ تٔمۍ سٕنز طاقت ژھارِو، تٔمۍ سُند بُتھ ژھارُن لگاتار ژھارُن۔\n12. تٔمۍ سٕندِ حیرت انگیز کامہِ یاد تھاوُن، تٔمۍ سٕندِ عجائبات تہٕ تٔمۍ سٕندِ ٲسٕکۍ فیصلہٕ۔\n13. اے اسرٲیلٕکۍ اولاد، یعقوب سٕندِ بُرۍ، یعقوب سٕندِ ژٲرِمٕتـ̡ ۔\n14. سُہ چُھ خداوند سُند خدا۔ تٔمۍ سٕندِ فٲصلہٕ {چِھ} سارِنٕے زمینس منز۔\n15. تٔمۍ سٕندِس معاہدُک ہمیشہٕ خیال تھاوُن۔ لفظ {یُس} تٔمۍ ساس نسلن حکم دِیُت۔\n16.\\tیُس معاہدٕ تہِ اوس تٔمۍ ابراہیمس سٍتـ̡ کورمُت، تہٕ اسحاق سٍتـ̡ تٔمۍ سٕندِس حلفس مُتلِق۔\n17. تہٕ یعقوبس سٍتـ̡ چُھہ شریعت خٲطرٕ تصدیق کٔرمٕژ، {تہٕ} اسرٲیلس سٍتـ̡ {یێلہِ} ہُند اَبدی عہدٕ،\n18.\\tیہ ونِتھ زِ بہٕ دِیہ ژے کنعانٕچ زمین، چانہِ وراثتُک حصہٕ۔ {لاٹ: ہیب۔ ڈور}\n19.\\tییلہ تم اتھ منز کم ٲسو، کینہہ تہِ تہٕ اجنبی ٲسۍ۔ {کینٛہہ، حتیٰ کہ: ہیب۔ مرد آف نمبر، وغیرہ}\n20. تہٕ {ییلہ} تِم گٔیہِ قومہٕ پٮ۪ٹھٕ قومس تام، تہٕ {اکہِ} بادشٲہی پٮ۪ٹھٕ بییِس قومس تام۔\n21.\\tأمِس دِژ نہٕ تِمن ہٕندِس مۅکھٕ دِنہٕ آمُت: آ، تٔمۍ کٔر بادشاہن تہندِ خٲطرٕ ملامت\n22.\\t{ونان}، میانہِ مسح کرنہٕ آمٕژ تہٕ میانین پیغمبرن کٔرِو نہٕ کانہہ نقصان ۔\n23. خداوند سٕندِ خٲطرٕ گٮ۪وُن، سارِنٕے زمینہٕ؛ دۅہہٕ دۅہہٕ ہٲوِو تٔمۍ سٕنزِ نجات ہاونہٕ۔\n24. کافرن مَنٛز کٔرِو تٔمِس جلال ہُند اعلان۔ سارنٕے قومن منز چھے تٔمۍ سٕنز حیرت انگیز کٲم۔\n25. خداوند سُند بٔڈ تہٕ سٮ۪ٹھاہ تعریف: سُہ تہِ گژھہِ سارِنٕے دیوتاہن ہٕندِ کھۅتہٕ کھۅتہٕ خوف۔\n26.\\tلوکن ہندِ سارِنٕے دیوتا چِھہ بُت، مگر خداہن بنوو آسمان۔\n27. جلال تہٕ عزت {چھ} تٔمۍ سٕندِس حضورس منز؛ طاقت تہٕ خوشی چھِ أمۍ سٕنٛزِ جایہِ ۔\n28. اے لُکن ہٕندِس رِشتہٕ دارس دِیُو خداوند سُند جلال تہٕ طاقت۔\n29. خداوند سٕندِس ناوس سٍتـ̡ جلال دِیُن: اکھ نذرانہ أنِو، تہٕ أمِس برونہہ کُن یِن: پاکیزگی ہٕنزِ خوبصورتی سٍتـ̡ کٔرِو خداوند سٕنز عبادت ۔\n30.\\tتس برونہہ کُن کھوژُن، سارِنٕے زمینہِ سٍتـ̡ دنیا تہِ گژھہِ مستحکم تہٕ یُس نہٕ ہلاونہٕ یُن۔\n31. آسمانن گژھہِ خۅش تہٕ زمینہِ گژھہِ شاد گژھُن، تہٕ {انسان} قومن مَنٛز وَنُن زِ خداوند چُھ بادشاہت کران۔\n32.\\tسمندرس تہٕ اَمہ سٍتـ̡ گٔژھِو گُرٕنـ̡ تہٕ یێمہِ سٍتـ̡ خۅش سپدُن۔\n33. تیلہِ گژھن لٔکرِ کُلۍ خداوند سٕندِس حضورس سٍتـ̡ گٮ۪ون، کیازِ سُہ چُھ زمینہِ ہُند انصاف کرنہٕ خٲطرٕ یوان۔\n34. اے خداوند سُند شُکر ادا کرُن؛ تکیازِ {سُہ} چُھ اصل؛ تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ خٲطرٕ۔\n35. تہٕ ونُن، اے سانہِ نجات ہُند خدا، اسہِ بچاو، تہٕ اسہِ جمع کرُن، تہٕ اسہِ کٔرِو کافرو نِش بچاو، یُتھ أسۍ چانہِ پاک ناوُک شُکر ادا کٔرِتھ، تہٕ تُہٕندِس تعریفس مَنٛز جلال حٲصِل کٔرِو۔\n36.\\tاسرٲیلُک خداوند خدا گژھہِ ہمیشہ ہمیشہ خٲطرٕ بابرکت ۔ تہٕ سارِوٕے لُکو ووٚن آمین، تہٕ کٔرٕکھ خداوند سٕنز تعریف۔\n37.\\tتێلہِ دراو سُہ خداوند آصف تہٕ تٔمۍ سٕندٮ۪ن باین ہٕندِس عہد کِس صندوق برونہہ کُن، یُس پرٮ۪تھ دۅہدٕچ کامہِ ہٕندِس ضرورتس مُطٲبِق اوس صندوقس برونہہ کُن خدمت کرنہٕ خٲطرٕ:\n38. تہٕ اوبیڈوم پننین باین سٍتۍ، تریہ تہٕ ٲٹھ۔ عوبدیدوم تہِ اوس یہدوتون تہٕ ہوسہ سُند نیچو تہِ:\n39.\\tتہٕ زادوک پادٕر، تہٕ تٔمۍ سٕندِس بٲے پادٕرۍ، خداوند سٕندِس خیمہ برونہہ کُن یُس جبیونس مَنٛز اوس،\n40.\\tصُبحہ تہٕ شامَس دزنہٕ آمٕژ قربان گاہس پیٹھ خداوند سٕندِ خٲطرٕ دزنہٕ نذرانہ پیش کرُن، تہٕ خداوند سٕندِس شریعتس مَنٛز لیکھنہٕ آمٕژ سارِنٕے مُطٲبق کرُن، یُس تٔمۍ اسرٲیلُک حکم دِیُت۔ {صبح...: ہیب۔ صبحس تہ شامس\n41.\\tتہٕ تِمن سٍتـ̡ ہیمان تہٕ یدوتون، تہٕ باقٕے یِم ژارنہٕ آمٕتۍ، یِمن ہُند اظہار اوس کرنہٕ آمُت، خداوند سُند شُکر ادا کرنہٕ خٲطرٕ، کیازِ تٔمۍ سٕنز رحمت چھے ہمیشہٕ خٲطرٕ روزان۔\n42.\\tتہٕ تِمن سٍتـ̡ ہیمن تہٕ یہدوتھُن تِمن ہٕندِ خٲطرٕ یِم آواز تراوٕن، تہٕ خدایہ سٕندِ سازو سٍتـ̡ تہٕ خدایہ سٕندِ سازو سٍتـ̡ ۔ تہٕ جدوتون سٕندۍ نیچوۍ ٲسۍ قُلی۔ {پورٹرز: ہیب۔ گیٹ خٲطرٕ}\n43.\\tتہٕ سارِوٕے لُکھ دراو پرٮ۪تھ أکِس نَفس کُن تہٕ داؤد آو پننِس گرس دُعا دِنہٕ خٲطرٕ واپس۔","1.\\tوۅنۍ سپد یہ سپد ییلہ داؤد پننس گرس منز بِہتھ اوس، داؤد ووٚن ناتھن پیغمبرس زِ بہٕ چُھس دیودار کِس گرس مَنٛز روزان، مگر خداوند سٕندِ عہد کِس صندوقس منز چُھہ پردٕ تلہ روزان۔\n2. پتہٕ ووٚن ناتھنن داؤدس زِ سُہ کٔرِو سُہ سورُے یُس پنہٕ نِس دِلس مَنٛز چُھ۔ تکیازِ خدا چُھ توے سٍتـ̡ ۔\n3.\\tتہٕ امی رٲژ سپد خدایہ سُند کلام ناتھنس نِش وونُن،\n4.\\tگژھ تہٕ میٲنِس خادمَس وَنُن، یِتھٕ پٲٹھـ̡ خداوند چُھ ونان زِ ژے کٔرِو نہٕ مےٚ روزنہٕ خٲطرٕ اکھ مکانہٕ بَناوُن:\n5. یێلہِ بہٕ چُھس نہٕ اَمہِ دۅہہٕ پیٹھٕ کُنہِ گَرَس مَنٛز روزمُت یێمہِ دۅہہٕ یێلہِ بہٕ اِسرٲیلِچ پرورش کٔرمٕژ۔ مگر گٔے خیمہ پیٹھہ خیمہ تام، تہ {اکہ} خیمہ پیٹھہ بییِس خیمہ تام۔ {گٔمٕتۍ: ہیب۔ ہیو بے}\n6. یێتہِ تہِ بہٕ سارِنٕے اسرٲیلِس سٍتـ̡ پکان چُھس، بہٕ کٔر اِسرٲیلِس کُنہِ تہِ قاضس سٍتـ̡ اکھ لفظ، یٔمِس میہ پننین لوکن کھٮ۪نہٕ دِنُک حُکُم دِیُتمُت چُھ، یہِ ونُن زِ ژے کیازِ چُھہ نہٕ میانہِ خٲطرٕ دیودارُک مکانہٕ بنوومُت؟\n7. تێمہِ پٲٹھـ̡ چُھہ تێہہ میٲنِس خادم داوڈس ونُن، یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند رب وَنُن زِ بہٕ چُھہ ژے کُنہِ سٍتـ̡ نِش تہٕ ژے میانین لوکن ہٕندِس اسرٲیلِس پیٹھ حکمران بنُن: {یێلہِ پٲٹھـ̡ ہیب۔ پتہٕ پیٹھ}\n8. تہٕ بہٕ چُھس ژے سٍتـ̡ یێتہِ تہِ پکان چُھ، تہٕ ژے سارِوٕے دُشمن ژٹِمُت تہٕ ژے بنیومُت تِمن بٔڈٮ۪ن نفرن ہُند ناو یُس زمینس مَنٛز چُھ۔\n9. تہٕ بہٕ کَرٕ پننین لوکن ہٕندِ خٲطرٕ اکھ جاۓ مقرر تہٕ تِم کٔرِن تِمن ہٕنزِ جایہِ روزن، تہٕ یِم گژھن نہٕ پنہٕ نِس جایہِ روزنہٕ۔ بد کاری ہٕندِ شُرۍ گژھن تِمن مزید ضایع کٔرِتھ، یِتھ کٔنۍ زَن شروعاتس منز،\n10. تہٕ یێمہِ وقتہٕ پیٹھٕ مے پننین لوکن ہٕندِس اسرٲیلِس پیٹھ قاضین ہُند حُکُم دِیُت۔ اَمہِ علاوٕ کَرٕ بہٕ تُہٕندِس سارِنٕے دُشمن زیر۔ اَمہِ علاوٕ چُھس بہٕ ژےٚ ونان زِ خداوند کرِ ژےٚ اکھ مکانہٕ۔\n11. تہٕ یێلہِ گژھہِ تُہند دۅہ مۄکلیو، تہٕ ژے گژھہِ پننین مٲلن سٍتـ̡ روزُن، تہٕ بہٕ کرٕ چانہِ اولاد، یُس تُہند نیچو آسہِ۔ تہٕ بہٕ کٔرٕ تٔمۍ سٕنٛز بادشاہت قٲیم۔\n12. سُہ بناوِ میہ اکھ مکانہٕ، تہٕ بہٕ کرٕ تٔمۍ سُند تخت ہمیشہٕ خٲطرٕ قٲیم۔\n13. بہٕ بنہٕ تٔمۍ سُند مول تہٕ سُہ بنہٕ میون نیچو: تہٕ بہٕ ہیوٚک نہٕ أمِس نِش پنُن رحم نِش نِتھ، یِتھ کٔنۍ مے ژے برونہہ کُن اوس:\n14. مگر بہٕ کٔرٕ سُہ پننِس گرس تہٕ پننہِ سلطنتس مَنٛز ہمیشہٕ خٲطرٕ بساوُن: تہٕ تٔمۍ سُند تخت گژھہِ ہمیشہٕ خٲطرٕ قایم کرنہٕ۔\n15.\\tیِمو سارِنٕے کلامَو مُطٲبِق تہٕ یِتھٕ پٲٹھۍ کٔر ناتھن داؤدس سٍتـ̡ کتھ کرنہٕ۔\n16.\\tتہٕ داؤد بادشاہ آو تہٕ بیوٹھ خداوند سٕندِس برونہہ کُن، تہٕ وونُن، اے خداوند خدایہ، تہٕ میون مکانہٕ کیا چُھ، یُس ژے مے وُنیُک تام واتنوومُت چُھ؟\n17. تہٕ {توتہِ} یہ اوس چانہِ نظرن منز اکھ لۄکُٹ چیز، اے خدایہ۔ تِکیازِ ژے چُھکھ واریاہس کالس پیٹھٕ پننِس خادم سٕندِس گرس مُتلق کتھ کٔرمٕژ، تہٕ اے خدایہ سٕندِس أکِس تھدِ درجہٕ سٕندِس جایدادٕ مُطٲبق کٔرٕکھ میہ سٍتـ̡ نظر۔\n18.\\tداؤد کیاہ ہیکہِ تۅہہِ سٍتـ̡ پننِس خادم سٕندِ عزتہٕ خٲطرٕ زیادٕ کتھ کٔرِتھ؟ تِکیازِ ژٕ چُھکھ پنٕنِس خادمَس زانان۔\n19.\\tاے خداوند، پنہٕ نِس خادم سٕندِ خٲطرٕ، تہٕ پنہٕ نِس دِلہٕ مُطٲبق، ژے کٔر یِہ سورے عظمت، یِمن سارِنٕے بٔڈ چیزن ہٕنز زانکٲری دِنہٕ خٲطرٕ۔ {عظیم...: ہیب۔ عظمت}\n20. اے خداوند، ژے ہیوٗ کانہہ تہِ چُھہ نہٕ، تہٕ نہ چُھہ تۅہہِ سٍتـ̡ خدایہ، یُس اسہِ پننیو کنو سٍتـ̡ بوزمُت چُھ۔\n21. تہٕ زمینس مَنٛز کُس اکھ قوم چُھہ تُہنزِ قوم اسرٲیلِس ہیوٗ یُس خدایہ پنٕنـ̡ قوم بننہٕ خٲطرٕ گۆو تہٕ تۅہہِ ہُند ناو بَناوُن، یُس تۅہہِ قومن ہٕندِس برٛونٛہہِ کٔڈِتھ تہٕ تُہٕندِس قومن ہُند ناو بَناوُن، یِم ژے مصرہٕ منزٕ نِش نجات دِژمٕژ چھِ۔\n22. پننہِ قومہٕ خٲطرٕ بنوو اسرٲیل، ژے پَنٕنۍ قوم ہمیشہٕ خٲطرٕ۔ تہٕ تُہۍ بنیوو تِہُند خدا۔\n23. تێمہِ کِنـ̡ وۆنـ̡ خداوند، یُس کتھ ژے پننِس خادمس تہٕ تٔمۍ سٕندِس گرس مُتلق کتھ کٔرمٕژ چُھ، سُہ گژھہِ ہمیشہٕ خٲطرٕ قٲیم کرنہٕ یُن، تہٕ یُس ژے وَنُن چُھ، سُہ گژھہِ ہمیشہٕ خٲطرٕ قٲیم کرنہٕ یُن۔\n24. یێلہِ تہِ گژھہِ تُہُند ناو ہمیشہٕ خٲطرٕ بڑاونہٕ یُن، یہِ ؤنِتھ زِ لشکرن ہُند رب چُھہ اسرٲیلُک خدا، تہٕ داؤد سُند گرٕ گژھہِ تُہند خادم تہٕ تُہٕندِس بٔنِس سٍتـ̡ قایم کرنہٕ یُن۔\n25.\\tتکیازِ اے میانہِ خدایہ، ژے چُھہ پننِس خادمس ووٚنمُت زِ ژٕ کٔرِکھ تٔمِس اکھ مکانہٕ بناوُن، تێمہِ مۅکھہ چُھہ تۅہہِ سٍتـ̡ دِل دِنہٕ آمُت۔ {ہسٹ...: ہیب۔ پننس خادمس کٔر کنن ظٲہر}\n26. تہٕ وُن، خداوند، تہٕ چُھکھ پننِس خادمَس سٍتـ̡ یێمہِ نیکی ہُند وعدٕ کورمُت:\n27. تێمہِ کِنۍ گژھہِ ژے پننہِ بندہ سٕندِس گرس برکت دِن، یُتھ سُہ گژھہِ ہمیشہٕ خٲطرٕ توے برونہہ کُن روزُن: اے خداوند، تہٕ یہ گژھہِ ہمیشہٕ خٲطرٕ بابرکت روزُن۔ {چلو...: یا، یہ چُھ ژےٚ خوش گومُت}","1.\\tامہ پتہ سپد یہ سپد زِ داؤد دیت فلسطینن پیٹھ تہ زیر کٔرِتھ تہ نِن گاتھ تہٕ تسند شہر فلسطینن ہٕندِ اتھہ نِش نیران۔\n2. تہٕ تٔمۍ دِژ موآب۔ تہٕ موابی بنیے داؤد سٕندِ خدمتگار، {تہٕ} أنۍ تحفہٕ۔\n3.\\tتہٕ داؤدن دِژ زوبہٕ کِس بادشاہ حدارزرس ہمتھس کُن، ییلہ سُہ دریائے فرات کِس نِش پنُن سلطنت قایم کرنہٕ خٲطرٕ گوٚو۔ {Hadarezer: یا، Hadadezer}\n4.\\tتہٕ داؤد نِش نِش اکھ ساس رتھ تہٕ ستھ ساس گُرۍ سوار تہٕ وُہ ساس پیدل تہِ۔ {ستھ ...: یا، ستھ ہتھ}\n5.\\tییلہ دمشقٕکۍ شامی حضریزر زوبہ کِس بادشاہس مددتہٕ خٲطرٕ آو، داؤدن مارۍ شامی زٕ وُہ ساس نفر۔ {دمشق: ہیب۔ دارمیسیک}\n6. پَتہٕ داؤد تھوو {گیریژن} شامدمشقس مَنٛز۔ تہٕ شامٕکۍ بنیے داؤد سٕندِ نوکر، {تہٕ} أنۍ تحفہٕ۔ یِتھٕ کٔنۍ کٔر خداوند داؤد رٲچھ ییتہِ تہِ گٔیہِ۔\n7.\\tتہٕ داؤد رٔٹِتھ سۄنہٕ سٕنزِ ڈھال یُس حدارزر سٕندِس نوکرَن ہٕندِس سٍتـ̡ ٲس، تہٕ أنِن یِم یروشلمس کُن۔\n8.\\tیِتھے پٲٹھـ̡ تیبھتھ تہٕ چُن پیٹھ، ہدارزر شہرو سٍتـ̡ اوٚن داؤد سٍتـ̡ سٮ۪ٹھاہ پیتل، ییمہِ سٍتـ̡ سُلیمانن بٔنـ̡ سمندرٕ تہٕ تھم تہٕ پیتلٕکۍ بانہٕ۔ {تیبھتھ...: سیموئیل بیتہ تہٕ بیروتھایی سٕنزِ کتابہِ منز وننہٕ آمُت}\n9.\\tوُنہِ ییلہ حمتُک بادشاہ تو بوز زِ کِتھہ کٔنۍ اوس داوُن زوبہ کِس بادشاہ حدارزر سٕندِس سارِنٕے لشکرس مارمُت۔ {Tou: Toi تہِ ونان چھِ}\n10. تٔمۍ سوٗز پنُن نیچو بادشاہ ڈیوڈس نِش، تٔمِس خیریت پرژھنہٕ خٲطرٕ، تہٕ تٔمِس مبارک باد دِنہٕ خٲطرٕ، تکیازِ تٔمۍ اوس ہدارزرس خلاف جنگ کورمُت، تہٕ مارُن أمِس مار۔ (تکیازِ ہڈاریزرس اوس توہس سٍتۍ جنگ کورمُت؛) تہٕ {أمِس سۭتۍ} سۄنہٕ تہٕ رۄپہٕ تہٕ پیتلٕکۍ پرٛٮ۪تھ قٕسمٕکۍ بانہٕ۔ {Hadoram: تہٕ چُھ، Joram تہٕ وننہٕ یوان} {پرژھنہٕ خٲطرٕ...: یا، سلام} {مبارک باد دِنہٕ خٲطرٕ: ہیب۔ برکت دِنہٕ خٲطرٕ} {جنگ: ہیب۔ اوس جنگُک آدمی}\n11. تِمو تہِ کٔر بادشاہ ڈیوڈس رۄپہٕ تہٕ سۄنہٕ سٍتـ̡ یُس سُہ سارِنٕے قومن نِش أنِتھ خداوند سٕندِ خٲطرٕ وقف کورمُت۔ ادوم پیٹھ، تہٕ موآب پیٹھ، تہٕ عمون سٕندِ اولادٕ سٍتـ̡ تہٕ فلسطینی تہٕ عمالیق سٍتـ̡ ۔\n12.\\tزریاہ سُند نیچو ابیشایی مارِ ادومی نوٗنہٕ کِس وادی مَنٛز ارداہ ساس۔ {ابیشائی: ہیب۔ ابشائی}\n13. تہٕ تٔمۍ تھوو ایڈومَس مَنٛز چھاوی۔ تہٕ سٲری ادومی بنییہِ داؤد سٕندِ خدمتگار۔ یِتھٕ کٔنۍ کٔر خداوند داؤد رٲچھ ییتہِ تہِ گٔیہِ۔\n14.\\tیێلہِ کٔر داؤد سارِنٕے اسرٲیلِس پیٹھ بادشاہت تہٕ پننین سارِنٕے لوکن مَنٛز کوٚرُن فیصلہٕ تہٕ انصاف ۔\n15.\\tتہٕ زرویاہ سُند نیچو یوآب اوس لشکرس پیٹھ۔ تہٕ یہوشافعت، احیلود سُند نیچو، ریکارڈر۔ {ریکارڈر: یا، ریمیمبرنسر}\n16.\\tتہٕ احیتوبس سُند نیچو زادوک تہٕ ابیاتھر سُند نیچو ابیمیلک ٲسۍ پادٕرۍ۔ تہٕ شوشہ اوس کاتب۔ {Abimelech: یتھ تہٕ وَننہٕ چُھ یوان، احیمیلک} {شوشہ: یتھ سریا یا شیشہ تہِ ونان چھِ}\n17.\\tتہٕ یہوعیدہ سُند نیچو بنیاہ اوس چیریتھین تہٕ پیلیتھین پیٹھ۔ تہٕ داؤد سٕندِ نیچوۍ ٲسۍ بادشاہس متعلق سردار۔ {متعلق...: ہیب۔ بادشاہ سٕندِس اتھس پیٹھ}","1.\\tامہ پتہ سپد یہ زِ عمون کین بچن ہند بادشاہ ناہش گۆو تہ تسٕندِ جایہ گۆو تٔمۍ سُند نیچو بادشاہ۔\n2.\\tتہٕ داؤد ووٚن بہٕ کٔرٕ ناحاش سٕندِس نیچوِس حنون سٍتـ̡ مہربانی کرنہٕ، تکیازِ تٔمۍ سٕندِس مٲلہِ سٍتـ̡ کٔر میانہِ سٍتـ̡ مہربانی ۔ تہٕ سوٗزۍ داؤد پننِس مٲلِس متعلق تسلی دِنہٕ خٲطرٕ قاصد۔ تہٕ داؤد سٕندِ نوکر آیہِ عمون سٕندٮ۪ن شُرین ہٕندِس ملکس مَنٛز حنون نِش تسٕندِس تسلی دِنہٕ خٲطرٕ۔\n3.\\tمگر عمون سٕندٮ۪ن بچن ہٕندِیو شہزادو ووٚن حنونس زِ ژیہ چھا باسان زِ داؤد چُھ پننِس مٲلِس عزت کران، یێلہِ تٔمۍ سُہ چُھہ تۅہہِ نِش تسلی دِنہٕ وٲلۍ۔ کیا تٔمۍ سٕندِ خادم چھِنہٕ تۅہہِ نِش ژھانڈنہٕ خٲطرٕ تہٕ تختہٕ والنہٕ خٲطرٕ تہٕ زمینٕچ جاسوسی کرنہٕ خٲطرٕ آمٕتۍ؟ {تھنکسٹ...: ہیب۔ تۅہہِ نظرن منز چھہ ڈیوڈ بیترِ}\n4. اَمہِ مۄکھٕ کٔرٕن حَنوُن داؤد سٕندِ نوکر تہٕ کھوٗر کٔرِتھ ژٔٹِتھ تِہٕندِس پَلَو ژٔٹِتھ\n5. پَتہٕ ووت {یقین}، تہٕ وونُن ڈیوڈس زِ نفرن کِتھہ کٔنۍ آیہ خدمت کرنہٕ۔ تہٕ سُہ سوٗز تِمن سمکھنہٕ خٲطرٕ: تِکیازِ مرد ٲسۍ سٮ۪ٹھاہ شرمندٕ۔ تہٕ بادشاہن ووٚن، یریحاہس منز روزُن یوٚت تام تۅہہ داڑھ بٔڈۍ، تہٕ {پتہٕ} واپس۔\n6.\\tییلہ عمون سٕندیو اولادو وُچھ زِ تِمو چُھ داؤدس سٍتـ̡ نفرت کٔرمٕژ، حنون تہٕ عمون سٕندیو اولاوو سوٗزۍ ساس رۄپہٕ رۄپہٕ تِمن میسوپوٹیمیا منزٕ تہٕ شامماچہ منزٕ تہٕ زوبہ نِش رتھٕ تہٕ گُرۍ سوارِ ہٕندِس کرایہٕ سٍتـ̡ ۔ {اوڈیوس: ہیب۔ بدبو}\n7.\\tیِمو کٔرِتھ ترٕہ زٕ ساس رتھ، تہٕ ماچہ ہُند بادشاہ تہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ ۔ یُس آو تہٕ میڈیبا برونہہ کُن پِچ کٔر۔ تہٕ عمون سٕندِ شُرۍ گٔیہِ پننیو شہرو منزٕ جمع تہٕ آیہ جنگہٕ کرنہٕ۔\n8. تہٕ ییلہ داؤدس یہِ بوٗز، تٔمۍ سوٗزۍ یوآب تہٕ سارِنٕے طاقتور لشکر۔\n9.\\tتہٕ عمون سٕندِ بچہٕ دراو تہٕ شہر کِس دروازس برونہہ کُن لٔگِتھ جنگہٕ صفہٕ۔ تہٕ یِم بادشاہ ٲسۍ پانہٕ مٲدانس مَنٛز آمٕتۍ۔\n10.\\tییلہ یوآبن وُچھ زِ جنگ چھہ تس برونہہ تہ پتھ کُن کرنہ آمت، تمٔۍ ژٲر اسرٲیلکۍ سارِوٕے انتخابس منز، تہٕ کورُن شامس خلاف صفہٕ۔ {جنگ...: ہیب۔ جنگُک بُتھ اوس {انتخاب: یا، نوجوان}\n11.\\tتہٕ باقٕے لُکھ یِم أمۍ پننِس بٲیِس ابیشایی سٕندِس اتھس حوالہٕ کٔرِتھ، تہٕ تِمو کٔرٕکھ عمون سٕندِس بچن خلاف صفہٕ کھڑا۔ {ابیشائی: ہیب۔ ابشائی}\n12.\\tتہٕ ووٚن زِ اگر شامی میانہِ خٲطرٕ واریاہ مضبوط آسن، تیلہِ کٔرِو ژے میانہِ مدد، مگر اگر عمون سٕندِ اولاد تہٕ ژےٚ خٲطرٕ زیادٕ مضبوط آسن، تیلہِ کٔرٕ بہٕ ژےٚ مدد۔\n13. رژھ ہمت کرُن، تہٕ أسۍ کرو پننین لوکن تہٕ پننین خدایہ سٕندٮ۪ن شہرن خٲطرٕ بہادری سان برتاو تہٕ خداوند کرُن سُہ یُس تٔمِس نظرِ منز نیکی آسہِ۔\n14.\\tیِتھٕ پٲٹھـ̡ یوآب تہٕ یِم لُکھ أمِس سٍتـ̡ ٲسِتھ وٲتِتھ وٲتِتھ شامِس برونہہ کُن جنگہٕ کِس بارس مَنٛز۔ تہٕ تِم ژٔلِتھ أمِس برونہہ کُن۔\n15.\\tتہٕ ییلہ عمون سٕندیو شُرۍ وُچھ زِ شامٕکۍ ژٔلِتھ تہٕ ژٔلِتھ ژٔلِتھ شہرس مَنٛز۔ پتہٕ آو یوآب یروشلم۔\n16.\\tییلہ شامیو وُچھ زِ تم چھہِ اسرٲیلِس برونہہ کنہِ بدتر کرنہٕ آمٕتۍ، تِمو سوٗزۍ قاصد تہٕ دریاوس اپارِ کٔرِکھ شامٕکۍ کپتان، تہٕ ہدارزر سٕندِس لشکرُک کپتان شوفاخ گۆو تمن برونہہ کُن۔ {دریاو: یعنی فرات } {شوفاچ: شوباخ تہِ ونان چھِ}\n17. تہٕ داؤد آو وننہٕ۔ تہٕ تٔمۍ کٔر سارِنٕے اسرٲیلِس جمع تہٕ اردن کِس اِشارس کُن تہٕ تِمن نِش آو تہٕ تِمن خلاف کوٚرُن جنگ۔ چنانچہ ییلہ داؤد شامس خلاف جنگ ترتیب دِژ، تمو لوٚڑ تمس سٍتۍ۔\n18.\\tمگر شامٕکۍ ژٔل اسرٲیلِس برونہہ کُن۔ تہٕ ڈیوڈن مارۍ شامی سَتھ ساس نفر یِمو رتھن منز لڑان ٲسۍ، تہٕ ژتٲجی ساس پیدل تہٕ لشکرُک کپتان شوفاخ مٲرِتھ۔\n19.\\tتہٕ ییلہ حدارزر سٕندیو خدمتگارو وُچھ زِ تِم چھِ اسرٲیلِس برونہہ کُن بدتر کرنہٕ آمٕتۍ، تِمو کٔر داؤدس سٍتـ̡ صلح تہٕ بنییہِ تٔمۍ سٕندِس خادم۔","1.\\tتہٕ سپُد یہِ زِ ؤری مۄکلاونہٕ پَتہٕ ییلہ بادشاہ جنگہٕ خٲطرٕ نیران چُھ، یوآبن کٔر فوجُک طاقت، تہٕ کٔرٕن عمون سٕندٮ۪ن بچن ہُند مُلُک برباد، تہٕ کوٚرُن ربہٕ ہُند محاصرٕ۔ مگر داؤد روٗد یروشلمس منٛز۔ تہٕ یوعبن دِژ رَبع تہٕ کوٚرُن تباہ۔ {پتہٕ...: ہیب۔ ؤری کس واپسیس پیٹھ}\n2.\\tتہٕ داؤد تُل پننِس بادشاہ سُند تاج کلہٕ پیٹھ، تہٕ وُچھُن سۄنہٕ سُند وزن تہٕ اتھ منز ٲسۍ قیمتی پتھر۔ تہٕ یہ آو ڈیوڈ سٕندِس کلس پیٹھ تھونہٕ: تہٕ سُہ اوٚن شہرٕ منزٕ واریاہ زیادٕ لوُٹ تہِ۔ {وزن: ہیب۔ وزن}\n3.\\tتہٕ تِم لُکھ یِم اتھ منز ٲسۍ، تہٕ ژٔٹِن لُکھ لُکھ تہٕ ژٔٹِتھ لٔٹِتھ تہٕ کلہٕ سٍتۍ۔ اَتھ پٲٹھـ̡ تہِ اوس داؤدس عمون کین شُرین ہٕندِس سارِنٕے شہرن سٍتـ̡ سٍتـ̡ سٍت تہٕ داؤد تہٕ سٲری لُکھ گٔیہِ یروشلم واپس۔\n4.\\tتہٕ امہِ پتہٕ سپُد یہ زِ گیزرس مَنٛز گوٚو فلسطینن سٍتـ̡ جنگ۔ ییمہِ وِزِ سِبیچایی ہُشاطین مٲرِتھ سِپایی، یُس دیو سٕندٮ۪ن شُرین ہُند اوس، تہٕ تِم گٔیہِ زیر کرنہٕ۔ {arose: یا، جٲری: Heb. کھڑا} {گیزر: گوب} {سِپائی: تہِ ونان چھِ، صف} {دیو: یا، رافا}\n5. تہٕ فلسطینن سٍتـ̡ گۆو بییہ جنگ۔ تہٕ یائر سٕندِ نیچِوِ الہانن مٲرِتھ گولیتھ دی گیٹی سُند بوے لہمی، یٔمۍ سُند نیزٕ ہُند لاٹھہٕ اوس وونٛنہٕ وٲلِس بیم ہیوٗ آسان۔ {جیر: تہِ ونان جاریوریجم}\n6. تہٕ بییہِ گۆو گاتھس منز جنگ، ییتہِ اکھ {بٔڈ} قد وول انسان اوس، یمۍ سٕنزِ اونگجہِ تہٕ کھورِ ژور تہٕ وُہ، شیہ {پرٮ۪تھ اتھس پیٹھ} تہٕ شیہ {پرٮ۪تھ کھورِ پیٹھ}: تہٕ سُہ اوس دیو سُند نیچو تہِ۔ {عظیم...: ہیب۔ پیمائش} {نیچو...: ہیب۔ دیوس زامُت، یا، رافا}\n7. مگر ییلہ تٔمۍ اسرٲیلٕچ نافرمانی کٔر، شمیعہ داؤد سٕندِس بٲے سٕندِس نیچِوِ یوناتھن مور سُہ ۔ {مخالف: یا، ملامت کرنہٕ} {شمیعہ: یتھ شمہ تہِ ونان چھِ}\n8. یِم ٲسۍ گاتھس منز دیو زامٕتۍ۔ تہٕ تِم گٔیہِ داؤد سٕندِ اتھہٕ سٍتـ̡ تہٕ تٔمۍ سٕندٮ۪ن خدمتگارن ہٕندِ اتھہٕ سٍتـ̡ پۯاونہٕ۔","1. تہٕ شیطان ووت اسرٲیلِس خٕلاف، تہٕ دٲیرُن داؤدس اسرٲیلِس گنزراونہٕ خٲطرٕ اِشارٕ۔\n2. تہٕ داؤد ووٚن یوآب تہٕ لُکن ہٕندِس حکمرانن زِ گژھ اسرٲیلِس بیرشبع پیٹھٕ دان تام گنزراونہٕ۔ تہٕ تِمن ہُند تعداد أنِتھ مے نِش، یُتھ بہٕ زانہٕ {یہ}۔\n3. تہٕ یوآبن دیُت جواب، خداوند بنوو پننین لوکن ہتہٕ گنہٕ زیادٕ، مگر میانہِ آقا بادشاہ، کیا تِم چھِنہٕ سٲری میانہِ آقا سٕندِ خادم؟ تیلہِ کیازِ چُھس میانہِ مالہِ اتھ چیزچ ضرورت؟ سُہ کیازِ بنہِ اسرٲیلِس خلاف ورزی کرنُک سبب؟\n4.\\tبہر حال اوس بادشاہ سُند کلام یوآبس پیٹھ غالب۔ اَمہِ کِنۍ دراو یوآب تہٕ ووت سارِنٕے اسرٲیلِس منز، تہٕ آو یروشلم۔\n5. تہٕ یوآبن دِژ لُکن ہُند تعداد داؤد۔ تہٕ سارِنٕے اِسرٲیلٕکۍ ٲسۍ ساس ساس تہٕ اکھ لچھ نفر یِم تلوار تُلِتھ ٲسۍ۔ تہٕ یہوداہ اوس ژور لچھ تریہ تہٕ داہ ساس نفر یِم تلوار تُلان۔\n6. مگر لیوی تہٕ بنیامین اوس نہٕ سُہ تِمن منز شمار کٔرِتھ، تکیازِ بادشاہ سُند کلام اوس یوآبس خٲطرٕ ناپسندیدہ۔\n7. تہٕ خدا اوس اتھ چیزس پیٹھ ناراض۔ تَمہِ کِنۍ دِژ تٔمۍ اِسرٲیلَس مار۔ {تہٕ ...: ہیب۔ تہٕ یہ اوس خداوند سٕنزِ نظرِ منز اتھ چیزس متعلق بُر}\n8. تہٕ داؤد ووٚن خدایس زِ میہ چُھ واریاہ گۅناہ کورمُت، کیازِ مے چُھ یہِ کٲم کٔرمٕژ، مگر وۅنۍ چُھس بہٕ ژے درخواست کران زِ پنہٕ نِس خادمُک گناہ کٔرِو دوٗر۔ تکیازِ میہ چھیہ سیٹھا بیوقوفی کٔرمژ۔\n9.\\tتہٕ خداوند کٔر داؤد سٕندِس غیب وٲلِس گادس سٍتـ̡ وونُن،\n10.\\tگژھ تہٕ داؤدس ونُن، یِتھٕ پٲٹھۍ چُھہ خداوند فرماوان زِ بہٕ چُھس ژے تریہ چیز پیش کران: تِمو منزٕ کٔرِو ژے اکھ ژٲرِتھ، یُتھ بہٕ کرٕ ژے سٍتـ̡ کٔرِتھ۔ {پیشکش: ہیب۔ کھینچ آوٹ}\n11.\\tیێلہِ آو گاد داؤدس نِش، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ، خداوند چُھہ ونان، ژٲر ژٲر {ژٲرِو...: ہیب۔ نِش نِیو}\n12. یا تہٕ ترٚین ؤرین ہُند قحط۔ یا تریہ ریتن گژھہِ پننین دشمنن برونہہ کنہِ تباہ گژھُن، ییلہ زن تہندین دشمنن ہنز تلوار ژیہ ژٔٹِتھ ۔ نتہٕ تریہ دۅہہٕ خداوند سٕنز تلوار، یێلہِ تہٕ وبا تہٕ خداوند سُند فرشتہٕ یُس اسرٲیلٕکِس سارِنٕے ساحلس سٍتـ̡ تباہ کرُن۔ وۅنۍ کٔرِو پانس مشورٕ زِ بہٕ کُس لفظ دُبارٕ یُس مےٚ سوزمُت اوس۔\n13. تہٕ داؤدن ووٚن گاڈس زِ بہٕ چُھس سٮ۪ٹھاہ مُشکِلس منز: بہٕ چُھس وۅنۍ خداوند سٕندِس اتھس مَنٛز۔ تکیازِ واریاہ عظیم چھہِ تسٕنزِ رحمت: مگر بہٕ گژھ نہ انسان سٕندِس اتھس منز۔ {واریاہ عظیم: یا، واریاہ زیادٕ}\n14. یێمہِ سٍتـ̡ ساس سٍتـ̡\n15. تہٕ خداین سوز یروشلمس منز اکھ فرشتہ یُس تباہ کرنہٕ خٲطرٕ، تہٕ یێلہِ سُہ تباہ اوس کران، خداوند وُچھ تہٕ تٔمِس کٔرٕن بدی نِش توبہٕ، تہٕ وونُن تٔمِس فرشتس یُس تباہ کٔرِ، یہِ چُھہ کٲفی، وُنۍ روزُن پنُن اتھہٕ۔ تہٕ خداوند سُند فرشتہ اوس اورنان یبوسی سٕندِس تھریشنگ فلورس نِش کھڑا۔ {اورنان: تہِ ونان چھِ، ارونہ}\n16. تہٕ داؤد کٔر أچھ تُل، تہٕ وُچھ خداوند سُند فرشتہ زمینس تہٕ آسمانس درمیان کھڑا تہٕ یُس یروشلمس پیٹھ تلوار پھٔہلٲوِتھ اوس۔ اَمہِ پتہٕ گٔیہِ داؤد تہٕ اسرٲیلٕکۍ زِٹھۍ، یِم بُتھِس پیٹھ لٔگِتھ ٲسۍ۔\n17. تہٕ داؤدن ووٚن خدایس {یہ} کیا میہ چُھنہٕ لوکن گنزراونُک حکم دِتمُت؟ میہ تہِ چھہ گۅنہہ کورمُت تہ بد کار کورمُت۔ مگر {یوت} یمن دانٛدن خٲطرٕ، تمو کیا کوٚر ؟ چُھس پنُن اَتھٕ دُعا کَرُن، اے خداوند میانہِ خدایہ، میانہِ تہٕ میٲنِس مٲلہِ سٕندِس گرس پیٹھ۔ مگر پننین لوکن پیٹھ نہٕ، زِ تِم گژھن متٲثر گژھن۔\n18.\\tتێلہِ دِژ خداوند سٕندِ فرشتن گاڈس حکم زِ سُہ گژھہِ داؤدس ونُن، تہٕ یێلہِ دٲیود سٍتـ̡ یێلہِ ہٕندِس کُنہِ\n19.\\tتہٕ داؤد ووت گاد سٕندِس کلامس پیٹھ، یُس تٔمۍ خداوند سٕندِ ناوٕ سٍتـ̡ کتھ کٔر۔\n20.\\tتہٕ اورنن پھیُر پتھ تہ وُچھن فرشتہ۔ تہٕ تٔمۍ سٕنٛدۍ ژور نیچوۍ ٲسۍ أمس سۭتۍ ژوٗر۔ وۅنۍ اوس اورنن کٕنُک کُنُک کُنہِ {تہٕ اورنان...: یا، ییلہ اورنن واپس پھیُر تہ فرشتہ وُچھ، تیلہ گٔیہ سہ تہٕ تس سٍتۍ ژور نیچوۍ ژوٗرِ}\n21.\\tییلہ داؤد اورنان آو تہ وُچھن داؤد تہ وُچھن داؤد، تہٕ دوٚپ داؤدس کُن بُتھ کٔرِتھ نمُن۔\n22. اَمہِ پَتہٕ ووٚن داؤد اورنانس زِ مے دِژ یَتھ مَنٛز رٔنگہِ ہٕنز جاے دِیُن، یُتھ بہٕ اَتھ مَنٛز خداوند سٕندِ خٲطرٕ اکھ قربان گاہ بنٲوِتھ، تہٕ ژٕ دِیُکھ مے پوٗرٕ قٲمتس مۅکھہٕ دِنہٕ، یُتھ زِ وبا روزِ لُکن نِش رُکاونہٕ۔ {گرانٹ: ہیب۔ دِیُو}\n23.\\tتہٕ اورنن ووٚن ڈیوڈس زِ یہ نِش نِن تہٕ میانہِ آقا بادشاہ دِیُن تٔمۍ سٕنزِ نظرِ ہٕندِ خٲطرٕ یُس اصل آسہِ، تہٕ بہٕ دِوان ژے دِوان زالنہٕ خٲطرٕ بیل تہٕ لٔکرِ ہٕندِ خٲطرٕ کٕنُک تہٕ ماز نذرانہٕ خٲطرٕ کٕنُک۔ بہٕ چھُس یہ سورُے دِوان۔\n24.\\tتہٕ بادشاہ ڈیوڈن ووٚن اورنانس نے۔ مگر بہٕ ہیوٚک یہ پورٕ قٲمتس پیٹھ ہینہٕ: کیازِ بہٕ نِہ نہٕ سُہ {یہ} یُس خداوند خٲطرٕ {چُھ} چُھ، تہٕ نہ کرٕ بغٲر خرچہٕ دزنہٕ نذرانہ پیش کرنہٕ۔\n25.\\tتہ دِژ داؤد اورنانس وزنہ حسابہٕ شیہ ہتھ شیکل سونہٕ۔\n26. تہٕ داؤدَن بَنوو اَتہِ خداوند سٕندِ خٲطرٕ اکھ قربان گاہ، تہٕ دِژٕن دَزنہٕ نذرانہ تہٕ امن ہٕندِ نذرانہ پیش تہٕ کٔرٕن خداوند سٕندِ خٲطرٕ مُطالبہٕ۔ تہٕ تٔمۍ دِژ أمِس آسمانہٕ پیٹھٕ نار سٍتـ̡ دزنہٕ آمٕژ قربان گاہس پیٹھ جواب۔\n27. تہٕ خداوند دِیُت فرشتہٕ سُند حُکُم۔ تہٕ تٔمۍ ترٲو پنٕنۍ تلوار بییہ اتھ نیدرس منٛز۔\n28. تمہِ وِزِ ییلہ داؤد وُچھ زِ خداوند چُھ أمِس اورنان یبوسی سٕندِس تھریشنگ فلورس مَنٛز جواب دِژمُت، تیلہِ کٔر تٔمۍ تتہِ قربانی۔\n29.\\tخداوند سٕندِ خیمہ خٲطرٕ، یُس موسیٰ ہن بیابانس مَنٛز بنوومُت اوس، تہٕ دزنہٕ نذرانہٕ ہُند قربان گاہ، اَتھ موسمس مَنٛز ٲس گِبیونَس مَنٛز تھدِ جایہ۔\n30.\\tمگر داؤد ہیوٚک نہٕ أمِس برونہہ کُن گژھِتھ خدایہِ سٕنزِ تلوار سٍتـ̡ کھوژان۔","1. پَتہٕ داؤد ووٚن، یہِ چُھ خداوند خدایہِ سُند گر، تہٕ یہِ چُھہ اسرٲیلِس خٲطرٕ دزنہٕ آمٕژ قربان گاہ۔\n2. تہٕ داؤدُن دِیُت حُکُم زِ یِم اِسرٲیلِس مَنٛز ٲسِن تِم غٲر ملکی جمع کٔرِتھ۔ تہٕ تٔمۍ مقرر کٔر خدایہ سُند گرٕ بناونہٕ خٲطرٕ کٔنہِ کٔنہِ۔\n3.\\tتہٕ داؤدن کٔر دروازن ہندِ دروازن تہٕ جوڑن خٲطرٕ کیلن خٲطرٕ کثرت سان ششتٕر تیار۔ تہٕ وزنہٕ ورٲے پیتل کثرت سان؛\n4.\\tدیودار کُلۍ تہِ کثرت سان: زیدونیو تہٕ صور کِس تِمو أنۍ داؤدس نِش واریاہ دیودار لٔکر۔\n5. تہٕ داؤد ووٚن، سُلیمان میون نیچو چُھہ جوان تہٕ نرم، تہٕ یُس گرٕ خداوند سٕندِ خٲطرٕ تعمیر کرنہٕ یُن چُھہ سارنٕے ملکن منز شہرت تہٕ جلال ہُند سٍتـ̡ آسُن: بہٕ کرٕ وۅنۍ امہِ خٲطرٕ تیٲری کرنہٕ۔ چنانچہ داؤد پننہِ مرنہٕ برونہہ واریاہ تیار۔\n6. پَتہٕ تٔمۍ بُلوو پنُن نیچو سُلیمان، تہٕ دِتُن أمِس اِسرٲیلِکِس خدایہِ سٕندِ خٲطرٕ اکھ مکانہٕ بناونُک حُکُم۔\n7. تہٕ داؤدن ووٚن سُلیمانس زِ میانہِ نیچو، یێلہِ میانہِ ذہنس مَنٛز اوس خداوند میانہِ خدایہ سٕندِ ناوٕ سٍتـ̡ اکھ مکانہٕ بناوُن:\n8.\\tمگر خداوند سُند کلام آو میہ نِش، یێلہِ ووت ژے واریاہ خوُن تہٕ بٔڈ جنگ کورمُت، تہٕ ژے کٔرٕکھ نہٕ میانہِ ناوٕ سٍتـ̡ مکانہٕ بنوومُت، کیازِ ژے چُھکھ میانہِ نظرِ مَنٛز زمینس پیٹھ واریاہ خوُن تروومُت۔\n9.\\tوُچھِو ژے اکھ نیٚچُو زامُت، یُس آرام دِنہٕ وول آسہِ۔ تہٕ بہٕ دِیہ تس اندۍ پکھۍ سارِنٕے دُشمن نِش آرام دِنہٕ، تکیازِ تٔمۍ سُند ناو آسہِ سُلیمان، تہٕ بہٕ دِیہ اسرٲیلِس تسٕندِس دۅہس منز امن تہٕ سکون۔ {سلیمان: یعنی پرامن}\n10.\\tسُہ کرِ میانہِ ناوٕ خٲطرٕ اکھ مکانہٕ۔ تہٕ سُہ آسہِ میون نیچو، تہٕ بہٕ آسہٕ تٔمۍ سُند مول۔ تہٕ بہٕ کٔرٕ تٔمۍ سٕنزِ سلطنتُک تخت ہمیشہٕ خٲطرٕ اسرٲیلس پیٹھ۔\n11. وۅنۍ چُھہ میانہِ نیچو، خداوند آسُن توے سٍتـ̡ ۔ تہٕ کٔرِو خۄشحال تہٕ خداوند پنُن خدا سُند گرٕ بناوُن، یِتھ کٔنۍ تٔمۍ تۅہہِ متعلق ووٚنمُت۔\n12. صرف خداوند چُھہ تۅہہِ حکمت تہٕ فہم دِوان، تہٕ اسرٲیلِس مُتلق دِیُن تہٕ تۅہہِ ہێکہِ خداوند سٕندِس خدایہِ سٕندِس شریعت سٍتـ̡ رٲچھ کٔرِتھ۔\n13.\\tتیلہِ گژھہِ تیلہِ گژھہِ تۅہہِ ترقی سپدِ، یێلہِ تِمن قونونن تہٕ فیصلن ہُند خیال تھاوُن یُس خداوند موسیٰ ہس اسرٲیلِس متعلق دِژمُت اوس، مضبوط تہٕ ہمت تھاوُن۔ خوفزدہ گژھ نہٕ تہٕ نہ گژھ خوف۔\n14.\\tوُچھِو میہ پننہِ مصیبت سٍتـ̡ خداوند سٕندِ گرٕ خٲطرٕ اکھ لچھ ساس سۄنہٕ تہٕ ساس ساس رۄپہٕ تیار کٔرِتھ۔ تہٕ پیتل تہٕ ششتٕرُک وزن ورٲے ؛ تکیازِ یہ چھُ وافر مقدار منٛز: لٔکر تہٕ کٔنۍ تہِ چھِ مے تیار کٔرمٕژ۔ تہٕ تُہۍ ہیکِو اتھ منٛز شٲمِل کٔرِتھ۔ {پریشانی: یا، غربت}\n15.\\tاَمہِ علاوٕ چھِ تۅہہِ سٍتـ̡ کٔنـ̡ کٔنـ̡ تہٕ لٔکرِ ہٕندِس کامہِ سٍتـ̡ سارِوٕے قٕسمٕکۍ چالاک نفر موجود۔ {کارکن...: یعنی معمار تہٕ چھان}\n16. سۄن، رۄپھ، پیتل تہٕ ششتٕرُک {چُھنہ} کانہہ تعداد۔ وۅتھٕ وُن تہٕ کرُن، تہٕ خداوند روزِ توے سٍتـ̡ ۔\n17.\\tداؤد دِیُت اِسرٲیلِکۍ سارنٕے شہزادن تہِ حُکُم زِ سُہ کٔرِن سُلیمان سٕندِس نیچوِس سٍتـ̡ مدد۔\n18.\\tکیا چُھہ نہٕ خداوند تُہند خدا؟ تہٕ کیا تٔمۍ دِژ ژےٚ پریتھ طرفہٕ آرام دِژمٕژ؟ تکیازِ تٔمۍ دِژ زمینہٕ کین بسکینن میٲنس اتھس منٛز۔ تہٕ زمین چُھ خداوند سٕندِس برونہہ کُن تہٕ تٔمۍ سٕندِس لوکن برونہہ کُن زیر کرنہٕ آمُت۔\n19. وۅنۍ کرو پنُن دِل تہٕ روح خداوند پنُن خدایہ ژھارنہٕ خٲطرٕ۔ تێمہِ وِزِ وۆتھ، تہٕ خداوند سٕندِ عہدُک صندوق تہٕ خدایہ سٕندِ مقدس بانہٕ یُس خداوند سٕندِ ناوٕ سٍتـ̡ بناونہٕ یُن چُھ۔","1. یێلہِ داؤد بُزرگ تہٕ دۅہہٕ بٔرِتھ بنیوو، تٔمۍ بنوو سُلیمانس پَنُن نیچو اسرٲیلُک بادشاہ۔\n2. تہٕ تٔمۍ کٔر اسرٲیلٕکۍ سٲری شہزادٕ، کاہنن تہٕ لاوِین سٍتـ̡ جمع ۔\n3. وۅنۍ اوس لاوِین ہُند تعداد ترہ وُہُر وٲنسہِ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہُند شمار کرنہٕ آمُت، تہٕ تِہُند تعداد اوس انسان سٕندِ پتہٕ ٲٹھ ساس۔\n4. یِمو منزٕ ژۅوُہ ساس ٲسِتھ خداوند سٕندِ گرٕچ کٲم برونہہ پکناونہٕ خٲطرٕ۔ تہٕ شیہ ساس {ٲس} افسر تہٕ جج: {سیٹ...: یا، نگرانی}\n5.\\tامہ علاوہ ژور ساس قلی۔ تہٕ ژور ساس کٔر خداوند سٕندِ تعریف، یُس میہ بنوومُت چُھ، {داؤد} سٍتـ̡ تعریف۔\n6. تہٕ داؤد کٔر تِم لیوی سٕندٮ۪ن نیچوین مَنٛز تقسیم۔ {کورس: ہیب۔ تقسیم}\n7.\\tگرشونیَن مَنٛز، لَدان تہٕ شِمیعی۔ {لادان: یا، لبنی}\n8.\\tلادان سٕندِ نیٚچوۍ۔ سردار اوس جہیل، تہٕ زیتھم، تہٕ جوئل، ترےٚ۔\n9.\\tشیمی سٕندِ نیٚچوۍ۔ شیلومتھ تہ ہازیل تہ ہارن ترۍ۔ یِم ٲسۍ لادان کین فادرن ہٕندِ سردار۔\n10.\\tتہٕ شمعیہ سٕندِ نیٚچوۍ، جہات، زینا تہٕ عیسیٰ تہٕ بریہ۔ یم ژور ٲسۍ شیمی سٕندۍ نیچو۔ {زینا: یا، زیزہ}\n11.\\tتہٕ یَحَت اوس سردار، تہٕ زیزہ اوس دۆیِم، مگر حضرت عیسیٰ تہٕ بریاہَس ٲسۍ نہٕ واریاہ نیٚچِو۔ لہذا ٲسۍ تم اکۍ سے حسابس منز، {تہندِ} مٲلۍ سٕندِ گرٕ مطٲبق۔ {had...: Heb. نیچو کٔر نہٕ ضرب دِنہٕ}\n12. کوہاتھ سٕندۍ نیٚچوۍ۔ امرام، اظہر، ہیبرون تہٕ عزیل، ژور۔\n13.\\tامرام سٕندِ نیٚچوۍ۔ ہارون تہٕ موسیٰ: تہٕ ہارون آو الگ کرنہٕ، یُتھ سُہ تہٕ تٔمۍ سٕندِس نیچوِس ہمیشہٕ خٲطرٕ پاک کرُن، خداوند سٕندِ برونہہ کُن بخور زالُن، أمِس خدمت کرنہٕ خٲطرٕ، تہٕ تٔمۍ سٕندِس ناوس سٍتـ̡ ہمیشہٕ خٲطرٕ برکت دِنہٕ۔\n14.\\tوُنہِ موسیٰ سٕندِس خدایہِ سٕندِس انسانس سٍتـ̡ تہٕ تٔمۍ سٕندِس نیچوِس ہُند ناو اوس لاوی سٕندِس قبیلس مَنٛز تھاونہٕ آمُت۔\n15.\\tموسیٰ سٕندِ نیچوۍ، گرشوم تہٕ ایلیزر۔\n16.\\tگرشوم سٕندِس نیچویو منز، شیبویل اوس سردار۔ {شیبویل: تہٕ چُھ، شبیل تہٕ وننہٕ یوان}\n17.\\tتہٕ الیزر سٕندِ نیچوۍ، رحبیہ سردار۔ تہٕ الیعزرس اوس نہٕ بیٚیہ کانٛہہ نیچو۔ مگر رحبیہ سٕندِ نیچوۍ ٲسۍ واریاہ زیادٕ۔ {سردار: یا، گۄڈنیُک} {واریاہ زیادٕ: ہیب۔ انتہایی ضرب دِنہٕ آمُت}\n18.\\tازہر سٕندِس نیچوِس منز۔ شیلومتھ دی چیف۔ {شیلومتھ: یتھ شیلوموتھ تہِ ونان چھِ}\n19. ہیبرون کین نیچوین ہٕنز۔ یریاہ گۄڈنیُک، امریاہ دویم، جہازیل تریم تہٕ جیکامیم ژورم۔\n20. عزیل سٕندِس نیچوِس منز؛ میخا گوڈنیک تہٕ جیسیاہ دوٚیم۔\n21.\\tمیراری سٕندِ نیٚچوۍ۔ مہلی، تہٕ مشی۔ مہلی سٕندۍ نیچو؛ الیزار تہٕ کِش۔\n22.\\tتہٕ الیعازر موٗد تہٕ تٔمِس زٲنِس نہٕ نیچو، مگر کورِ: تہٕ تِہٕندِس بٲے کِش سٕندِس نیچوِس نِش رٔٹۍ۔ {برادران: یا، رشتہ دار}\n23.\\tموشی سٕندِ نیچوۍ۔ مہلی، تہٕ ایڈر، تہٕ یرموتھ، ترۍ۔\n24. یِم ٲسۍ پننین مٲلن ہٕندِس گرس پتہٕ لاوی سٕندِ نیچوۍ۔ {حتیٰ کہ} فادرن ہُند سردار، یتھ کٔنۍ زِ تِم ٲسۍ پننیو انتخابن ہٕندِ لحاظہٕ ناون ہٕندِ تعدادٕ سٍتـ̡ گنزراونہٕ آمٕتۍ، یِمو وُہن وُہٕرِ وٲنسہِ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕنزِ خدمتہٕ خٲطرٕ کٲم کٔر۔\n25.\\tداؤد وۆن زِ اسرٲیلُک خدایہ چُھ پننین لوکن آرام دِژمُت، یُتھ زن تِم یروشلمس مَنٛز ہمیشہٕ روزِن: {یہ...: یا، تہٕ سُہ روزِ یروشلمس مَنٛز روزُن، وغیرہ}\n26. تہٕ لاوِین سٍتـ̡ تہِ۔ تِم گژھن نہٕ خیمہ نِن، تہٕ نہ گژھن امہِ چہِ خدمتہٕ خٲطرٕ امِچ کانہہ بانہٕ۔\n27. تکیازِ داؤد سٕندِس ٲخری کلامس مطٲبق اوس لاوی {وُہُہ وُہُر وٲنسہِ تہٕ امہِ کھوتہٕ زیادٕہ وٲنسہِ﴾ شمار کرنہٕ آمُت: {نمبر: حب۔ نمبر}\n28.\\tتِکیازِ تِہُند عہدٕ اوس ہارون سٕندِس نیچوِس ہٕنزِ خدمتہٕ خٲطرٕ، دربارن مَنٛز، تہٕ خانن مَنٛز، تہٕ سارنٕے مقدس چیزن پاک کرنہٕ خٲطرٕ، تہٕ خدایہ سٕندِ گرٕچ خدمتہٕ خٲطرٕ انتظار کرُن۔ {تِہُند...: ہیب۔ تہند مقام اوس ہارون سٕندِس نیچوین ہٕندِس اتھس منز}\n29.\\tشیو بریڈ خٲطرٕ، تہٕ مازٕچ نذرانہ خٲطرٕ، تہٕ خمیر روٚس کیک خٲطرٕ، تہٕ یُس پانس منز سینہٕ یوان چُھ، تہٕ تُلنہٕ خٲطرٕ، تہٕ پرٮ۪تھ قٕسمٕچ پیمائش تہٕ سائزٕ خٲطرٕ۔ {پین: یا، فلیٹ پلیٹ}\n30. تہٕ پرٮ۪تھ صُبحٲے کھڑا روزُن خداوند سُند شُکر ادا کرنہٕ تہٕ تعریف۔\n31.\\tتہٕ سبت دۅہہ، نوِ زونہِ مَنٛز، تہٕ مقرر عیدن پیٹھ، خداوند سٕندِ خٲطرٕ سارِنٕے دزنہٕ آمٕژ قربانی پیش کرنہٕ خٲطرٕ، یُس حکم دِنہٕ آمُت چھُ، خداوند سٕندِ برونہہ کُن لگاتار روزُن:\n32.\\tتہٕ یُس تِم گژھن جماعت ہٕندِس خیمہ ہُند ذمہ دار، تہٕ مُقدس {جاے} ہُند ذمہ دار، تہٕ ہارون سٕندٮ۪ن نیچوین ہُند ذمہ دار، خداوند سٕندِس گرٕ سٕنزِ خدمتہٕ مَنٛز۔","1. وۅنۍ چھہِ ہارون سٕندِس نیچوین ہٕنز تقسیم۔ ہارون سٕندۍ نیٚچوۍ؛ نداب تہٕ ابیہو، الیعازر تہٕ اِتھمار۔\n2.\\tمگر نداب تہٕ ابیہو گٔیہِ پننِس مٲلِس برونہہ کُن، تہٕ یِمن اوس نہٕ کانہہ شُر: اَمہِ مۄکھٕ کٔر الیعازر تہٕ اِتھمارن پادٕرۍ سُند عہدٕ۔\n3. تہٕ داؤد کٔر تِم دۅشوے الیعزر سٕندِ نیچوین ہٕندِس زادوک تہٕ اِتھامار کین نیچوین ہٕندِس احیمیلک تہٕ تِمن ہٕنزِ خدمتہٕ مُطٲبق بٲگراونہٕ۔\n4.\\tتہٕ الیعزر سٕندٮ۪ن نیچوین ہٕندِس مقابلس منز ٲسۍ زیادٕ اہم مرد لبنہٕ آمٕتۍ۔ تہٕ {یتھہ پاٹھۍ} آیہ تم تقسیم کرنہ۔ الیعازر سٕندِس نیچوین منز ٲس {تہندِ} مٲلن ہٕندِس گرٕکۍ شُراہ اہم نفر، تہٕ اِتھمار سٕندِس نیچوین منز ٲٹھ تہٕ تہندِس مٲلن ہٕندِ گرٕ مطٲبق ٲسۍ۔\n5. یِتھٕ پٲٹھۍ آیہ تِم قرعہ اندازی سٍتـ̡ تقسیم کرنہٕ، اَکہِ قسمہٕ سٍتـ̡ بییِس سٍتـ̡ تکیازِ مقدس مقامکۍ گورنرن تہٕ خدایہ سٕندِ گرٕکۍ گورنرن ٲس الیعازر سٕندِ نیچوین تہٕ اِتھمار سٕندٮ۪ن نیچوین ہٕندِ۔\n6.\\tتہٕ نیتھانیل سُند نیچو شمعیاہ یُس لاوِین ہٕندِس نیچوُس {اَکہِ}، یُس بادشاہس تہٕ شہزادن تہٕ زادوک پادٕر، تہٕ ابیاتھر سُند نیچو اہیمیلک تہٕ کاہنن تہٕ لاوِین ہٕندِس مٲلن ہٕندِس سردارس برونہہ کُن لیوکھمُت۔ {پرنسپل...: ہیب۔ ہاوس آف دی فادر}\n7. وۅنۍ آو گۄڈنیُک لاٹ یہویاریبس کُن، دۆیِم یَدعیاہ کُن،\n8.\\tتریم حریمس تہ ژورم سیوریمس کُن،\n9. پوٗنٛژِم ملچیجاہَس کُن، شیٚیِم مِجامینَس\n10. سٔتِم حکوز، ٲٹھم ابیاہس خٲطرٕ،\n11. نٔوِم یشوع کُن، دٔہِم شیکانیاہَس کُن،\n12. کٔہِم الیاشیب، بٔہِم جاکیم،\n13.\\tتروٲہِم ہُپہ تہٕ ژۄدٲہِم یشیبیعَس کُن،\n14.\\tپنٛدٲہِم بلگاہ، شُراہِم عمیر،\n15.\\tسداہِم حزیر، ارداہِم افسس،\n16.\\tکُنوُہِم پتھاہ، وُہِم یحزقل،\n17.\\tاکھ تہٕ وُہِم جاچِن، زٕ تہٕ وُہِم گامل،\n18.\\tتریم تہٕ وُہمہِ دلیاہس منز، ژور تہٕ وُہمہِ ماضیہ کُن۔\n19.\\tیِم ٲسۍ تِمن ہٕنزِ خدمتہٕ مَنٛز خداوند سٕندِس گرس مَنٛز یِنُک حُکُم یِنہٕ خٲطرٕ، یِتھٕ کٔنۍ زن اسرٲیلِکِس خداہِ سٕندِس مٲلِس سٍتـ̡ یِمن ہُند حُکُم اوس دِژمُت۔\n20.\\tتہٕ لیوی سٕندِ باقٕے نیچو {یِم}: امرام سٕندِس نیچوِس منز۔ شبیل: شبیل سٕندِس نیچوِس منز۔ جہدیہ۔ {شبیل: یتھ تہِ ونان چھہِ}\n21.\\tرحبیہ متعلق: رحبیہ کین فرزندن مَنٛز گۅڈنِچ {ٲس} عیشیہ۔\n22.\\tازاریَن ہُند؛ شیلوموتھ: شیلوموتھ سٕنٛدیٚن نیٚچویٚن ہٕنٛز؛ جہاتھ۔ {شیلوموتھ: یتھ شیلومتھ تہِ ونان چھِ}\n23. تہٕ نیچوۍ {ہیبرون}؛ یریاہ {گۄڈٕنِک}، امریاہ دۆیم، جہازیل تریم تہٕ یکامیم ژورم۔\n24. عزیل سٕندِ نیچوۍ۔ میچاہ: میخا سٕندِس نیچوِس منز؛ شمیر۔\n25.\\tمیخا سُند بوے عشیہ سٕندِس نیچوِس سٍتـ̡ ۔ زکریا ۔\n26.\\tمراری سٕندِ نیچو مہلی تہٕ موشی: جازیہ سٕندِ نیٚچِوۍ۔ بینو۔\n27.\\tجزیہ سٕندِ مراری سٕندِس نیچو۔ بینو، تہٕ شوہم، تہٕ زکر، تہٕ ایبری۔\n28.\\tمہلی سٍتـ̡ آو الیزار، ییمِس نہٕ کانہہ نیچو اوس۔\n29.\\tکِش سُند نیچو اوس رحمیل۔\n30.\\tموشی سٕندِ نیچوۍ تہِ۔ مہلی، تہٕ ایڈر، تہٕ جیریموتھ۔ یِم ٲسۍ پننین مٲلن ہٕندِس گرس پتہٕ لاوی سٕندِ نیچوۍ۔\n31.\\tیِتھے پٲٹھـ̡ کٔر یِمو پننین باین سٍتـ̡ ہارون سٕندِس نیچوِس سٍتـ̡ داؤد بادشاہ تہٕ زادوک تہٕ اہیملک، تہٕ پادٕرین تہٕ لاوِین ہٕندِس مٲلن ہٕندِس مٲلن ہٕندِس سردارس سٍتـ̡ تہٕ حتیٰ کہ اہم بابن تہٕ پننین لۄکٹٮ۪ن باین ہٕندِس خٕلاف قرعہٕ۔","1. امہِ علاوٕ گٔیہِ داؤد تہٕ میزبانہٕ سٕندِ کپتان آساف سٕندِس نیچوِس تہٕ ہیمانس تہٕ یدوتون سٕندِس نیچوین ہٕنزِ خدمتہٕ خٲطرٕ الگ گٔیہِ، یِم ہارپ، زبور تہٕ تھپھ سٍتـ̡ پیشن گویی کرٕنۍ: تہٕ تِمن ہٕنزِ خدمتہٕ مُطٲبق اوس کامگارن ہُند تعداد :\n2. آصف سٕندِس نیچوِس منز؛ زکر، تہٕ یوسف، تہٕ نیتھنیاہ، تہٕ اسارِلہ، آصف سٕندِس اتھہٕ سٍتـ̡ یِمو بادشاہ سٕندِس حُکمس مُطٲبق پیشن گویی کٔر۔ {اَسَریلہ: نَتہٕ یَتھ یِشارلہ وَننہٕ یِوان} {مطٲبق...: ہیب۔ بادشاہ سٕندِ اتھہٕ سٕتۍ}\n3. جدوتون سٕندِ: یدوتون سٕندِ نیٚچوۍ۔ گیدلیہ، تہٕ زیری، تہٕ یشایعہ، حشبہ، تہٕ متیتیاہ، شیٚیہ، پننِس مٲلِس یہدوتون سٕندِس اتھس تل، یٔمۍ ہٕندِس بٔرِس سٍتـ̡ پیشن گویی کٔر، یُس خداوند سُند شُکر ادا کرنہٕ خٲطرٕ تہٕ تعریف کرنہٕ خٲطرٕ پیشن گویی کٔر۔ {زیری: یا، ازری}\n4. ہیمن سٕندِ: ہیمن سٕندِ نیچو۔ بُکیہ، متانیہ، عزیل، شیبول تہٕ یریموتھ، حنانیہ، حنانی، الیاتھا، گِدالتی، تہٕ رومتیزر، جوشبیکاشاہ، مالوتھی، ہوتیر، {تہٕ} مہازیوتھ: {عزیل: تہٕ وَننہٕ یِوان، آزریل} {شبویل: تہِ وَننہٕ یِوان، شُبعل}\n5.\\tیِم سٲری ٲسۍ خدایہ سٕندِس کلامس مَنٛز بادشاہ سٕندِ سٕندِس نیچِھس سٍتـ̡ تُلنہٕ خٲطرٕ۔ تہٕ خداین دِژ ہیمانس ژۄداہ نیچوۍ تہٕ ترےٚ کورِ۔ {الفاظ: یا، معاملہ}\n6.\\tیِم سٲری ٲسۍ پننِس مٲلہِ سٕندِس اتھس تل خدایہ سٕندِس گرس مَنٛز گٮ۪ونہٕ خٲطرٕ، خدایہ سٕندِ گرٕ سٕنزِ خدمتہٕ خٲطرٕ، بادشاہ سٕندِ حُکمہٕ مُطٲبق آساف، یہدوتون تہٕ ہیمانس ہٕندِس حُکمس مُطٲبق۔ {مطٲبق...: ہیب۔ بادشاہ سٕندِ اتھہٕ سٕتۍ}\n7.\\tیێلہِ تِمن ہُند تعداد اوس تِمن بٲے سٍتـ̡ یِمن ہٕندِس بٲیس مَنٛز ہدایت دِنہٕ آمٕژ ٲس، {حتیٰ کہ} سارِنٕے چالاک ٲس، زٕ ہتھ ژور تہٕ ٲٹھ۔\n8.\\tتہِ چھہِ لۅکٹٮن تہ لۅکٹٮن تہ بٔڈۍ تہِ لۅکٹۍ تہ استادس عالمس سیتۍ واٹھ دوان۔\n9. وۅنۍ آو گۄڈنیُک لاٹ آصاف سٕندِ خٲطرٕ یوسفس نِش، دۆیِم گدلیہ سٍتـ̡ یُس پننین باین تہٕ نیچوین سٍتـ̡ بَہہ وُہُن:\n10.\\tتریم زکرس سٍتۍ، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ {أس} باہ۔\n11.\\tژوٗرِم عزری، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n12.\\tپوٗنژِم نیتھانیاہَس سٍتـ̡ {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ وُہُن:\n13.\\tشیٚیِم بُکیاہ سٍتـ̡ {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے، {أسـ̡ باہ:\n14.\\tسٔتِم یشرلہ، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n15.\\tٲٹھِم یشایعہ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n16.\\tمتانیاہ سٍتـ̡ نٔوِم، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n17.\\tدٔہِم شمیعی، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n18.\\tکٔہِم عزریل، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بٔہِتھ:\n19.\\tہشبیاہ سٍتـ̡ بٔہِم، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بٔہِم:\n20.\\tشبیل سٍتـ̡ تروٲہِم، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n21.\\tمتیتھا سٍتـ̡ ژۄدٲہِم، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ {أسـ̡ بَہہ:\n22.\\tپنٛدٲہِم یرموتھس سٍتـ̡ {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ {أسـ̡ باہ:\n23.\\tشُراہ حنانیاہ سٍتـ̡ {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n24.\\tسداہِم جوشبیکاشہ، {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہِم:\n25.\\tاردٲہِم حنانی، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n26.\\tکُنوُہِم ملوتھی، {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n27.\\tوُہِم ایلیاتاہ، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ {أسـ̡ باہ:\n28.\\tہوتیرس اکھ تہٕ وُہِم، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بٔہِتھ:\n29.\\tزٕ تہٕ وُہِم گِڈلتی، {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بٔہِتھ:\n30.\\tتریہ تہٕ وُہِم مہزیوت، {سُہ}، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بَہہ:\n31.\\tژور تہٕ وُہِم رومامٹیزرس سٍتۍ، تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ بٔہِم۔","1.\\tقلین ہٕندِس تقسیمس متعلق: کورِس سُند نیچو مشلیمیاہ اوس آصف سٕندِس نیچوُس ۔ {میشیلیمیاہ: یتھ شیلمیاہ تہِ ونان چھِ} {آساف: یتھ تہِ ونان چھہِ}\n2. تہٕ مشلیمیاہ سٕندِ نیچوۍ، زکریاہ گۅڈنِیُک، یدیال دۆیم، زبدیاہ تریم تہٕ یتھنیئل ژوٗرِم،\n3. ایلام پٲنژم، یہوہانن شیٚیِم، ایلیوئنائی سٔتِم۔\n4.\\tبییہِ اوس اوبیڈوم سٕندِ نیچوۍ، شمعیہ گۅڈنیُک، یہوزآباد دۆیم، یوحہ تریم تہٕ سکار ژورمہِ تہٕ نیتھانیل پٲنژم۔\n5.\\tاَمیَل شیٚیِم، اِساکر سٔتِم، پیلتھائی ٲٹھم: تِکیازِ خداین کٔر أمِس برکت۔ {سُہ: یعنی اوبیدیدوم}\n6.\\tشمعیاہ سٕندِس نیچوِس سٍتـ̡ زامٕتـ̡ نیچوۍ، یِمو تِمن ہٕندِس مٲلہِ سٕندِس گرس سٍتـ̡ راج کٔرِتھ، تکیازِ تِم ٲسۍ بہادر شخص۔\n7. شمعیاہ سٕندِ نیٚچوۍ۔ عثنی، تہٕ رفائیل، تہٕ عوبید، الزاباد، یمۍ سٕندۍ بٲے ٲسۍ مضبوٗط انسان، ایلیہو تہٕ سماکیاہ۔\n8.\\tاوبیڈوم سٕندِ یِم سارِنٕے نیچوۍ: تِم تہٕ تِہٕندِ نیچوۍ تہٕ تِہٕندِ بٲے یِم خدمتہٕ خٲطرٕ طاقت حٲصِل کٔرِتھ ٲسۍ، تریہ تہٕ زٕ اوبیڈوم۔\n9.\\tتہٕ مشلیمیاہس ٲسۍ نیچوۍ تہٕ بٲے، مضبوط نفر، ارداہ۔\n10.\\tمراری ہٕندِس شُرِس منز زاے ہوشاہس نیچوۍ۔ سِمری سردار، (اگرچہِ} سُہ اوس نہٕ گۄڈنیُک زامُت، توتہِ اوس تٔمۍ سٕندِس مٲلہِ سُہ سردار؛)\n11.\\tحلکیا دۆیم، تیبلیاہ تریم تہ زکریا ژورم: ہوشہ سٕندِ سارِنٕے نیٚچوۍ تہٕ بٲے ٲسۍ ترہ وُہُر۔\n12.\\tیِمن مَنٛز ٲسۍ قُلٮ۪ن ہٕنز تقسیم، {حتیٰ کہ} بٔڈِس مَنٛز تہِ، {یِمَن} ہٕندِس گرس مَنٛز خدمت کرنہٕ خٲطرٕ۔\n13.\\tتہٕ تِمو کٔرِکھ پرٮ۪تھ دروازٕ خٲطرٕ، لۄکٕٹۍ تہٕ بٔڈۍ تہٕ بٔڈۍ تہِ۔ {تہِ...: یا، لۄکٹٮ۪ن تہٕ بڑٮ۪ن خٲطرٕ}\n14. تہٕ مشرقس کُن آو شیلیمیاہ کُن۔ اَمہِ پَتہٕ کٔرِو زکریا سٕندِس نیچوِس سٍتـ̡ یُس عقلمند مُشیر اوس، تِمو دِژ قرعہٕ۔ تہٕ تٔمۍ سُند لاٹ آو شمالس کُن۔ {شیلیمیاہ: یتھ مشیلمیاہ تہِ ونان چھہِ}\n15. اوبیڈیڈوم جنوبس کُن۔ تہٕ تٔمۍ سٕندٮ۪ن نیٚچوٮ۪ن ہُند گرٕ آسُپِم۔ {Asuppimp: Heb. اجتماع}\n16.\\tشوپیم تہٕ ہوشاہس کُن آو مغرب کُن، دروازہ شالچیتھ سٍتۍ، ہیوٚر کِس وتہِ سٍتۍ، وارڈس خلاف وارڈ۔\n17. مشرقس کُن ٲسۍ شیہ لاوی، شمالس کُن ژور دۅہہ، جنوبس کُن ژور دۅہس کُن، تہٕ آسوپیم کُن زٕ تہٕ زٕ۔\n18.\\tپربرس مغربس منز، ژور کاز وے پیٹھ، {تہٕ} زٕ پربرس پیٹھ۔\n19.\\tیِم چھِ کورے سٕندٮ۪ن نیچوٮ۪ن تہٕ میراری سٕندٮ۪ن نیچوٮ۪ن مَنٛز قُلٮ۪ن ہٕنز تقسیم۔\n20.\\tتہٕ لاوِین مَنٛز اوس احیجاہ خدایہ سٕندِس گرٕ کِس خزانس تہٕ مُقرر چیزن ہٕندِس خزانس پیٹھ۔ {وقف کٔرِتھ...: ہیب۔ مقدس چیز}\n21.\\t{یُس زن لادان سٕندِس نیچوِس متعلق چھُ}۔ گرشونائٹ لادان سٕنٛدۍ نیٚچوۍ، چیف فادر، {حتیٰ کہ} لادان دی گرشونائٹ، {ٲس} جہیلی۔ {لادن: لبنی تہِ ونان چھِ} {جہیلی: تہِ ونان چھِ، جہیل}\n22.\\tجہیلی سٕندِ نیٚچوۍ۔ زیتھم، تہٕ یوایل، تٔمۍ سُند بوے {یُس} خداوند سٕندِ گرٕ کِس خزانس پیٹھ۔\n23.\\tامرامی منز، تہٕ ازری، حبرونی، تہٕ عزیلٮن منز:\n24. تہٕ موسیٰ سُند نیچو گرشوم سُند نیچو شیبویل اوس خزانن ہُند حکمران۔\n25. تہٕ تٔمۍ سٕندِ بٲے الیعزر سٕندِ۔ رحبیاہ تٔمۍ سُند نیچو، تہٕ یشیعیاہ تٔمۍ سُند نیچو، تہٕ جورم سُند نیچو تہٕ زیکری تٔمۍ سُند نیچو تہٕ شیلومیت تٔمۍ سُند نیچو۔\n26.\\tیُس شیلومتھ تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ سارِنٕے خزانہٕ سٍتـ̡ وقف کٔرۍمٕتۍ، یُس ڈیوڈ بادشاہ تہٕ بٔڈۍ باپ، ساسہٕ بٔدۍ تہٕ ہتہٕ بٔدۍ کپتانن تہٕ میزبانن ہٕندِس کپتانن وقف کورمُت اوس۔\n27. جنگن مَنٛز زیننہٕ آمٕژ غنیمت مَنٛز کٔر تِمو خداوند سٕندِس گرس رژھراونہٕ خٲطرٕ وقف ۔ {غنیمت...: ہیب۔ جنگ تہٕ غنیمت}\n28.\\tتہٕ سُہ سورُے یُس سموئیل سُند نیچو، تہٕ کیش سُند نیچو ساؤل، تہٕ نیر سُند نیچو ابنیر تہٕ زرویاہ سُند نیچو یوآب اوس وقف کورمُت۔ {تہٕ} ییٚمۍ {کانٛہہ تہِ چیز وقف اوس کوٚرمُت، سُہ اوس شیلومتھ تہٕ تٔمۍ سٕنٛدٮ۪ن باین ہٕنٛدِس اتھس تل۔\n29.\\tاِحارِیو منز، چنانیاہ تہٕ تٔمۍ سٕندِس نیچوِس ٲسۍ اسرٲیلِس پیٹھ ظاہری کارٕبارٕ خٲطرٕ، افسرن تہٕ ججن ہٕندِ خٲطرٕ۔\n30.\\tحشبہ تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ ساس ستھ ہتھ سٍتـ̡ أسـ̡ اِسرٲیلٕکۍ افسر یێمہِ طرفہٕ یێمہِ طرفہٕ اردن کُن خداوند سٕندِس سارِنٕے کاروبارس مَنٛز، تہٕ بادشاہ سٕنزِ خدمتس مَنٛز۔ {افسر...: ہیب۔ اوور دی چارج}\n31.\\tہیبرونین مَنٛز اوس یریجہ سردار تہٕ پننین آباؤ اجدادن ہٕندِ نسلہٕ مطٲبق اوس یِریاہ سردار۔ داؤد سٕندِ دورِ حکومتہٕ کِس ژتٲجیمس ؤریس منز آیہ تِمن ہٕنز تلاش کرنہٕ، تہٕ یِمن منز آیہ جلعاد کِس جازرس منز بہادر نفر لبنہٕ۔\n32.\\tتہٕ تٔمۍ سٕندِ بٲے، بہادر شخص، ٲسۍ زٕ ساس ستھ ہتھ بٔڈۍ، یِمن بادشاہ داؤدن روبینین، گادِس تہٕ مناسی سٕندِس نصف قبیلس پیٹھ بادشاہ بنوو، خدایہ سٕندِس معاملس تہٕ بادشاہ سٕندِس معاملس مۅکھہٕ۔ {معاملہٕ: ہیب۔ چیز}","1.\\tوۅنۍ چھہِ اسرٲیلکۍ اولاد تہندِ تعدادس مطٲبق، ساسہٕ بٔدۍ تہٕ ہتن ہٕندِس کپتان، تہٕ تِہندِ افسر یِم بادشاہس کُنہِ تہِ معاملس مَنٛز خدمت کران ٲسۍ، یِم ؤری کین سارنٕے ریتن منز ریتہ پتہٕ ریتہٕ نیران ٲسۍ، پرٮ۪تھ کورسٕکۍ ٲسۍ وُہ تہٕ ژۅن ساس۔\n2.\\tگۅڈنِکِس ریتس مَنٛز اوس یشوبیم زبدیل سُند نیچو: تہٕ تٔمۍ سٕندِس طریقس مَنٛز اوس وُہ ژۅن ساس۔\n3. پیریز سٕندِ شُرین منزٕ اوس گۄڈنِکِس ریتس منز میزبانن ہٕندِس سارنٕے کپتانن ہُند سردار۔\n4.\\tتہٕ دۆیمِس ریتس دوران اوس دودایہ اکھ اہوہ، تہٕ تٔمۍ سٕندِس طریقس منز اوس مِکلوت تہِ حُکُمران تہِ: تٔمۍ سٕندِس طریقس مَنٛز ٲسۍ یِتھے پٲٹھۍ وُہ ژور ساس۔ {ڈوڈای: تہِ ونان ڈوڈو}\n5.\\tتریمہِ ریتس منز اوس میزبانُک تریم کپتان یہویادہ سُند نیچو بنیاہ یُس اکھ سردار پادٕرۍ اوس، تہٕ تٔمۍ سٕندِس دورس منز اوس وُہ ژۅن ساس۔ {چیف...: یا، پرنسپل آفیسر}\n6.\\tیہِ چھُ یہِ بنیاہ {یُس} یُس ترہن منز تہٕ ترہن ہٕندِس مَنٛز طاقتور اوس، تہٕ تٔمۍ سٕندِس طریقس مَنٛز اوس امی زاباد تٔمۍ سُند نیچو۔\n7.\\tژورمہِ ریتس منز اوس ژوُرِم {کپتان} یوآب سُند بوے اَساہیل تہٕ أمِس پتہٕ أمِس نیچو زبادیاہ تہٕ تٔمِس سٍتـ̡ وُہ ژۅن ساس ۔\n8.\\tپوٗنٛژمہِ ریتُک پٲنژِم کپتان اوس شمحوت عزراہی: تہٕ تٔمۍ سٕندِس طریقس مَنٛز اوس وُہ ژۅن ساس۔\n9.\\tشیمہِ ریتس منز اوس شییِم {کپتان} اِکیش سُند نیچو ایرا: تہٕ تٔمۍ سٕندِس دورس منز اوس وُہ ژۅن ساس۔\n10.\\tسٔتِم ریتس خٲطرٕ سٔتِم {کپتان} اوس ہیلیز پیلونائٹ، افرائیم سٕندٮ۪ن بچن منز: تہٕ تٔمۍ سٕندِس طریقس مَنٛز ٲس وُہ ژور ساس۔\n11.\\tٲٹھمہِ ریتس منز اوس ٲٹھمہِ ریتس منز سِبیکایی ہشتہتی، زرہین ہُند، تہٕ تٔمۍ سٕندِس طریقس مَنٛز ٲسۍ وُہ ژور ساس۔\n12. نٔوِمہِ ریتس خٲطرٕ اوس نٔوِم {کپتان} ابیزر انیتوتھی، بنیمیَن ہُند: تہٕ تٔمۍ سٕندِس طریقس مَنٛز ٲس وُہ تہٕ ژور ساس۔\n13.\\tدٔہمہِ ریتس خٲطرٕ اوس دٔہِم {کپتان} مہراے نیٹوفتھی، زرہِین ہُند: تہٕ تٔمۍ سٕندِس طریقس منز ٲسۍ وُہ ژور ساس۔\n14.\\tکاہمہِ ریتہٕ خٲطرٕ اوس کٔہِم {کپتان} افرایم سٕندٮ۪ن شُرین ہٕندِس نیعیاہ پیراتھونیٹ، تہٕ تٔمۍ سٕندِس دورس مَنٛز ٲس وُہ ژۅۅن ساس۔\n15.\\tبٔہِمہِ ریتس خٲطرٕ اوس بٔہِم {کپتان} ہیلڈای نیٹوفیتھی، اوتھنیلُک تہٕ تٔمۍ سٕندِس طریقس مَنٛز اوس وُہ ژور ساس۔ {ہیلڈای: ہیلڈ تہِ ونان چھِ}\n16.\\tاَمہِ علاوٕ چُھہ اِسرٲیلؠن ہٕندِس قبیلس مُتلِق: روبینیَن ہُند حُکُمران اوس زِکری سُند نیٚچُو: سِمیونیَن ہُند تہٕ شیفطیہ سُند نیچو۔\n17.\\tلاوِین مَنٛز حشبیاہ کموئیل سُند نیچو: ہارونیوں سٍتـ̡ زادوک:\n18.\\tیہوداہ، ایلیہو، داؤد سٕندِس بٲے سٍتـ̡ {اَکھ ﴿اِسخر﴾ عُمری، میکائیل سُند نیٚچُو: {ایلیہو: تہِ وَننہٕ یِوان، الیاب}\n19.\\tزبلون سُند نیچو اسماعیاہ: نفتالی سُند، عزرییل سُند نیچو یرموت:\n20.\\tافرائیم سٕندِس اولادس منز، ہوشعہ سُند نیچو عززیاہ سُند نیچو۔\n21.\\tگلعادس مَنٛز منسیٰ سٕندِس نصف قبیلس منز، زکریا سُند نیچو اِدو: بنیامین سُند، یعقوبیل سُند نیچو:\n22. دان، عزریل، یروہم سُند نیچو۔ یِم ٲسۍ اسرٲیلِک قبیلہٕ ہٕندِ شہزادٕ۔\n23.\\tمگر داؤدس ہیوٚت نہٕ تِمن ہُند تعداد وُہن ؤرین تہٕ امہِ کھوتہٕ کم وٲنسہِ، تکیازِ خداوند اوس ووٚنمُت زِ سُہ کرِ اسرٲیلِس آسمانن ہٕندِس ستارن ہٕندۍ پٲٹھۍ۔\n24.\\tزریاہ سُند نیچو یوآب ہیوٚتُن گنزراونہٕ مگر تٔمِس ہیوٚت نہٕ، تکیازِ اِسرٲیلِس سٍتـ̡ ووت أمِس سٍتـ̡ غصہٕ۔ نہ اوس یہ نمبر بادشاہ ڈیوڈ سٕندِس تواریخس منز دراونہٕ آمُت۔ {اوس: ہیب۔ کھسُن}\n25.\\tتہٕ بادشاہ سٕندِس خزانس پیٹھ اوس عدیل سُند نیچو عزماوتھ تہٕ کھہَن مَنٛز، شہرن مَنٛز، گامن تہٕ قلعن مَنٛز ذخیرٕ خانن پیٹھ، عزیاہ سُند نیچو یہوناتھن:\n26.\\tتہٕ یِمن پیٹھ یُس زمینہٕ کھٲلنہٕ خٲطرٕ کٲم کٔرِتھ اوس، سُہ اوس چیلوب سُند نیچو۔\n27.\\tتہٕ انگور کِس باغس پیٹھ اوس شمی رماتھیت: شراب خانہٕ خٲطرٕ انگورن ہٕندِس باغن ہٕندِس اضافس پیٹھ {اوس} زبدی شِفمائٹ: {زیادٕ اضافہٕ...: حب۔ تتھ پیٹھ یُس انگورن ہند اوس}\n28.\\tتہٕ زیتون کُلٮ۪ن تہٕ کُلٮ۪ن پیٹھ یِم {ٲس} بٔنِم مٲدانن مَنٛز {ٲس} بعلحنان گیدِرِٹ: تہٕ تیلٕکِس تہٕ تہٕ تیٖلٕکِس تہٕ تہٕ تِمن ہٕندِس تہٕ کُلِس پیٹھ۔\n29.\\tتہٕ یِمن ریوڑن پیٹھ یُس شیرونس مَنٛز کھٮ۪وان اوس، شِتراے شیرونی: تہٕ وادی مَنٛز یِمن ہٕندِس ریوڑس پیٹھ {اوس} شفعت یُس عدلائی سُند نیچو اوس:\n30.\\tاونٹَن پیٹھ تہِ اوس اوبیل اسماعیلِی: تہٕ گَرَن پیٹھ اوس یہدیاہ میرونوتھی:\n31.\\tتہٕ ریوڑن پیٹھ اوس جازِز ہجرِیت۔ یم سٲری ٲسۍ تمہ مادک حکمران یُس {اوس}بادشاہ ڈیوڈ سُند۔\n32.\\tتہِ اوس جوناتھن ڈیوڈ سُند پیٚتٕر مُشیر، اکھ دانشمند تہٕ کاتب: تہٕ جہیل، ہچمونی سُند نیچو اوس بادشاہ سٕندِس نیچوِس سٍتۍ: {کاتب: یا، سیکرٹری} {نیچو...: یا، ہخمونیت}\n33.\\tتہٕ اہیتھوفیل اوس بادشاہ سُند مُشیر: تہٕ ہوشایی آرکائیٹ اوس بادشاہ سُند سٲتھی:\n34.\\tتہٕ احیتھوفیل سٕندِ پَتہٕ اوس یہوعیدا بنیاہ سُند نیچو، تہٕ ابیاتھر: تہٕ بادشاہ سٕندِس فوجُک سپاہ اوس یوآب۔","1. تہٕ داؤد کٔر اسرٲیلٕکۍ سٲری شہزادٕ، قبیلن ہٕندِ شہزادٕ تہٕ بادشاہس سٍتـ̡ خدمت کرن واجنہِ کمپنیہِ ہٕندِس کپتان، تہٕ ساسہٕ بٔدۍ کپتان، تہٕ بادشاہ سٕندِس سارِنٕے چیزس تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡  تہٕ طاقتور نفرن سٍتۍ، تہٕ سارنٕے بہادر نفرن سٍتۍ، یروشلمس تام۔ {قبضہ: یا، مویشی} {تہٕ ...: یا، تہٕ تٔمۍ سٕندۍ نیچو} {افسر: یا، خواجہ سرا}\n2. اَمہِ پَتہٕ ووٚتھ داؤد بادشاہ پننِس قدمن پیٹھ، تہٕ وونُن، بوزو، میانیو بٲے تہٕ میانہِ لوکو: {یێلہِ} بہٕ اوسُس پننِس دِلس مَنٛز خداوند سٕندِ عہد کِس صندوقس تہٕ سانہِ خدایہ سٕندِ قدمن ہٕندِ خٲطرٕ آرام کرنُک مکانہٕ تعمیر کرُن، تہٕ اوسُس عمارتہٕ خٲطرٕ تیار۔\n3.\\tمگر خداین ووٚن میہ زِ ژے کٔرِکھ نہٕ میانہِ ناوٕ خٲطرٕ مکانہٕ بَناوُن، تِکیازِ ژے چھُکھ جنگی شخص، تہٕ کورُکھ خون۔ {خون: ہیب۔ بلڈز}\n4. توتہِ چُھ میہ پننِس مٲلہِ سٕندِس سارِنٕے گرس برونہہ کُن اسرٲیلُک بادشاہ بننہٕ خٲطرٕ ژٲرمُت، تکیازِ تٔمۍ چُھ یہوداہ بادشاہ بننہٕ خٲطرٕ ژٲرمُت۔ تہٕ یہوداہ کِس گرس منز، میٲنس مٲل سُند گرٕ؛ تہٕ میٲنِس مٲلہِ سٕندٮ۪ن نیٚچوٮ۪ن مَنٛز اوس سُہ خۅش کران زِ بہٕ بناوُن سارِنٕے اسرٲیلُک بادشاہ۔\n5. تہٕ میانیو سارِنٕے نیٚچویو منزٕ چُھہ (یێلہِ خداوند سٕندِ بادشاہی ہٕندِس تختس پیٹھ بِہنہٕ خٲطرٕ چُھہ سُلیمانُک نیچو منتخب کورمُت۔\n6. تہٕ تٔمۍ ووٚن مے، سُلیمان، تُہند نیچو، سُہ بناوِ میون گرٕ تہٕ میٲنۍ دربار، کیازِ مے چُھس سُہ پنُن نیچو بننہٕ خٲطرٕ منتخب کورمُت، تہٕ بہٕ بنہٕ تٔمۍ سُند مول۔\n7. اَمہِ علاوٕ کَرٕ بہٕ تٔمۍ سٕنز بادشٲہی ہمیشہٕ خٲطرٕ قٲیِم، یێلہِ سُہ میٲنۍ حُکمن تہٕ میٲنۍ فٲصلن ہٕندِس دٲیرس پیٹھ ثابت روزِ۔ {مستقل: ہیب۔ مضبوط}\n8. تێمہِ وۆنـ̡ سارِنٕے اسرٲیلـ̡ ہٕندِس نظرس مَنٛز، خداوند سٕنزِ جماعت تہٕ سٲنـ̡ خدایہِ سٕندِس سامعینَس مَنٛز، خداوند پَنٕنـ̡ خدایہِ سٕندِس سارِنٕے حُکمن ہٕندِس سٍتـ̡ رٔٹِتھ تہٕ ژھٲرِو، یُتھ تُہٕندِس اَصٕل زمینس حٲصِل کٔرِو، تہٕ یێلہِ پَنٕنـ̡ پَنٕنـ̡ شُرین ہٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ وَراونہٕ یِنـ̡ ۔\n9. تہٕ ژے چُھہ پننِس مٲلہِ سُند خدا زانان تہٕ کامل دِلہٕ سٍتـ̡ تہٕ رضامندی سٍتـ̡ أمِس سٍتـ̡ عبادت کٔرِتھ، تکیازِ خداوند چُھ سارنٕے دلن ہٕنز تلاش کران، تہٕ خیالن ہٕندِس سارِنٕے خیالن سٍتـ̡ پى۪ٹھ مگر اگر ژے أمِس ترٛٲوِو، سُہ کٔرِو ژےٚ ہمیشہٕ خٲطرٕ دِنہٕ۔\n10. وۅنۍ کرو دھیان کیازِکہ خداوند چُھ ژے مقدس مقامہٕ خٲطرٕ اکھ مکانہٕ بناونہٕ خٲطرٕ منتخب کوٚرمُت: مضبوٗط روزُن، تہٕ کرُن {یہ}۔\n11. پتہٕ دیت ڈیوڈس سُلیمانس پننِس نیچوِس برآمدُک تہٕ اَمہِ کِس خانن ہُند تہٕ اَمہِ کِس پیٹھمہِ خانن ہُند تہٕ اَمہِ ہٕندِس أنٛدرِمِس پارلرن ہُند تہٕ رحمتٕچ جاۓ ہُند نمونہٕ۔\n12. تہٕ یُس تٔمِس سٍتـ̡ روحہٕ سٍتـ̡ اوس، خداوند سٕندِ گرٕ ہٕندِس دربارس منز، تہٕ اندۍ پٔکۍ سارِنٕے خانن ہٕندِ، خدایہ سٕندِ گرٕ ہٕندِس خزانہٕ تہٕ وقف چیزن ہٕندِس خزانن ہُند نمونہٕ: {تِمن سارِنٕے چیزن ہُند...: حب۔ تمن سارِنٕے چیٖزن ہُنٛد یُس أمس سۭتۍ اوس}\n13. پادٕرین تہٕ لاوِین ہٕنزِ خدمتہٕ خٲطرٕ، تہٕ خداوند سٕندِس گرس مَنٛز خدمتہٕ کِس سارِنٕے کامہِ خٲطرٕ۔\n14. {تٔمۍ دِیُت} سۄنہٕ سٕندِس وزنس سٍتـ̡ ، پرٮ۪تھ قٕسمٕچ خدمتہٕ کِس سارِنٕے آلاتَن خٲطرٕ۔ {رۄپہٕ تہِ} رۄپہٕ کیٚن سارنٕے آلاتن خٲطرٕ، پرٮ۪تھ قٕسمٕچ خدمتہٕ کیٚن سارنٕے آلاتن خٲطرٕ:\n15.\\tسۅنہٕ سٕندِس شمعہٕ سٕندِ خٲطرٕ تہٕ تِمن ہٕندِس شمعہٕ سٕندِ خٲطرٕ تہٕ تِمن ہٕندِس شمعہٕ سٕندِ خٲطرٕ تہٕ تِمن ہٕندِس شمعہٕ سٕندِ خٲطرٕ تہٕ پرٮ۪تھ شمعدان ہٕندِ ورتاوٕ مُطٲبق تہٕ رۄپہٕ سٕندِ شمعہٕ خٲطرٕ تہٕ شمعدان ہٕندِ خٲطرٕ تہٕ پرٮ۪تھ شمعدان ہٕندِ استعمالہٕ مُطٲبق چُھ شمعہٕ سٕندِ خٲطرٕ۔\n16. تہٕ وزنٕ سٍتـ̡ دِژُن سۄن، پرٮ۪تھ کُنہِ میزہٕ خٲطرٕ۔ تہٕ {یِتھے پٲٹھۍ}رۄپہٕ ہٕندِ ٹیبلن خٲطرٕ رۄپہٕ:\n17.\\tخالص سون تہٕ پیالہ تہٕ پیالہ تہٕ سۅنہٕ بیسن خٲطرٕ تہٕ دِژ سۄنہٕ سٍتـ̡ پرٮ۪تھ کُنہِ بیسنس خٲطرٕ وزن۔ تہٕ {یتھے پٲٹھۍ رۄپہٕ} رۄپہٕ کِس پرٮ۪تھ بیسنس خٲطرٕ وزنہٕ لحاظہٕ:\n18.\\tتہٕ اگربتی ہٕندِس قربان گاہٕ خٲطرٕ، وزن سٍتـ̡ سۄنہٕ صاف کرنہٕ آمُت۔ تہٕ سۄنہٕ کروبن ہٕندِ رتھٕکۍ نمونہٕ خٲطرٕ، یُس پکھہٕ پھٔہلِتھ تہٕ خداوند سٕندِ عہد کِس صندوقس ؤلِتھ اوس۔\n19.\\tیہ سورُے {یہِ، داؤد وۆن}، خداوند دیت میہ لیکھِتھ اتھ نمونہ چہ سارنٕے کامہِ سٍتـ̡ سٍتـ̡ سمجھ۔\n20. تہٕ داؤد ووٚن پننِس نیچوِس سُلیمانس زِ مضبوط تہٕ ہمت تھاوُن، تہٕ کرُن: خوفزدہ گژھ نہٕ تہٕ نہ گژھ خوفزدٕ، یُس خداوند خدا، {حتی} میون خدا، {آسہِ} تہٕ آسہِ توے سٍتـ̡ ۔ سُہ کرِ نہٕ تۅہہِ ناکام تہٕ نہ تراوُن، یوتام نہٕ ژے خداوند سٕنزِ گرٕ سٕنزِ خدمتہٕ خٲطرٕ تمام کٲم مُکمل کرِ۔\n21. تہٕ وُچھِو، پادٕرین تہٕ لاوِین ہٕنزِ وتہٕ، {تِم تہِ آسن توے سٍتـ̡ خدایہِ سٕندِس گرٕ سٕنزِ سارِنٕے خدمتہٕ خٲطرٕ﴾ تہٕ {اَتہِ آسہِ} پرٮ۪تھ قٕسمٕچ کامہِ خٲطرٕ پرٮ۪تھ کُنہِ تہِ قٕسمٕچ کامہِ خٲطرٕ تہٕ کُنہِ تہِ قٕسمٕچ خدمتہٕ خٲطرٕ، تہٕ شہزادٕ تہٕ سارِنٕے لوٗکھ تہٕ آسن تُہندِ حُکمس مُطٲبق۔","1. اَمہِ علاوٕ ووٚن داؤد بادشاہن سارنٕے جمٲژ سٍتـ̡، سُلیمان میون نیچو، یُس صرف خداین چُھ ژٲرمُت، {چُھہ} جوان تہٕ نرم تہٕ کٲم {چُھ} عظیم: محل {چُھ} نہٕ انسانہٕ سٕندِ خٲطرٕ، بٔلکہِ خداوند خدا سٕندِ خٲطرٕ۔\n2. وۅنۍ چُھس میہ پننہِ خدایہ سٕندِ گرٕ خٲطرٕ سۄنہٕ سٍتـ̡ پى۪ٹھـ̡ اونکس کن، تہٕ {کن} گژھن سیٹ کرنہٕ، چمکدار کن، تہٕ مختلف رنگن ہٕنٛز، تہٕ پرتھ قسمک قیمتی کن، تہٕ سنگ مرمر کن۔\n3. امہِ علاوٕ، کیازِ میہ چُھ پنُن محبت پننِس خدایہ سٕندِس گرس سٍتـ̡ قایم کورمُت، تێلہِ چُھہ میہ پننہِ خدایہ سٕندِس گرس سٍتـ̡ دِژمُت، یُس میہ مقدس گرٕ خٲطرٕ تیار کورمُت چُھ،\n4. {حتیٰ کہ} ترے ساس ٹیلنٹ سۄن، اوفیر سٕندِ سۄنہٕ سٍتۍ، تہٕ سَتھ ساس رۄپہٕ سٕندِس سٍتـ̡ گَرَن ہٕندِس دیوارس سٍتـ̡ سٍتـ̡\n5. سۄنہٕ سٕندِ {چیزن} خٲطرٕ، تہٕ رۄپہٕ {چیزن} خٲطرٕ، تہٕ پرٮ۪تھ قٕسمٕچ کامہِ خٲطرٕ۔ تہٕ کُس چُھ از دۅہہ پنٕنۍ خدمت خداوند سٕندِ خٲطرٕ وقف کرنہٕ خٲطرٕ تیار؟ {تٔمۍ سٕنز خدمت مقدس کرو: ہیب۔ امۍ سند اتھہ بٔرتھ}\n6.\\tاَمہِ پَتہٕ کٔر اِسرٲیلٕکۍ قبیلن ہٕندِس مٲلن تہٕ شہزادن ہٕندِس سردارس تہٕ ساسہٕ بٔدۍ تہٕ ہتہٕ بٔدۍ کپتان، بادشاہ سٕنزِ کامہِ ہٕندِس حکمرانن سٍتـ̡ دِژ پننہِ مرضی سٍتـ̡ پیشکش،\n7.\\tتہٕ دیتُن خدایہ سٕندِ گرٕ سٕنزِ خدمتہٕ خٲطرٕ پانژھ ساس ٹیلنٹ تہٕ داہ ساس ڈرم، تہٕ رۄپہٕ سٕندِ دَہ ساس ٹیلنٹ تہٕ پیتل ہٕندِ ارداہ ساس ٹیلنٹ تہٕ اکھ لچھ ٹیلنٹ ششتٕر۔\n8. تہٕ یِمن نِش {قیمتی} کٔنہِ لبنہٕ آو، تِمو دِژ خداوند سٕندِس گرٕ کِس خزانہٕ سٍتـ̡ یہیل گرشونی سٕندِ اتھہٕ سٍتـ̡۔\n9. اَمہِ مۅکھہٕ کٔر لُکھ خۅش، تِکیازِ تِمو کٔر کامل دِلہٕ سٍتـ̡ خداہس سٍتـ̡ خوشی سان پیش کرنہٕ، تہٕ داؤد بادشاہ تہِ کٔر سٮ۪ٹھاہ خوشی سان خۅش۔\n10.\\tتێلہِ کٔر داؤدُن سارِنٕے جمٲژ برونہہ کُن خداوند سٕنز برکت، تہٕ داؤدَن وۆنُن، بابرکت آسُن، اسرٲیلُک خدا، سٲنـ̡ باپ، ہمیشہٕ ہمیشہ خٲطرٕ۔\n11. اے خداوند، تُہُند عظمت، تہٕ طاقت، تہٕ عظمت، فتح، تہٕ عظمت، یُس اسمانس تہٕ زمینس مَنٛز چُھہ تُہُند {چُھ}؛ اے خداوند، تہٕ تُہۍ چُھکھ سارِوٕے کھۄتہٕ تھوٚد کَلہٕ سٍتـ̡ تھزر۔\n12. دۅشوے دولت تہٕ عزت، تہٕ تُہۍ چھِو سارِنٕے پٲٹھـ̡ بادشاہت کٔرِتھ۔ تہٕ تُہندس اتھس منز چُھ طاقت تہٕ طاقت؛ تہٕ پننِس اتھس مَنٛز چُھہ عظیم بناوُن، تہٕ سارِنٕے ہٕندِس طاقت دِنہٕ خٲطرٕ۔\n13. تێمہِ وۆن، سانہِ خدا، أسۍ چُھہ تُہند شُکر ادا کران تہٕ تُہٕندِس شاندار ناوٕچ حمد کران۔\n14.\\tمگر بہٕ کُس چھُس، تہٕ میانین لوکن کیا چھُ، یُس اسہِ یژھ مرضی سان پیش کرُن؟ سارِنٕے چیزن خٲطرٕ، تہٕ تۅہہِ سٍتـ̡ چُھہ ژے دِژمُت۔ {قٲبل: ہیب۔ برقرار تھاوُن، یا طاقت حٲصل کرُن} {تُہند ...: ہیب۔ تُہٕندِس اتھس منز}\n15. تکیازِ أسۍ چھہِ ژے برونہہ کنہِ اجنبی تہٕ روزان روزان چھہِ، یتھے پاٹھۍ چھہِ سانین سارِنٕے بابن ہندۍ پٲٹھۍ: زمینس پیٹھ چھہِ سانۍ دۅہ ژھایہ ہیو تہ کانہہ تہِ چھُنہ۔ {پابندی: ہیب۔ توقع}\n16. اے خداوند سانہِ خدایہ، یہ سورُے ذخیرٕ یُس أسۍ چانہِ مقدس ناوٕ خٲطرٕ اکھ مکانہ بناونہٕ خٲطرٕ تیار کورمُت چُھ، تہٕ {چُھ} چُھہ تُہند پنُن۔\n17. بہٕ چُھس یہ تہِ زانان زِ ژے چُھکھ دِل آزماوان، تہٕ چُھس دِلس سٍتـ̡ خوش گٔژھان۔ یوٚتام میانہِ دِل کِس سیدِ پٲٹھۍ، مے چھِ پننہ مرضی سان یِم سٲری چیز پیش کٔرۍمٕتۍ: تہٕ وۄنۍ وُچھمُت تُہند لوکھ یِم یتہِ موجود چھِ، تۅہہِ پننہِ مرضی سان پیش کرنہٕ خٲطرٕ۔ {موجود: ہیب۔ لٔب}\n18.\\tاے ابراہیم، اسحاق تہٕ اسرٲیلُک خدا، سانٮ۪و آباؤ اجداد، یہِ تھاوُن پننہِ لوکن ہٕندِس دِلٕکِس خیالس مَنٛز ہمیشہٕ خٲطرٕ تہٕ تِہُند دِل پانس خٲطرٕ تیار: {تیار: یا، قایم کرُن}\n19. تہٕ دِیُن میٲنِس نیچوِس سُلیمانس اکھ کامل دِل، چانہِ حکم، پنٕنۍ گوٲہی تہٕ پنٕنۍ قوانین، تہٕ یِم سارِنٕے کامہِ کٔرِتھ تہٕ محل تعمیر کرنہٕ خٲطرٕ، یُس مے دِژمُت چھُ۔\n20. تہٕ داؤدَن ووٚن سارِنٕے جمٲژ سٍتـ̡ وۆن، وۅنۍ کٔرِو خداوند پنُن خدا۔ تہٕ سارِوٕے جمٲژ کٔر پننین مٲلن ہٕندِس خداہس برکت تہٕ کلہٕ نٔمِتھ تہٕ کٔرٕکھ خداوند تہٕ بادشاہس پوٗزا کرنہٕ۔\n21. تہٕ تِمو کٔرٕکھ خداوند سٕندِ خٲطرٕ قربانی تہٕ دِژٕکھ خدایہِ سٕندِ خٲطرٕ زٲلِتھ نذرانہ پیش کرنہٕ، یێمہِ دۅہہٕ پَتہٕ کٔرٕکھ ساس بیل، اکھ ساس کۅکر، تہٕ سارنٕے اسرٲیلِس خٲطرٕ کٔرٕکھ ساس بیل، اکھ ساس کۅکرِ تہٕ ساس کۅکرِ تہٕ سارنٕے اسرٲیلِس خٲطرٕ کثرت سان قربانی۔\n22. تہٕ کٔرٕن اَمہِ دۅہہٕ سٮ۪ٹھاہ خوشی سان خداوند سٕندِ برونہہ کُن کھٮ۪وان تہٕ چیوٚو۔ تہٕ تِمو بنوو سُلیمان داؤد سُند نیچو دوٚیمہِ لٹہِ بادشاہ، تہٕ سُہ کوٚرُکھ خداوند سٕندِس خٲطرٕ مسح کرنہٕ آمُت، تہٕ زادوک کٔرِکھ پادٕر۔\n23. اَمہِ پَتہٕ بیٛوٗٹھ سُلیمان پَنٕنِس مٲلِس داؤد سٕندِ بدلہٕ بادشاہ سٕندِس تختس پیٹھ، تہٕ سپُد ترقی۔ تہٕ سارِوٕے اسرٲیلَن کٔر أمِس فرمانبردار۔\n24.\\tتہٕ سارِوٕے شہزادو تہٕ طاقتور مرد تہٕ بادشاہ داؤد سٕندِس سارِنٕے نیچویو کٔر پنُن پان سُلیمان بادشاہس سٍتـ̡ تابع۔ {سبمِٹڈ...: ہیب۔ دِژ سُلیمانس تل اتھہٕ}\n25. تہٕ خداوند کٔر سُلیمانس سارِنٕے اسرٲیلِس مَنٛز سٮ۪ٹھاہ بٔڈِتھ تہٕ دِتُن أمِس سٍتـ̡ شٲہی عظمت یُس نہٕ تس برونہہ کُنہِ تہِ بادشاہس سٍتـ̡ اوس نہٕ آمُت۔\n26. یِتھٕ پٲٹھـ̡ کٔر یسیٰ سُند نیچو داؤد سارِنٕے اسرٲیلس پیٹھ حکومت۔\n27. تہٕ یُس وقت تٔمۍ اسرائیلس پیٹھ حکومت کٔر، سُہ اوس ژتٲجی ؤری۔ سَتھ ؤرین کٔر تٔمۍ ہیبرونس مَنٛز حکومت، تہٕ ترٕہ تریہ ؤرین کٔر یروشلمس مَنٛز حکومت۔\n28. تہٕ سُہ موٗد أکِس اصل بُزرگس منز، دۅہہ، دولت تہٕ عزتہٕ سٍتـ̡ بٔرِتھ، تہٕ سُلیمانن کٔر تٔمۍ سٕندِ بدلہٕ بادشاہ۔\n29.\\tوۅنۍ چھہ داؤد بادشاہ سٕنزِ اعمال، گۅڈنچہ تہٕ ٲخری کتابہِ مَنٛز، یِم چھِ سموئیل سٕنزِ کتابہِ مَنٛز، تہٕ ناتھن نبی سٕنزِ کتابہِ مَنٛز، تہٕ گاد سٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ، {کتاب: یا، تٲریخ: حب۔ لفظ}\n30.\\tپننہِ سارِنٕے بادشاہت تہٕ طاقتہٕ سٍتـ̡ تہٕ یُس زمانہٕ أمِس پیٹھ تہٕ اسرٲیلِس پیٹھ تہٕ سارنٕے ملکن ہٕنزِ سلطنتن پى۪ٹھ گۆو سٍتـ̡ ۔"];
